SELECT 'moj-all-verified-judgments-review-002-chunk-110' AS batch_name,
       (SELECT count(*) FROM public.legal_documents WHERE id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"72b35c0d-1e27-5125-9228-7b4e529b20f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب باستخدام عصا خشبية -ضرب أفضى إلى املوت -قتل شبه عمد -دعوى عامة وخاصة -االستئناس برأي أهل اخلبرة يف ثبوت الدعوى من عدمها «تقرير طبي شرعي» -يشترط لثبوت اجلناية ثبوت قيام العالقة السببية بن الفعل واجلناية-رد دعوى املدعى العام .","document_number":"34250164","case_number":"3018918","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"اعتداء -ضرب -ضرب باستخدام عصا خشبية -ضرب أفضى إلى املوت -قتل شبه عمد -دعوى عامة وخاصة -االستئناس برأي أهل اخلبرة يف ثبوت الدعوى من عدمها «تقرير طبي شرعي» -يشترط لثبوت اجلناية ثبوت قيام العالقة السببية بن الفعل واجلناية-رد دعوى املدعى العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                 ‫رقم الصك ‪ 34250164 :‬تاريخه‪:‬‬\n       ‫رقم الدعوى‪3018918:‬‬      ‫‪1434/06/24‬هـ‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34283702‬تاريخه‪1434/7/30 :‬هـ‬\n\n\n    ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب باســتخدام عصــا خشــبية ‪ -‬ضــرب أفضــى إلــى‬\n    ‫املــوت ‪ -‬قتــل شــبه عمــد‪ -‬دعــوى عامــة وخاصــة ‪ -‬االســتئناس بــرأي أهــل‬\n    ‫اخلبــرة يف ثبــوت الدعــوى مــن عدمهــا «تقريــر طبــي شــرعي» ‪-‬يشــترط‬\n    ‫لثبــوت اجلنايــة ثبــوت قيــام العالقــة الســببية بــن الفعــل واجلنايــة‪-‬رد‬\n                                                          ‫دعــوى املدعــى العــام ‪.‬‬\n\n\n\n\n                                        ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n    ‫أقــام املدعــي اخلــاص دعــوى ضــد املدعــى عليــه بحصــول مضاربــة بينــه‬\n    ‫وبــن مورثــه ‪ -‬ابنــه ‪-‬وأنــه قــام بضربــه بعصــا علــى رأســه أدت لوفاتــه‬\n    ‫ويطلــب احلكــم عليــه بدفــع نصيبــه مــن دية شــبه العمد املقــدرة بأربعمئة‬\n    ‫ألــف ريــال عليــه فيكــون نصيبــه منهــا مئتــن وســتني ألفــا وســتمئة وســتة‬\n    ‫وســتني ريــاال وســتة وســتني هللــة ‪،‬أقــر املدعــى عليــه بحصــول املضاربــة‬\n    ‫وأنــه تنــاول العصــا وأهــوى بهــا علــى مورثــه إال أن مورثــه متكــن مــن‬\n    ‫صدهــا بيــده ولــم تصبــه بــأذى ‪ ،‬ورد بتقريــر الطبيــب الشــرعي عــدم‬\n    ‫تعــرض املتوفــى ألي ضــرب يف أي موضــع مــن جســده وأنــه ظهــر مــن‬\n    ‫تشــريح اجلثــة وجــود حالــة مرضيــة مزمنــة متقدمــة بالقلــب وشــرايينه‬\n\n‫‪5‬‬\n\f‫أدت لتضخــم القلــب مصحــوب بتصلــب عصيــدي شــديد مــع انســداد يف‬\n‫محيــط الشــريان التاجــي لــذا فــإن وفاتــه تعــزى حلالتــه املرضيــة التــي أدت‬\n‫لتوقــف القلــب والتنفــس نتيجــة نقــص شــديد يف ترويــة عضلــة القلــب ‪،‬‬\n‫كمــا جــرى إفهــام املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه‬\n‫فطلــب ميينــه‪ ،‬فحلــف املدعــى عليــه اليمــن املطلوبــة‪ ،‬لــذا فقــد قــررت‬\n‫احملكمــة صــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه‬\n‫‪،‬وبعــرض احلكــم علــى املدعــي قــرر القناعــة ‪،‬وأقــام املدعــي العــام علــى‬\n‫املدعــى عليــه دعــوى بأنــه جــرى توجيــه االتهــام لــه بقيامــه بقتــل الغيــر‬\n‫شــبه عمــد بضربــه بعصــا خشــبية وطلــب إثبــات مــا أســند إليــه وتطبيــق‬\n‫مقتضــى اإلرادة امللكيــة ‪،‬أنكــر املدعــى عليــه تســببه يف قتــل املتوفــى‬\n‫‪،‬وإلنــكار املدعــى عليــه ولعــدم قيــام البينــة املوصلــة علــى الدعــوى‬\n‫وملــا تضمنــه التقريــر الطبــي مــن اإلشــارة بــأن ســبب الوفــاة يعــود حلالتــه‬\n‫املرضيــة ‪ -‬لــذا فقــد انتهــت احملكمــة إلــى عــدم ثبــوت تســبب املدعــى‬\n‫عليــه بالوفــاة ال عمــد ًا وال شــبهة وال خطــأ وقــررت صــرف النظــر عــن‬\n‫دعــوى املدعــي العــام وأخلــت ســبيله مــن الدعــوى ‪،‬بعــرض احلكــم علــى‬\n‫املدعــي العــام قــرر عــدم القناعــة وطلــب تدقيقــه بــدون الئحــة ‪،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1430/02/27‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪ 1430/02/27‬هـ ففي يوم الثالثاء املوافق‪1434/06/06‬‬\n\n                                                                                       ‫‪6‬‬\n\f    ‫ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬وفيهــا حضــر ‪...........‬أردنــي اجلنســية‬\n    ‫مبوجــب رخصــة إقامــة رقــم ‪...........‬وادعــى علــى احلاضــر معــه ‪...........‬‬\n    ‫بنجالديشــي اجلنســية مبوجــب رخصــة إقامــة رقــم ‪...........‬قائــا يف‬\n    ‫دعــواه أن هــذا احلاضــر ‪...........‬حصلــت بينــه وبــن ابنــي ‪...........‬مضاربــة‬\n    ‫يف ‪1429/9/22‬ه ـ فقــام بضــرب ابنــي بعصــا وتــويف ابنــي نتيجــة لذلــك‬\n    ‫وقــد انحصــر ارث ابنــي يف أنــا والــده ويف والدتــه ‪ ...........‬مبوجــب صــك‬\n    ‫اإلرث الصــادر مــن احملكمــة العامــة برقــم‪...........‬يف ‪1433/1/30‬هـ ـ‬\n    ‫فقــط وجنايــة علــى ابنــي مــن قبيــل شــبه العمــد اطلــب منكــم احلكــم‬\n    ‫عليــه بتســليمي نصيبــي مــن ديــة قتــل شــبه العمــد حيــث أن ديــة شــبه‬\n    ‫العمــد أربعمائــة ألــف ريــال ونصيبــي منهــا مئتــن وســتني الفــا وســتمائة‬\n    ‫وســتة وســتني رياال وســته وســتني هلله(‪)266666,6‬هذه دعواي وبعرض‬\n    ‫دعــوى املدعــي ‪...........‬علــى املدعــى عليــه ‪...........‬اجــاب بلســان عربــي‬\n    ‫قائــا إنــه حصلــت بينــي وبــن ابــن املدعــي ‪...........‬مضاربــة فأخــذت‬\n    ‫عصــا ملــا ضربنــي أردت ضربــه بهــا ورفعتهــا وأهويــت بهــا عليــه فقــام‬\n    ‫مبســكها منــي أثنــاء رفعهــا ولــم أصبــه بــأي ضــرب وقــد جــاء آخــر‬\n    ‫ســعودي فضربنــي ولــم يحصــل منــي أي ضــرب ألحــد هكــذا أجــاب‬\n    ‫وبعــرض جوابــه علــى املدعــي قــال إن املدعــى عليــه ضــرب ابنــي وعنــدي‬\n    ‫بينــه وبينتــي احلاضــر املضاربــة ‪...........‬اطلــب رفــع اجللســة إلحضــاره‬\n    ‫ورفعــت اجللســة لذلــك وحــددت لهمــا موعــد ًا هــو يــوم األربعــاء املوافــق‬\n    ‫‪1434/6/14‬هـ ـ الســاعة الثامنــة والنصــف وعلــى مــا ذكــر حصــل‬\n    ‫التوقيــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/06‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/06/14‬ه ـ‬\n\n\n‫‪7‬‬\n\f‫افتتحــت اجللسةالســاعة‪9‬وفيها حضــر املدعــي ‪...........‬واملدعــى عليــه‬\n‫‪...........‬وقــد احضــر املدعــي معــه ‪...........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...........‬وبســؤال احلاضــر ‪...........‬عمــا لديــه مــن‬\n‫شــهادة كنــت أنــا وصديقــي ‪...........‬رحمــة اهلل عليــه راجعــن إلــى منــزل‬\n‫‪...........‬وكنــا نــود الســحور ووقفنــا أمــام منــزل ‪...........‬ولــم جنــد موقفـ ًا‬\n‫للســيارة ووقفنــا خلــف الســيارات ونزلنــا ومعنــا الســحور وجدنــا البنقالي‬\n‫املدعــى عليــه هــذا احلاضــر أمــام مطعمــه فتوجهنــا إليه ووجه إليه ســؤال‬\n‫وقــال ملــاذا كثــرت الســيارات أمــام منزلــي وقــام البنقالــي يتلفــظ مــا لــك‬\n‫دخــل وكشــر بوجهــه ‪...........‬وقامــوا مبدافعــة بعضهــم بعضــا وجتمــع‬\n‫النــاس لتفريقهــم وأنــا بجانــب ‪...........‬ورجــع البنقالــي للمحــل ورأيــت معــه‬\n‫عصــا وكان ممســك ًا بيديــه الثنتــن ويريــد ضــرب ‪...........‬وخفــت ان‬\n‫يضربنــي ووجهــت وجهــي للخلــف فســمعت ضربــة العصــا ولــم أشــاهد‬\n‫أيــن ضــرب فقــام ‪...........‬بغضــب شــديد فضــرب البنقالــي وقمنــا بدخــول‬\n‫احملــل وهنــاك كنــت امســك البنقالــي هــذا احلاضــر وهو كان ماســك ًا‬\n‫بــي وكان دم البنقالــي هــذا احلاضــر ينثــر علــي ولكــي أفلــت البنقالــي‬\n‫هــذا احلاضــر قمــت وضربتــه لكــي يتركنــي وقمنــا بالتفرقــة بينهمــا‬\n‫هــذا مــا لــدي مــن شــهادة وبــه اشــهد وبســؤال املدعــي ‪...........‬هــل لديــه‬\n‫أي بينــة أو شــاهد آخــر قــال ال يوجــد لــدي أي بينــات أو شــهود ســوى‬\n‫مــن أحضــرت ‪...........‬هــذا وقــد جــرى اطالعــي علــى التقريــر الطبــي‬\n‫الشــرعي النهائــي يف هــذه القضيــة رقــم ‪...........‬الصــادر مــن املديريــة‬\n‫العامــة للشــئون الصحيــة مبنطقــة الريــاض إدارة الطــب الشــرعي‬\n‫بالريــاض حيــث ذكــر فيــه عــدم تعــرض املتوفــى ب‪ ...........‬ألي ضــرب‬\n‫يف أي موضــع مــن جســده وهــذا خالصــة مــا جــاء يف تقريرهــم حيــث‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫ذكــر يف الصفحــة األخيــرة منــه ( ثبــت مــن فحــص وتشــريح اجلثــة ومــن‬\n    ‫فحــص التشــريح النســجي وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب‬\n    ‫وشــرايينه عبــارة عــن تضخــم بعضلــة القلــب (البطــن االيســر) مصحــوب‬\n    ‫بتصلــب عصيــدي شــديد مــع انســداد يف محيــط الشــريان التاجــي‬\n    ‫االيســر نســبة ‪ %90‬وحكمـ ًا علــى مــا ســبق وعلــى مــا اوردنــا مــن حقائــق‬\n    ‫علميــة فإننــا نــرى ان وفــاة املذكــور مرضيــة تعــزى الــى حالتــه املرضيــة‬\n    ‫املوصوفــه بالقلــب آنفـ ًا مبــا أدت اليــه مــن توقــف للقلــب والتنفــس نتيجــة‬\n    ‫نقــص شــديد يف ترويــة عضلــة القلــب وال يوجــد مــا مينــع مــن حــدوث وفــاة‬\n    ‫املذكــور يف تاريــخ ‪1429/9/22‬هـ ـ كمــا هــو مثبــت بخطــاب الشــرطة‬\n    ‫اخصائــي الطــب الشــرعي بالريــاض و‪...........‬توقيــع اخصائــي الطــب‬\n    ‫الشــرعي بالريــاض ‪............‬توقيــع جلميــع مــا تقــدم مــن الدعــوى واالجابــة‬\n    ‫وحيــث أنكــر املدعــى ‪ ......................‬ضربــه مــورث املدعــي ‪...........‬أو‬\n    ‫تســببه يف وفاتــه وحيــث لــم يقــم املدعــي البينــه علــى مــا أدعــاه وحيــث أن‬\n    ‫شــهادة الشــاهد الــذي أحضــره املدعــي هــو ‪ ...........‬لــم يشــهد علــى ضرب‬\n    ‫املدعــى عليــه وحيــث اثبــت التقريــر الطبــي الشــرعي املذكــور خالصتــه‬\n    ‫ان ســبب الوفــاة هــو وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب أدت‬\n    ‫الــى وفاتــه وانــه لــم يتعــرض ألي آثــار ضــرب يف جســده فقــد أفهمــت‬\n    ‫املدعــي ان لــه ميــن املدعــى عليــه أنــه لــم يضــرب ابنــه وانــه لــم يتســبب‬\n    ‫يف وفاتــه بضربــه قــال أريــد ميــن املدعــى عليــه ‪...........‬وبعرضــه علــى‬\n    ‫املدعــى عليــه ‪...........‬قــال ال مــا نــع لــدي مــن احللــف ثــم تلفــظ قائــا واهلل‬\n    ‫العظيــم الــذي ال الــه اال هــو عالــم الغيــب والشــهادة اننــي لــم اضــرب ابــن‬\n    ‫املدعــي ‪...........‬جلميــع مــا تقــدم فقــد حكمــت بصــرف النظــر عــن دعــوى‬\n    ‫املدعــي ‪...........‬ضــد املدعــى عليــه ‪...........‬واخليــت ســبيل املدعــى عليــه‬\n\n\n‫‪9‬‬\n\f‫‪...........‬وبعــرض احلكــم علــى الطرفــن قــررا القناعــة بــه‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1434/06/14‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف‬\n‫احملكمــة اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1430/02/27‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1430/02/27‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق‪ 1434/06/18‬ه ـ افتتحــت اجللســة الســاعة وفيهــا حضــر املدعــي‬\n‫‪...........‬قائــا يف دعــواه بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬\n                                                    ‫مبدينــة الريــاض أدعــي علــى‪/‬‬\n‫‪ 37........... -1‬عامــا ‪ ،‬بنجالديشــي اجلنســية مبوجــب رخصــة االقامــة‬\n‫رقــم () مقيــم مبدينــة الريــاض اوقــف بتاريخ ‪1429/9/22‬ه ـ ومت ايداعه‬\n‫الســجن العــام مبوجــب مذكــرة االحالــة ومتديــد التوقيــف رقــم‪...........‬‬\n                                                          ‫وتاريــخ ‪1429/11/12‬هـ‬\n‫‪ 22........... -2‬عامــا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )...........‬متعلم ‪ ،‬مقيم مبدينة الرياض ‪ ،‬اوقف بتاريخ ‪1429/9/22‬هـ‬\n‫وافــرج عنــه مبوجــب امــر اإلفــراج ‪...........‬وتاريــخ ‪1429/9/24‬ه ـ حيــث‬\n‫انــه بتاريــخ ‪1429/6/5‬ه ـ ورد ملركــز شــرطة ‪...........‬تقريــر احــدى فــرق‬\n‫الدوريــات االمنيــة برقــم ‪...........‬املتضمــن وجــود مضاربــة علــى شــارع‬\n‫‪...........‬امــام مطعــم ‪...........‬وانتقلــت الفرقــه للموقــع وقابلــت املتهــم االول‬\n‫وتبــن ان بــه اصابــه ويفيــد بــان شــخصني قامــا بضربــه امــام املطعــم‬\n‫ودخــا املنــزل احدهمــا املتهــم الثانــي واالخــر يدعــى ‪...........‬واثنــاء ذلــك‬\n‫حضــرا وافــادا بــان الطــرف االول تلفــظ عليهمــا ويقــوم بايقــاف ســيارته‬\n‫امــام املنــزل ومت نقــل جميــع االطــراف الــى مســتوصف ‪...........‬الســعافهم‬\n\n\n                                                                                          ‫‪10‬‬\n\f     ‫ومت عــاج املتهــم االول فقــط لعــدم وجــود اصابــات باخصامــه كمــا‬\n     ‫افــادا بذلــك واثنــاء اخلــروج مــن املســتوصف تعــرض ‪...........‬حلالــة اغمــاء‬\n     ‫ومت عرضــه علــى الطبيــب فطلــب نقلــه الــى مستشــفى احلــرس الوطنــي‬\n     ‫ومت نقلــه عــن طريــق اســعاف املســتوصف وتــويف قبــل وصولــه املستشــفى‬\n     ‫وباالنتقــال الــى موقــع اجلرميــة يف حــي ‪ .....‬شــارع ‪...........‬عقــار رقــم ‪...........‬‬\n     ‫وعنــد معاينــة املوقــع عثــر علــى عصــا خشــبية ( عصــا مكنســة ) ولــم يتــم‬\n     ‫العثــور علــى اشــياء اخــرى او اثــار دمــاء ‪ .‬وباســتجواب املتهــم االول ‪ /‬افــاد‬\n     ‫بانــه يف حوالــي الســاعة الثالثــة والثلــث صباحــا مــن يــوم ‪1429/9/22‬ه ـ‬\n     ‫حضــر البوفيــة وتنــاول وجبــة الســحور وعنــد خروجــه مــن البوفيــة‬\n     ‫قابله‪...........‬وســاله عــن صاحــب الســيارة الليموزيــن الواقفــه امــام منزلــه‬\n     ‫فقــال انــه نائــم يف منزلــه فضربــه ‪...........‬بيــده علــى وجهــه وضربــه‬\n     ‫بحديــده وذراعــه وفخــذه االميــن وقــام زميلــه املتهــم الثانــي ‪...........‬بضربــه‬\n     ‫علــى وجهــه ومبواجهتــه باملتهــم الثانــي تراجــع عــن اقوالــه وافــاد بانــه قــام‬\n     ‫بضــرب املتــويف بعصــا خشــبية مــرة واحــدة وال يعلــم هــل كانــت الضربــة‬\n     ‫علــى صــدره ام كتفــه وباســتجواب املتهــم الثانــي افــاد بانــه كان مــع‬\n     ‫املتــويف وعنــد وصولهمــا الــى املنــزل لــم يعثــر علــى موقــف للســيارة فنــزل‬\n     ‫املتــويف يتحــدث مــع املتهــم االول فســأله عــن صاحــب الســيارة الواقفــة‬\n     ‫أمــام منزلهــم فقــال لــه املتهــم األول إنــه زبــون وأنــه نائــم فتماســكا‬\n     ‫باأليــدي فدخــل املتهــم األول البوفيــة وأحضــر عصــا ورفعهــا علــى املتــويف‬\n     ‫وال يعلــم إن كان ضربــه بهــا أم ال كمــا أفــاد بــأن املتهــم األول قــام‬\n     ‫مبســكه وحــاول التخلــص منــه دون جــدوى فقــام لضــرب املتهــم األول‬\n     ‫علــى وجهــه ثــم دخــل هــو واملتــويف املنــزل وبعــد ذلــك قبــض عليهمــا وال‬\n     ‫يوجــد بــه أي اصابــات وقــد صــدر التقريــر الشــرعي رقم‪...........‬املتضمــن‬\n\n\n‫‪11‬‬\n\f‫ان املجنــي عليــه يعانــي مــن حالــة مرضيــة متقدمــة بالقلــب وشــرايينه‬\n‫عبــارة عــن تضخــم بعضلــة القلــب البطــن األيســر مصحــوب بتصلــب‬\n‫عصيــدي شــديد مــع انســداد يف محيــط الشــريان التاجــي األيســر بنســبة‬\n‫‪ %90‬وحكمــا علــى مــا ســبق فــان املذكــور تعــزى وفاتــه إلــى حالتــه‬\n‫املرضيــة املوصوفــة بالقلــب ومبــا أدت إليــه مــن توقــف القلــب والتنفــس‬\n‫نتيجــة نقــص شــديد يف ترويــة عضلــة القلــب كمــا ورد التقريــر الطبــي‬\n‫مــن مدينــة امللــك عبدالعزيــز الطبيــة رقــم ‪...........‬وتاريــخ ‪1429/9/22‬ه ـ‬\n             ‫بحــق املتــويف ‪...........‬املتضمــن وجــود ســحجات علــى الصــدر‪.‬‬\n‫وقــد أســفر التحقيــق عــن اتهــام األول ‪...........‬بقتــل ‪...........‬شــبه عمــد‬\n‫وذلــك بعــد ضربــه بعصــا خشــبية علــى صــدره ضربــة واحــده واتهــام‬\n‫الثانــي ‪...........‬بضــرب االول علــى وجهــه بيــده وفقــا لقــرار االتهــام رقــم (‬\n                       ‫‪ ...........‬لعــام ‪1429‬ه ــوذلك لألدلــة والقرائــن التاليــة‬\n‫‪-1‬إقــرار األول بالتضــارب مــع املتوفــى واملتهــم الثانــي املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )12‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪)24‬‬\n‫‪ -2‬مــا جــاء يف اقــوال املتهــم الثانــي املدونــة علــى الصفحــة رقــم (‪ )5‬مــن‬\n                                                ‫ملــف التحقيــق املرفــق لفــة (‪.)24‬‬\n‫‪-3‬محضــر املواجهــة املــدون علــى الصفحــة رقــم (‪ )8‬مــن ملــف التحقيــق‬\n                                                                  ‫املرفقــة لفــة (‪)24‬‬\n‫‪-4‬التقريــر الطبــي الصــادر مــن مدينــة امللــك عبدالعزيــز الطبية املتضمن‬\n                    ‫وجــود ســحجات علــى صــدر املتوفــى املرفــق لفــة رقم (‪)6‬‬\n‫‪-5‬محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪ )13-12‬مــن‬\n                                               ‫ملــف االســتدالل املرفــق لفــة (‪.)1‬‬\n                                            ‫‪ -6‬التقرير اجلنائي املصور لفة (‪.)22‬‬\n\n\n                                                                                         ‫‪12‬‬\n\f     ‫‪-7‬محضــر عــرض األداة املســتخدمة باجلرميــة املــدون علــى الصفحــة رقــم‬\n                                         ‫(‪ )2‬مــن ملــف التحقيــق املرفــق لفــة (‪.)24‬‬\n                                            ‫‪ -8‬تقرير الدوريات املنية لفة رقم (‪.)4‬‬\n     ‫وبالبحــث عــن ســوابقهما لــم تــرد حتــى تاريخــه‪ .‬وحيــث أن مــا أقــدم‬\n     ‫عليــه األول وهــو بكامــل أهليتــه يعــد فعــا محرمــا لــذا أطلــب إثبــات‬\n     ‫صفــة القتــل شــبه العمــد وفقــا لنــص املــادة ‪ 126‬مــن نظــام اإلجــراءات‬\n     ‫اجلزائيــة وطلــب احلكــم عليــه مبقتضــى اإلرادة امللكيــة للقتــل شــبه‬\n     ‫العمــد رقــم ‪ 2104/4/8‬وتاريــخ ‪1363/10/16‬ه ــوتعزير الثانــي لقــاء‬\n     ‫مــا أســند إليــه علمــا بــأن احلــق اخلــاص مــازال قائم ـ ًا بالنســبة للديــة‬\n     ‫‪.‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول ‪...........‬أجــاب‬\n     ‫بلســان عربــي قائــا ان املتوفــى ‪...........‬أردنــي اجلنســية حصــل بينــي‬\n     ‫وبينــه مشــادة كالميــة بســبب إيقــاف ســيارة أمــام املطعــم فقــام بضربــي‬\n     ‫كف ـ ًا علــى وجهــي وقمــت وأخــذت عصــا ملــا ضربنــي ورفعتهــا واهويــت‬\n     ‫بهــا عليــه فقــام مبســكها منــي أثنــاء رفعهــا ولــم أصبــه بــأي ضــرب‬\n     ‫وال غيــره وقــد جــاء ‪...........‬ســعودي اجلنســية فضربنــي ولــم أضــرب أي‬\n     ‫منهمــا بــل أنــا املضــروب هكــذا أجــاب وال صحــة ملاذكــر يف الدعــوى‬\n     ‫مــن اننــي أفــدت بضــرب املتوفــى بعصــا خشــبية مــرة واحــدة هــذا غيــر‬\n     ‫صحيــح هكــذا أجــاب وقــال املدعــي العــام ليــس لــدي بينــة علــى ضــرب‬\n     ‫املدعــى عليــه للمتوفــى ســوى إفــادة املدعــى عليــه وقــد جــرى رجوعــي‬\n     ‫ألقــوال املدعــى عليــه ‪...........‬و‪...........‬فيدفتــر التحقيــق املرفــق ص(‪-1‬‬\n     ‫‪)8‬فوجــدت املدعــى عليــه أنكــر ضربــه للمتوفــى ‪...........‬ووجــدت‬\n     ‫أقــوال ‪...........‬أنــه شــاهد املدعــى عليه‪...........‬رفــع العصــا وال يــدري هــل‬\n     ‫ضــرب ‪...........‬أم ال كمــا جــرى اطالعــي علــى محضــر املواجهــة بــن‬\n\n\n‫‪13‬‬\n\f‫‪...........‬و‪ ...........‬وجــدت افــادة ‪ ....‬أنــه قــام باحضــار العصــا مــن داخــل‬\n‫احملــل وقــام بضــرب ‪...........‬مــرة واحــدة وال يــدري هــل كانــت يف صــدره‬\n‫أم كتفــة وبعرضــه عليــه قــال ال صحــة لذلــك كمــا جــرى اطالعــي‬\n‫علــى التقريــر الطبــي الشــرعي النهائــي يف هــذه القضيــة رقــم ‪...........‬‬\n‫الصــادر مــن املديريــة العامــة للشــئون الصحيــة مبنطقــة الريــاض إدارة‬\n‫الطــب الشــرعي بالريــاض حيــث ذكــر فيــه عــدم تعــرض املتوفــى‬\n‫ب‪...........‬ألي ضــرب يف أي موضــع مــن جســده وعــدم وجــود ســحجات‬\n‫وهــذا خالصــة مــا جــاء يف تقريرهــم حيــث ذكــر يف الصفحــة األخيــرة‬\n‫منــه ( ثبــت مــن فحــص وتشــريح اجلثــة ومــن فحــص التشــريح النســجي‬\n‫وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب وشــرايينه عبــارة عــن‬\n‫تضخــم بعضلــة القلــب (البطــن االيســر) مصحــوب بتصلــد عصيــدي‬\n‫شــديد مــع انســداد يف محيــط الشــريان التاجــي االيســر نســبة ‪%90‬‬\n‫وحكمـ ًا علــى مــا ســبق وعلــى مــا أوردنــا مــن حقائــق علميــة فإننــا نــرى‬\n‫أن وفــاة املذكــور مرضيــة تعــزى الــى حالتــه املرضيــة املوصوفــه بالقلــب‬\n‫آنف ـ ًا مبــا أدت اليــه مــن توقــف للقلــب والتنفــس نتيجــة نقــص شــديد يف‬\n‫ترويــة عضلــة القلــب وال يوجــد مــا مينــع مــن حــدوث وفــاة املذكــور يف‬\n‫تاريــخ ‪1429/9/22‬هـ ــكما هــو مثبــت بخطــاب الشــرطة أخصائــي‬\n‫الطــب الشــرعي بالريــاض ‪...........‬توقيــع أخصائــي الطــب الشــرعي‬\n‫بالريــاض د‪............‬توقيــع جلميــع مــا تقــدم مــن الدعــوى واالجابــة وحيــث‬\n‫أنكــر املدعــى عليــه ‪...........‬ضربــه مــورث املدعــي‪...........‬أو تســببه يف‬\n‫وفاتــه وحيــث لــم يقــم املدعــي البينــة علــى مــا أدعــاه وحيــث جــاء يف‬\n‫التقريــر الطبــي الشــرعي النهائــي أن ســبب وفــاة ‪...........‬حالتــه املرضيــة‬\n‫بالقلــب جلميــع مــا تقــدم لــم يظهــر لــم يثبــت لــدي تســبب املدعــى عليــه يف‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫وفــاة ‪...........‬ال عمــد وال شــبه وال خطــأ وحكمــت بصــرف النظــر عــن‬\n     ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ‪...........‬وأخليــت ســبيله وبعــرض‬\n     ‫احلكــم علــى الطرفــن قنــع املدعــى عليــه ‪...........‬ولــم يقنــع املدعــي العــام‬\n     ‫وطلــب تدقيقــه مــن قبــل محكمــة االســتئناف بــدون الئحــة فأجيــب‬\n     ‫لطلبــه ويف حــال إحضــار املدعــى عليــه الثاني‪...........‬ســوف يتــم نظــر‬\n     ‫الدعــوى ضــده لــدي مبشــيئة اهلل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n     ‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪331950074‬‬\n     ‫وتاريــخ ‪1434/7/9‬ه ــاملرفق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ ‪........... /‬برقموتاريخ‪1434/6/24‬ه ـ اخلــاص بدعوى‬\n     ‫املدعــي العــام واخلــاص ‪...........‬أردني اجلنســية ضد‪ ........... /‬بنجالديشــي‬\n     ‫اجلنســية يف قضيــة قتــل علــى النحــو املوضــح يف بالقــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى احلكــم فيمــا يتعلــق‬\n     ‫باحلــق العــام وأمــا مــا يتعلــق باحلــق اخلــاص فقــد انتهــى احلكــم بقناعــة‬\n     ‫الطرفــن فــا يكــون خاضع ـ ًا للتدقيــق واهلل املوفــق وصلــى اهلل علــى‬\n                                                     ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪15‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":5,"source_page_end":15,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"57b732a9852944cc5be15d283a1e0a24a397aebdc4de7c1cdb52998863d498e2","normalized_text_hash":"7cb22a01be803710c1c9c014b8b9ae8752e32a464dfb0aee7ee4205ca4837991","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p5-34250164"},{"id":"a2bda85b-a2e1-5082-9b3e-026a4677ff39","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابة -املطالبة بالتعزير جراء التعدي -املطالبة بأرش اإلصابة -تقدير أرش إصابة الرأس -التعزير","document_number":"3449421","case_number":"346565","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/27","year":"1434","subject":"اعتداء -ضرب -إحداث إصابة -املطالبة بالتعزير جراء التعدي -املطالبة بأرش اإلصابة -تقدير أرش إصابة الرأس -التعزير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 3449421:‬تاريخه‪1434/02/27 :‬هـ‬\n                       ‫رقم الدعوى‪346565:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34233598‬تاريخه‪1434/06/7:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪-‬إحــداث إصابــة ‪ -‬املطالبــة بالتعزيــر جــراء التعــدي‬\n‫‪ -‬املطالبــة بــأرش اإلصابــة ‪ -‬تقديــر أرش إصابــة الــرأس ‪ -‬التعزيــر‬\n                                                               ‫باجللــد‪.‬‬\n\n\n\n\n                                            ‫‪-1‬قول اهلل تعالى‪(:‬وال تعتدوا )‪.‬‬\n‫‪-2‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬مــن حلــف علــى ميــن هــو فيهــا فاجــر‬\n‫ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل وهــو عليه غضبان)‪.‬رواه مســلم‬\n‫‪-3‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                             ‫ومالــه وعرضــه )‪.‬‬\n‫‪-4‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                         ‫ويده)‪.‬‬\n          ‫‪-5‬ماذكره الفقهاء من حتليف أقوى املتداعيني املتجاحدين‪.‬‬\n ‫‪-6‬ماذكره ابن القيم من أن البينة هي كل مايبني احلق ويوضحه‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه برمــي فنجــان والتســبب يف إصابــة املجنــي‬\n‫عليــه بجــرح بالــرأس ويحتــاج عشــرة أيــام للعــاج ‪ ،‬طلــب املدعــى العــام‬\n‫إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬حضــر‬\n\n                                                                                   ‫‪16‬‬\n\f     ‫املدعــي اخلــاص وطلــب أرش االصابــة‪ ،‬أقــر املدعــى عليــه بضــرب املدعي‬\n     ‫اخلــاص بفنجــان الشــاي ‪ ،‬وذكــر بــأن اإلصابــة بالصدر وليســت بالرأس‬\n     ‫‪ ،‬أحضــر املدعــي العــام واملدعــي اخلــاص شــاهدين فشــهدا بالضــرب‬\n     ‫ولــم يذكــرا موضعــه ‪ ،‬وذكــر الشــاهدان أنهــم بعــد املضاربــة شــاهدا‬\n     ‫إصابــة يف رأس املدعــي باحلــق اخلــاص ‪ ،‬رجــع القاضــي إلــى التقريــر‬\n     ‫الطبــي املبــن لصفــة اإلصابــة ومــدة الشــفاء وقــد مت تقديــر أرش‬\n     ‫اإلصابــة مــن مقــدري الشــجاج بأربعــة آالف ريــال ‪،‬وملــا ذكــره الفقهــاء‬\n     ‫مــن حتليــف أقــوى املتداعبــن املتجاحديــن جــرى حتليــف املدعــي باحلــق‬\n     ‫اخلــاص علــى صحــة دعــواه مــن أن اإلصابــة التــي برأســه مــن املدعــى‬\n     ‫عليــه ‪ ،‬صــدر احلكــم بجلــد املدعــى عليــه عشــرين جلــدة للحــق العــام ‪،‬‬\n     ‫إلــزام املدعــى عليــه بــأن يدفــع للمدعــي باحلــق اخلــاص أربعــة آالف ريــال‬\n     ‫أرش إصابتــه ‪،‬قــرر املدعــي العــام عــدم املعارضــة واملــدع باحلــق اخلــاص‬\n     ‫القناعــة أمــا املدعــى عليــه فاعتــرض علــى احلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة‬\n     ‫اجلزئيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزئيــة يف محافظــة جدة‪/‬املســاعد برقــم وتاريــخ‬\n     ‫‪ 1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33120326‬وتاريــخ‬\n     ‫‪ 1433/01/18‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/01/24‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي باحلــق اخلــاص ‪......... ،‬‬\n     ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .........‬واملدعــي العــام‬\n\n‫‪17‬‬\n\f‫بصفتــه عضــو هيئــة التحقيــق واالدعــاء العــام بدائــرة محافظــة جــدة‪،‬‬\n‫واملكلــف مــن قبــل هيئــة التحقيــق واالدعاء العام برقــم هـ م ‪1540/2/2‬‬\n‫وتاريــخ ‪1433/01/05‬ه ـ وادعيــا علــى ‪ )37( ............../‬عامـ ًا ‪ ،‬ســعودي‬\n‫اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقــم () ‪ ،‬مطلــق الســراح بالكفالــة‬\n‫احلضوريــة ‪.‬حيــث أنــه بتاريــخ ‪1432/11/8‬ه ـ تســلم مركــز شــرطة‬\n‫النزهــة الشــكوى املقدمــة مــن املدعــي‪، /‬ســعودي اجلنســية ‪ ،‬ومفادهــا‬\n‫ان املدعــى عليــه رمــى عليــه فنجــان شــاي وصــدر بشــأنه التقريــر‬\n‫الطبــي مــن الشــؤون الصحيــة مبحافظــة الطائــف رقــم بــدون بتاريــخ‬\n‫‪1432/11/8‬هـ‪،‬املتضمــن إصابتــه بجــرح بالــراس بطــول ‪4‬ســم نصــف‬\n‫ســم‪ ،‬مــدة الشــفاء عشــرة أيام‪.‬وبســماع أقــوال املدعــى عليــه‪، ........../‬‬\n‫أقــر برمــي املدعــي بفنجــان شــاي بســبب وجــود خالفــات عائليــة ســابقة‬\n‫بينهمــا‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه برمــي‬\n‫املدعــي بفنجــان شــاي والتســبب يف إصابتــه باإلصابــة املدونــة بالتقريــر‬\n                                        ‫الطبــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                   ‫‪ )1‬اعترافه املنوه عنه مبلف التحقيق ص(‪.)1‬‬\n                                                                  ‫‪ )2‬التقرير الطبي‪.‬‬\n                  ‫وبالبحث عن سوابق املدعى عليه لم يعثر له على سوابق ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه املذكــور أعــاه فعــل محــرم و‬\n‫معاقــب عليــه شــرع ًا ‪ ،‬لــذا اطلــب مــن احملكمــة اجلزئيــة مبحافظــة جــدة‬\n‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا بــدر منــه‪.‬‬\n‫ا مــا ذكــره املدعــي‬      ‫ونســأله اجلــواب وبســؤال املدعــى عليــه أجــاب قائـ ً‬\n‫العــام مــن أننــي قمــت بضــرب املدعــي بفنجــان فصحيــح أمــا كــون‬\n‫الفنجــان أصــاب رأس املدعــي فغيــر صحيــح والصحيــح أن الفنجــان‬\n\n\n                                                                                         ‫‪18‬‬\n\f     ‫أصــاب صــدره هكــذا أجــاب وبســؤال املدعــى عليــه علــى بينتــه علــى‬\n     ‫أن الفنجــان أصــاب صــدره قــال هــذا مــا شــاهدته وبســؤال املدعــي العــام‬\n     ‫واملدعــي اخلــاص عــن بينتهمــا أجــاب املدعــي اخلــاص قائــا نعــم لــدي‬\n     ‫بينــه علــى ذلــك أطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة وأعطــي‬\n     ‫موعــدا يف يــوم األحــد املوافــق ‪1433/02/14‬ه ـ الســاعة احلاديــة عشــر‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزئيــة والقائــم‬\n     ‫بعمــل القاضــي مبوجــب التكليــف رقــم ‪ /260‬ش يف ‪1433/2/13‬ه ـ‬\n     ‫ويف اجللســة املقررةيــوم االحــد املوافــق ‪1443/2/14‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى‬\n     ‫ال مــن مينــي اجلنســية مبوجــب االقامــة‬\n                                              ‫عليــه واملدعــي اخلــاص وحضــر ك ً‬\n     ‫رقــم والــذي يعمــل ميكانيكــي ســيارات كمــا حضــر مينــي اجلنســية‬\n     ‫مبوجــب االقامــة رقــم والــذي يعمــل ميكانيكــي ســيارات وبســؤالهما‬\n     ‫كل واحــد مبفــرده شــهد كل واحــد منهمــا بــأن املدعــى عليــه قــام‬\n     ‫بضــرب املدعــى اخلــاص ولــم أرى املوضــع الــذي ضــرب بــه الفنجــان‬\n     ‫يف جســم املدعــى اخلــاص لكــن وبعــد املضاربــة رأينــا إصابــة يف رأس‬\n     ‫املدعــي اخلــاص بعــد ذلــك هكــذا شــهد كل واحــد منهمــا وبعــرض‬\n     ‫ا ماجــاء يف الشــهادة صحيــح‬    ‫الشــهادة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫لكــن االصابــة التــي حلقــت بــرأس املدعــي اخلــاص ليســت منــي وليســت‬\n     ‫مســؤول عنهــا والفنجــان الــذي رميــت بــه ضــرب يف صــدره وبســؤال‬\n     ‫املدعــي اخلــاص هــل لديــك بينــة علــى أن االصابــة التــي يف رأســك مــن‬\n     ‫املدعــى عليــه قــال ليــس لــدي ســوى ماقدمــت وعليــه رفعــت اجللســة‬\n     ‫وتأجلــت يف يــوم الســبت املوافــق ‪1433/2/27‬ه ـ ويف اجللســة املقررة يوم‬\n     ‫الســبت املوافــق ‪1433/02/27‬ه ـ الســاعة ‪ 10 : 30‬افتتحــت اجللســة‬\n\n\n‫‪19‬‬\n\f‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه واملدعــي‬\n‫اخلــاص وقــال أطلــب حقــي الشــرعي منــه وإلزامــه بدفــع أرش إصابتــي‬\n‫وتعزيــره لقــاء إهانتــي وبعــد ذلــك جــرى ســؤال املدعــى عليــه عــن الشــهود‬\n‫فقــال ال أطعــن فيهــم ولــي معرفــه بهــم ولكــن الفنجــان ضــرب يف صــدره‬\n‫ولــم يضــرب يف رأســه وال بينــه لــدي إال نفــس الشــهود الذيــن شــهدوا‬\n‫وال اعلــم مــن ضربــه يف رأســه وقــد جــرى منــي إحالــة املعاملــة إلــى جلنــة‬\n‫الصلــح برقــم ‪ 33120326‬يف ‪1433/02/27‬ه ـ لــذا رفعــت اجللســة إلــى‬\n‫حــن ورود اإلجابــة مــن جلنــة الصلــح ‪.‬احلمــد هلل وحــده وبعــد فلــدي أنــا‬\n‫القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة والقائــم بعمــل القاضــي‬\n‫مبوجــب قــرار التكليــف رقــم ‪331348829‬وتاريــخ ‪1433/07/19‬ه ـ‬\n‫ويف اجللســة املقــررة يــوم األحــد املوافــق‪ 1433/07/20‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 :30‬لســماع دعــوى املدعــي العــام ضــد وفيهــا حضــر‬\n‫املدعــي العــام و املدعــى باحلــق اخلــاص ولــم يحضــر املدعــى عليــه مــع‬\n‫علمــه باملوعــد احملــدد مســبق ًا لــذا رفعــت اجللســة حلــن حضــوره يف‬\n‫املوعــد احملــدد وذلــك يــوم األحــد املوافــق ‪1433/08/11‬ه ـ الســاعة‬\n‫‪ . 11 : 15‬ويف اجللســة املقــررة يــوم الســبت املوافــق ‪1433/02/27‬ه ـ‬\n‫الســاعة ‪ 10 : 30‬افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه واملدعــي اخلــاص وقــال أطلــب حقــي الشــرعي‬\n‫منــه وإلزامــه بدفــع أرش إصابتــي وتعزيــره لقــاء إهانتــي وبعــد ذلــك‬\n‫جــرى ســؤال املدعــى عليــه عــن الشــهود فقــال ال أطعــن فيهــم ولــي معرفــه‬\n‫بهــم ولكــن الفنجــان ضــرب يف صــدره ولــم يضــرب يف رأســه وال بينــه‬\n‫لــدي إال نفــس الشــهود الذيــن شــهدوا وال اعلــم مــن ضربــه يف رأســه‬\n‫وقــد جــرى منــي إحالــة املعاملــة إلــى جلنــة الصلــح برقــم ‪ 33120326‬يف‬\n\n\n                                                                                     ‫‪20‬‬\n\f     ‫‪1433/02/27‬ه ـ لــذا رفعــت اجللســة إلــى حــن ورود اإلجابــة مــن جلنــة‬\n     ‫الصلــح ويف جلســة أخــرى وردنــا خطــاب جلنــة الصلــح رقــم ‪33120326‬‬\n     ‫يف ‪1433/5/16‬ه ـ وبســؤال املدعــي العــام واملدعــي باحلــق اخلــاص هــل‬\n     ‫لديكمــا زيــادة بينــه قــاال ليــس لدينــا بينــه ســوى مــا قدمنــا ومــا جــاء يف‬\n     ‫املعاملــة مــن أدلــة وقرائــن عليــه جــرى منــي الرجــوع إلــى اعترافــه املــدون‬\n     ‫لفــة رقــم (‪ )1‬املتضمــن أنــه وبســؤاله عمــا جــاء يف أقــوال املدعــي أنكــر‬\n     ‫نهائي ـ ًا بــل هــو مــن قــام برميــي بطفايــة علبــة الســجائر وعــن اإلصابــة‬\n     ‫التــي حدثــت باملدعــي أفــاد أنــه ال يعلــم عنهــا نهائيـ ًا وال يعلــم مــن تســبب‬\n     ‫بهــا وأنهــا دعــوة كيديــة وبعــد االطــاع عليهــا لــم أجــد فيهــا اعتــراف‬\n     ‫للمدعــى عليــه كمــا ذكــر املدعــي العــام كمــا جــرى منــي الرجــوع‬\n     ‫إلــى التقريــر الطبــي املرفــق باملعاملــة لفــة رقــم (‪ )8‬واملتضمنــة أنــه يوجــد‬\n     ‫جــرح بالــرأس بطــول ‪ 4‬ســم ‪ ،‬نصــف ســم ومــدة الشــفاء عشــرة أيــام‬\n     ‫وهــو بتاريــخ ‪1432/11/08‬ه ـ وعليــه وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وحيــث إن املدعــي باحلــق اخلــاص تقــوي جانبــه مبــا يف دعــواه‬\n           ‫مبــا يلــي أوالً‪ :‬اعتــراف املدعــى عليــه بأنــه ضــرب املدعــي بفنجــان‬\n                            ‫ثانياً‪ :‬تزامن تاريخ الضرب مع تاريخ التقرير الطبي‬\n     ‫ثالثـاً‪ :‬مــا جــاء يف شــهادة الشــهود بــأن املدعــى عليــه قــام بضــرب املدعــى‬\n     ‫بفنجــان وبعــد املضاربــة شــاهدوا إصابــة يف وجــه املدعــي باحلــق اخلــاص‬\n     ‫عليه فق ــد ق ــررت الكتـاب ــة ملقدري الشجاج يف هذه احملكمة مبوجب‬\n     ‫خطابنا رقم ‪ 33120326‬وتاريخ ‪1434/01/14‬هـ لت ـقـديـر أرش اصـابة‬\n     ‫امل ــدعي ‪ ،‬وقــد وردنــا إفــادة مقــدري الشــجاج يف هــذه احملكمــة برقــم‬\n     ‫‪ 3457354‬و تاريــخ ‪1434/02/05‬ه ـ و املتضمنــة مــا نصــه يوجــد جــرح‬\n     ‫بالــرأس بطــول ‪ 4‬ســم و مــدة الشــفاء عشــرة أيــام و ال يوجــد مــكان‬\n\n\n‫‪21‬‬\n\f‫لإلصابــة عليــه نفيــد فضيلتكــم بــان تقديــر أرش اإلصابــة يقــدر بأربعــة‬\n‫آالف ريــال ( ‪ 4000‬ريــال ) و بــاهلل التوفيــق و مبــا أن جانــب املدعــي‬\n‫قــد تقــوى مبــا ذكــر ســابقا و ملــا ذكــره الفقهــاء مــن حتليــف أقــوى‬\n‫املتداعييناملتجاحديــن و لتقــوي جانــب املدعــي مبــا ذكــر ســابقا لــذا‬\n‫فقــد جــرى منــي عــرض اليمــن علــى املدعــي بــان يحلــف علــى أن املدعــي‬\n‫عليــه قــام برمــي فنجــان شــاهي عليــه و تســبب يف إصابتــه يف الــرأس و‬\n‫بعــد تذكيــره مبعظــم اليمــن و بقولــه صلــى اهلل عليــه وســلم ( مــن حلــف‬\n‫علــى ميــن هــو فيهــا فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل و هــو‬\n‫عليــه غضبــان ) رواه مســلم فاســتعد لقــول اليمــن ثــم حلــف بعــد إذنــي‬\n‫لــه قائــا ( و اهلل العظيــم الــذي ال الــه غيــره عالــم الغيــب و الشــهادة أن‬\n‫املدعــي عليــه قــام برمــي فنجــان شــاهي علــي و تســبب يف إصابتــي يف‬\n‫الــرأس ) و اهلل العظيــم و عليــه و بنــاء علــى مــا تقــدم مــن الدعــوى و‬\n‫جوابهــا و إلقــرار املدعــي عليــه برمــي فنجــان الشــاهي و لتزامــن تاريــخ‬\n‫الضــرب مــع تاريــخ التقريــر الطبــي و ملــا جــاء يف شــهادة الشــهود و ملــا جاء‬\n‫يف تقريــر مقــدري الشــجاج املطابقــة ملــا جــاء يف الدعــوى و قناعتهمــا بــه‬\n‫و ملــا قــرره أهــل العلــم بــان البينــة ليســت محصــورة باعتــراف أو شــهود‬\n‫و ملــا ذكــره ابــن القيــم بــأن البينــة هــي كل مايبــن احلــق و يوضحــه و‬\n‫حللــف املدعــي باحلــق اخلــاص اليمــن املكملــة لبينتــه لــذا فقــد ثبــت لــدي‬\n‫قيــام املدعــي عليــه برمــي املدعــي بفنجــان شــاي و التســبب يف إصابتــه و‬\n‫مبــا أن مــا قــام بــه املدعــي عليــه فعــل محــرم و معاقــب عليــه شــرعا لقولــه‬\n‫تعالــى ( وال تعتــدوا ) و لقولــه صلــى اهلل عليــه و ســلم ( كل املســلم علــى‬\n‫املســلم حــرام دمــه و مالــه و عرضــه) ولقولــه صلــى اهلل عليــه و ســلم‬\n‫( املســلم مــن ســلم املســلمون مــن لســانه و يــده ) و نظــرا لعــدم و جــود‬\n\n\n                                                                                        ‫‪22‬‬\n\f     ‫ســوابق علــى املدعــي عليــه كمــا هــو مبــن يف صحيفــة الســوابق املرفقــة‬\n     ‫لفــة رقــم (‪ )18‬و نظــر لصلــة القرابــة بينهمــا كــون املدعــي عليــه زوج‬\n     ‫أخــت املدعــي و ذلــك كلــه أمــر يلحــظ فلمــا ســبق فقــد قــررت اآلتــي ‪:‬‬\n     ‫أوال ‪ :‬يجلــد املدعــي عليــه عشــرون جلــده و ذلــك لقــاء قيامــه مبــا نســب‬\n     ‫إليــه و ذلــك لقــاء احلــق العــام ‪ .‬ثانيــا ‪ :‬الزمــت املدعــي عليــه بدفــع مبلــغ و‬\n     ‫قــدره أربعــة أالف ريــال (‪ 4000‬ريــال) للمدعــي وذلــك لقــاء ارش إصابتــه‬\n     ‫و بذلــك كلــه حكمــت و بعــرض احلكــم علــى املدعــي العــام و املدعــي‬\n     ‫عليــه و املدعــي باحلــق اخلــاص قــرر املدعــي باحلــق اخلــاص القناعــة بــه‬\n     ‫كمــا قــرر املدعــي العــام عــدم معارضتــه و قــرر املدعــي عليــه عــدم‬\n     ‫القناعــة فافهمتــه باحلضــور يف يــوم الســبت املوافــق ‪1434/03/07‬ه ـ‬\n     ‫الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n     ‫يومــا اعتبــارا مــن التاريــخ املشــار إليــه فــان مضــت املــدة و لــم يســتلم‬\n     ‫نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان حقــه يف‬\n     ‫تقــدمي الئحــة االعتــراض يكــون ســاقطا و جــرى النطــق باحلكــم يف يــوم‬\n     ‫الثالثــاء املوافــق ‪1434/02/26‬ه ـ الســاعة ‪ 10 : 30‬وبــه أقفلــت اجللســة‬\n     ‫و علــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ‬\n               ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n     ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n     ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n     ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــده رقــم(‪)3457354‬‬\n     ‫وتاريخ(‪1434/5/28‬هــ) املرفــق بهــا القــرار رقــم(‪)3449421‬‬\n     ‫وتاريخ(‪1434/2/27‬هـ)الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي‬\n\n\n‫‪23‬‬\n\f‫باحملكمــة اجلزائيــة بجــدة ‪،‬املتضمــن دعــوى املدعــي العــام ضــد‪/‬‬\n‫ســعودي اجلنســية ‪ ،‬املتهــم برمــي شــخص بفنجــان شــاي والتســبب يف‬\n‫إصابتــه ‪ ،‬احملكــوم فيــه مبــادون باطنه‪،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n   ‫املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                          ‫‪24‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":16,"source_page_end":24,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a7704868eaefc1c958244955645a67b20e6906f538b857f966e516d31564fed3","normalized_text_hash":"8e655485f7d6db94bd904b9a74f27d824a54ba1ec37510de1e257801e4e5714a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p16-3449421"},{"id":"41bb860d-9514-55b7-b066-ee771e565d5f","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -تنازل الزوجة عن حقها اخلاص -تعزير الزوج بالتوبيخ والسجن واجللد وأخذ التعهد.","document_number":"34226948","case_number":"3414182","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/29","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -تنازل الزوجة عن حقها اخلاص -تعزير الزوج بالتوبيخ والسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34226948 :‬تاريخه‪1434/05/29:‬هـ‬\n                          ‫رقم الدعوى‪3414182:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34251682‬تاريخه‪1434/06/26 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬تنــازل الزوجــة عــن حقهــا‬\n      ‫اخلــاص ‪ -‬تعزيــر الــزوج بالتوبيــخ والســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n                         ‫‪-1‬قول اهلل تعالى‪( :‬وعاشروهن باملعروف) [النساء‪.]19:‬‬\n     ‫‪-2‬حديــث معاويــة بــن حيــدة ‪ -‬رضــي اهلل عنــه ‪ -‬قــال‪ :‬قلــت يــا رســول اهلل‬\n     ‫مــا حــق زوجــة أحدنــا عليــه قــال‪« :‬أن تطعمهــا إذا طعمــت‪ ،‬وتكســوها إذا‬\n     ‫اكتســيت‪ ،‬وال تضــرب الوجــه وال تقبــح وال تهجــر إال يف البيــت» رواه‬\n      ‫أحمــد وأبــو داود وصححــه ابــن حبــان وقــال األلبانــي‪ :‬حســن صحيــح‪.‬‬\n     ‫‪ -3‬حديــث أبــي هريــرة قــال‪ :‬قــال النبــي ‪ -‬صلــى اهلل عليــه وســلم‪( :-‬إذا‬\n                            ‫قاتــل أحدكــم أخــاه فليجتنــب الوجــه) رواه مســلم‪.‬‬\n     ‫‪ -4‬قــول النــووي ‪ -‬رحمــه اهلل ‪ ،‬يف شــرحه للحديــث الســابق‪(:-‬هذا‬\n     ‫تصريــح بالنهــي عــن ضــرب الوجــه؛ ألنــه لطيــف يجمــع احملاســن‬\n     ‫وأعضــاؤه نفيســة لطيفــة وأكثــر اإلدراك بهــا‪ ،‬فقــد يبطلهــا ضــرب‬\n     ‫الوجــه وقــد ينقصهــا وقــد يشــوه الوجــه‪ ،‬والشــن فيــه فاحــش؛ ألنــه بــارز‬\n     ‫ظاهــر ال ميكــن ســتره‪ ،‬ومتــى ضربــه ال يســلم مــن شــن غالبـ ًا‪ ،‬ويدخــل‬\n     ‫يف النهــي إذا ضــرب زوجتــه أو ولــده أو عبــده ضــرب تأديــب فليجتنــب‬\n                                                                  ‫الوجــه) [‪.]165/16‬‬\n     ‫‪ -5‬التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل ‪ ،‬كمــا نــص علــى ذلــك‬\n                                                                             ‫الفقهــاء‪.‬‬\n‫‪25‬‬\n\f‫تقــدم مواطــن ببــاغ عــن تعــرض شــقيقته لإلعتــداء بالضــرب مــن‬\n‫قبــل زوجهــا املدعــى عليــه ‪ ،‬والتســبب يف إصابتهــا بكســر يف أصبــع‬\n‫قدمهــا اليمنــى ومــدة الشــفاء أربعــة أســابيع حســب تقريــر املستشــفى‪،‬‬\n‫بالتحقيــق معــه جــرى توجيــه اإلتهــام لــه بضــرب زوجتــه والتســبب يف‬\n‫إصابتهــا اإلصابــة املوصوفــة بالتقريــر الطبــي ‪ ،‬وطلــب إثبــات مــا أســند‬\n‫إليــه وإيقــاع العقوبــة التعزيريــة ‪ ،‬وقــد انتهــى احلــق اخلــاص بالتنــازل ‪،‬‬\n‫أنكــر املدعــى عليــه قيامــه بضــرب زوجتــه والتســبب يف كســر أصبعها‬\n‫وأقــر بأنــه دخــل املنــزل فلــم يجدهــا فلمــا حضــرت وســألها أيــن كانــت‬\n‫فأجابتــه بــأن هــذا ليــس مــن شــأنه ‪ ،‬فحصــل بينهمــا شــجار فصفعهــا‬\n‫صفعتــن وبصــق عليهــا ‪ ،‬وقــرر بــأن اإلصابــة املشــار لهــا يف التقريــر‬\n‫قدميــة إثــر ســقوطها مــن الــدرج وأن زوجتــه كثيــرة اخلــروج مــن املنــزل‬\n‫بغيــر إذنــه وأفــادت الزوجــة وشــقيقها قيــام زوجهــا بضربهــا ‪ ،‬فأنكــر‬\n‫وأفــاد أنهــا دائمـ ًا تخــرج دون إذنــه وصــدر بحقهــا صــك شــرعي يتضمــن‬\n‫عــدم خروجهــا مــن البيــت إال بإذنــه وإلقــرار املدعــى عليــه قيامــه بصفــع‬\n‫زوجتــه صفعتــن والبصــق عليهــا وإلنــكاره قيامــه بضربهــا ضربــا‬\n‫مبرحــا والتســبب يف كســر أصبعهــا ‪ ،‬ولعــدم قيــام البينــة علــى ذلــك‬\n‫وبنــاء علــى التقريــر الطبــي قــررت احملكمــة مــا يلــي ‪ :‬أوال‪ /‬عــدم ثبــوت‬\n‫قيــام املدعــى عليــه بضــرب زوجتــه ضربــا مبرحــا والتســبب يف إصابتهــا‬\n‫بكســر أصبــع قدمهــا اليمنــى إال أن التهمــة القوية تتوجــه نحوه ‪ ،‬ولعدم‬\n‫وجــود ســوابق عليــه ‪ ،‬وملــا ظهــر عليــه مــن توبــة ونــدم‪ ،‬ولكونــه متــزوج‬\n‫ولديــه أطفــال‪ ،‬وهــذه مســوغات معتبــرة يف تخفيــف العقوبــة عنــه لــذا‬\n\n                                                                                    ‫‪26‬‬\n\f     ‫فقــد قـ َـر َرت تعزيــره لقــاء ذلــك بســجنه ملــدة أســبوع محســوبا منهــا مــدة‬\n     ‫توقيفــه وجلــده ثالثــن جلــدة دفعــة واحــدة‪ .‬ثانيــا‪ :‬ثبــت قيــام املدعــى عليــه‬\n     ‫بصفــع زوجتــه صفعتــن علــى وجههــا والبصــق عليهــا وألن هــذا الفعــل‬\n     ‫فيــه مخالفــة شــرعية حيــث نهــى النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬عــن‬\n     ‫تقبيــح الوجــه فمــن بــاب أولــى البصــق والضــرب علــى الوجــه وكل ذلــك‬\n     ‫إكرامـ ًا للوجــه‪ ،‬وملــا كان التعزيــر يبــدأ بالتوبيــخ وينتهــي بالقتــل كمــا‬\n     ‫نــص علــى ذلــك الفقهــاء‪ ،‬فقــد جــرى توبيــخ املدعــى عليــه ولومــه علــى‬\n     ‫فعلــه‪ .‬ثالثــا‪ :‬أخــذ التعهــد علــى املدعــى عليــه بعــدم تكــرار مــا بــدر منــه‬\n     ‫وقــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام وطلــب رفعــه‬\n         ‫لالســتئناف بــدون الئحــة‪ .‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬املــازم القضائــي باحملكمــة‬\n     ‫اجلزائيــة باألحســاء يف املكتــب القضائــي وبنــاء علــى املعاملــة احملالــة‬\n     ‫مــن رئيــس احملكمــة اجلزائيــة باألحســاء برقــم ( ) يف ‪1434/1/10‬هـ ـ‬\n     ‫واملقيــدة برقــم ( ) يف ‪1434/1/10‬ه ـ وبنــاء علــى تعميــدي مــن فضيلــة‬\n     ‫الشــيخ ‪ ..........‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب‬\n     ‫خطابــه رقــم ( ) يف ‪1434/4/21‬ه ـ لنظــر القضايــا مــا عــدا الســجناء‬\n     ‫ويف يــوم األربعــاء املوافــق ‪1434/4/24‬ه ـ افتتحــت اجللســة األولــى‬\n     ‫يف متــام الســاعة التاســعة يف هــذه القضيــة رقــم ( ) وفيهــا حضــر‬\n     ‫املدعــي العــام ‪..........‬الســعودي بالســجل املدنــي رقــم (‪ )..........‬وحضــر‬\n     ‫حلضــوره املدعــى عليــه ‪ ..........‬الســعودي بالســجل املدنــي رقــم (‪)..........‬‬\n     ‫وبســؤال املدعــي العــام عــن دعــواه قــال بصفتــي مدعيــا عامــا بدائــرة‬\n\n‫‪27‬‬\n\f‫االدعــاء العــام مبحافظــة األحســاء أدعــي علــى كل ‪ ،........../‬البالــغ‬\n‫مــن العمــر (‪ )41‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي‬\n‫رقم‪..........‬أوقــف بتاريــخ ‪ 1433/11/8‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n‫‪1433/11/9‬ه ـ يســكن مبحافظــة األحســاء ‪ /‬قريــة ‪...........‬إنــه بتاريــخ‬\n‫‪1433/10/23‬ه ـ تقــدم املدعو‪........../‬ببــاغ مفــاده تعــرض شــقيقته‬\n‫املدعوة‪........../‬لالعتــداء بالضــرب مــن قبــل املدعــى عليــه (زوجهــا)‬\n‫والتســبب يف إصابتهــا‪ .‬وبضبــط أقــوال املجنــي عليها‪........../‬أفــادت‬\n‫انــه بتاريــخ ‪1433/10/20‬ه ـ وأثنــاء تواجدهــا مبنــزل زوجهــا وقيامهــا‬\n‫بإعــداد طعــام اإلفطــار لــه حصــل بينهمــا ســوء تفاهــم ممــا أدى باملدعــى‬\n‫عليــه بضربهــا وركلهــا وســقوطها علــى األرض والتســبب يف إصابتهــا‬\n‫وقــد صــدر بحقهــا التقريــر الطبــي رقــم(‪ )..........‬وتاريخ‪1433/11/1‬ه ـ‬\n‫مــن مستشــفى امللــك فهــد بالهفــوف املتضمــن إصابتهــا بكســر بإصبــع‬\n‫قدمهــا اليمنــى ومــدة الشــفاء أربعــة أســابيع مــا لــم حتــدث مضاعفــات‬\n‫وباســتجواب املدعــى عليــه أقــر بقيامــه بضــرب زوجتــه (‪ )..........‬بســبب‬\n‫خــاف حــدث بينهمــا‪ .‬وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه‬\n‫بضــرب زوجتــه ضربــا مبرحــا والتســبب يف اصابتهــا اإلصابــة املوصوفــة‬\n‫يف التقريــر الطبــي ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬إقراره حتقيقا‬\n‫املــدون علــى الصفحــة رقــم ( ‪ ) 13 - 12‬مــن ملــف تقريــر األحــوال األمنية‬\n                                                       ‫املوحــد املرفــق لفــة رقــم(‪. )1‬‬\n‫‪ -2‬بــاغ شــقيق املجنــي عليهــا املــدون علــى الصفحــة رقــم(‪ )1‬مــن ملــف‬\n                          ‫تقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم(‪. )1‬‬\n‫‪ -3‬مــا جــاء يف أقــوال املجنــي عليهــا املــدون علــى الصفحــة رقــم(‪-10-9‬‬\n       ‫‪ )11‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم(‪.)1‬‬\n\n\n                                                                                            ‫‪28‬‬\n\f                                                     ‫‪ -4‬التقرير الطبي املرفق لفة ( ‪.)9‬‬\n     ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة ‪ .‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة رادعــه لــه وزاجــرة لغيــره لقــاء مــا أســند إليــه مــن اتهــام ‪.‬‬\n     ‫(علمـ ًا أن احلــق اخلــاص انتهــى بالتنــازل) ‪ .‬هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n     ‫مــن قيامــي بضــرب املجنــي عليهــا ضربــا مبرحــا وركلهــا وســقوطها‬\n     ‫علــى األرض والتســبب يف إصابتهــا بكســر أصبــع قدمهــا اليمنــى فغيــر‬\n     ‫صحيــح والصحيــح أنــه يف نفــس اليــوم الــذي حصلــت فيــه املشــكلة‬\n     ‫كنــت عائــدا مــن العمــل الســاعة العاشــرة صباحــا فدخلــت بيتــي فلــم‬\n     ‫أجــد املجنــي عليهــا يف البيــت وبعــد مضــي ربــع ســاعة تقريبــا دخلــت‬\n     ‫املجنــي عليهــا إلــى البيــت ومعهــا طفلــي فقمــت بســؤالها أيــن كنتــي‬\n     ‫فــردت علــي ليــس لــك دخــل أطلــع أو مــا أطلــع فقلــت لهــا أنا ولــي أمرك ال‬\n     ‫بــد مــن أخــذ أذنــي يف اخلــروج فقامــت برفــع صوتهــا علــي فقمــت بضربهــا‬\n     ‫كفــن علــى وجههــا وقمــت بالبصــق عليهــا ولــم أقــم بكســر أصبعهــا‬\n     ‫مطلقــا وإمنــا هــذه اإلصابــة قدميــة حيــث إن املجنــي عليهــا ســقطت مــن‬\n     ‫الــدرج فحصلــت لهــا هــذه اإلصابــة واملجنــي عليهــا دائمــا تخــرج مــن‬\n     ‫بيتــي بــدون أذنــي وقــد صــدر بحقهــا صــك شــرعي صــادر مــن قاضــي‬\n     ‫األوقــاف واملواريــث برقــم (‪ )..........‬يف ‪1424/10/20‬ه ـ يتضمــن عــدم‬\n     ‫خروجهــا مــن بيتــي إال بــأذن منــي هكــذا أجــاب هــذا فتــم اطالعــي علــى‬\n     ‫الصــك املذكــور فوجدتــه مطابــق ملــا ذكــره هــذا فتــم ســؤاله عــن عمــره‬\n     ‫فقــال أبلــغ مــن العمــر ‪ 41‬عامــا هكــذا قــال كمــا مت ســؤاله عــن عملــه‬\n\n\n‫‪29‬‬\n\f‫فقــال أعمــل يف إدارة التربيــة والتعليــم هكــذا قــال كمــا مت ســؤاله‬\n‫هــل لديــه أطفــال فقــال نعــم لــدي ســتة أطفــال هكــذا قــال وبطلــب‬\n‫البينــة مــن املدعــي العــام اســتعد بإحضارهــا يف اجللســة القادمــة وذلــك‬\n‫يف يــوم األحــد ‪1434/5/19‬ه ـ الســاعة العاشــرة والنصــف واهلل املوفــق‬\n‫واختتمــت اجللســة يف متــام الســاعة التاســعة والنصــف صباحــا وللبيــان‬\n‫حرر يف ‪1434/4/24‬هـ وصلى اهلل على نبينا محمد وعلى آله وصحبه‬\n‫وســلم‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/5/19‬ه ـ افتتحــت‬\n‫اجللســة الثانيــة يف متــام الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي‬\n‫العــام ‪..........‬وحضــر حلضــوره املدعــى عليــه‪ ..........‬املذكــورة هويتهمــا‬\n‫ســابقا وبطلــب البينــة مــن املدعــي العــام التــي اســتعد بإحضارهــا يف هــذه‬\n‫اجللســة قــال ليــس لــدي بينــة ســوى مــا ورد يف أوراق املعاملــة هكــذا قــال‬\n‫هــذا فتــم اطالعــي علــى بــاغ شــقيق املجنــي عليهــا املــدون علــى الصفحة‬\n‫رقــم (‪ )1‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد املرفــق يف املعاملــة‬\n‫علــى اللفــة رقــم (‪ )1‬ويتضمــن (تعــرض املجنــي عليهــا باالعتــداء عليهــا‬\n‫بالضــرب مــن قبــل زوجهــا وذلــك بســبب ســوء تفاهــم حصــل بينهمــا ممــا‬\n‫نتــج عنــه إصابــة املجنــي عليهــا بالقــدم اليمنــى وكســر بأصبــع اإلبهــام‬\n‫للقــدم اليمنــى) أ‪.‬هـ ـ وبعرضــه علــى املدعــى عليــه قــال غيــر صحيــح فأنــا‬\n‫لــم أقــم بالتســبب لهــا باإلصابــة املذكــورة وإمنــا هــي إصابــة قدميــة حدثــت‬\n‫لهــا ملــا ســقطت املجنــي عليهــا مــن الــدرج هكــذا قــال كمــا مت اطالعــي‬\n‫علــى إفــادة املجنــي عليهــا املدونــة علــى الصفحــة رقــم (‪ )10‬مــن ملــف‬\n‫تقريــر األحــوال األمنيــة املوحــد املرفــق يف املعاملــة علــى اللفــة رقــم (‪)1‬‬\n‫وتتضمــن (حضــر زوجــي املدعــى عليــه وقمــت بإحضــار وجبــة اإلفطــار‬\n‫لــه وبعــد ذلــك طلــب منــي الذهــاب إلــى منــزل أهلــي فقلــت لــه ســوف‬\n\n\n                                                                                       ‫‪30‬‬\n\f     ‫أذهــب وبعــد ذلــك قــام بضربــي بيديــه وركلــي عــدة ركالت بقدميــه‬\n     ‫وكذلــك قــام برمــي ترمــس الشــاي علــي وكذلــك دفعنــي بيــده ممــا‬\n     ‫أدى لســقوطي علــى األرض وحصلــت بــي إصابــة بقدمــي اليمنــي وكــذا‬\n     ‫أصبــع إبهــام قدمــي اليمنــى) أ‪.‬ه ـ ـ وبعرضــه علــى املدعــى عليــه قــال غيــر‬\n     ‫صحيــح جملــة وتفصيــا والصحيــح مــا ذكرتــه يف إجابتــي هكــذا قــال‬\n     ‫كمــا مت اطالعــي علــى التقريــر الطبــي ويتضمــن (إصابــة املجنــي عليهــا‬\n     ‫بكســر يف األصبــع الكبيــر للقــدم اليمنــى‪ .‬ومــدة الشــفاء أربعة أســابيع‬\n     ‫مــا لــم حتــدث مضاعفــات ســبب اإلصابــة ادعــاء باعتــداء بالضرب)أ‪.‬هـ ـ‬\n     ‫وبعرضــه علــى املدعــى عليــه قــال‪ :‬غيــر صحيــح هكــذا قــال هــذا فتــم‬\n     ‫ســؤال املدعــى عليــه هــل لديــك بينــة على أن كســر أصبــع زوجتك كان‬\n     ‫بســبب ســقوطها مــن الــدرج قــال‪ :‬ال هكــذا قــال فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بضــرب زوجتــه كفــن‬\n     ‫علــى وجههــا والبصــق عليهــا وحيــث أنكــر املدعــى عليــه قيامــه بضــرب‬\n     ‫زوجتــه ضربــا مبرحــا والتســبب يف إصابتهــا بكســر أصبــع قدمهــا‬\n     ‫اليمنــى وحيــث ال يوجــد بينــة لــدى املدعــي العــام ســوى مــا ورد يف أوراق‬\n     ‫املعاملــة وبعــد االطــاع علــى إفــادة املجنــي عليهــا وعلــى التقريــر الطبــي‬\n                                                   ‫لذلــك كلــه فقــد قــررت مــا يلــي ‪:‬‬\n     ‫أوال‪ :‬لــم يثبــت لــدي قيــام املدعــى عليــه بضــرب زوجتــه ضربــا مبرحــا‬\n     ‫والتســبب يف إصابتهــا بكســر أصبــع قدمهــا اليمنــى إال أن التهمــة‬\n     ‫القويــة تتوجــه نحــوه ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق‬\n     ‫وملــا ظهــر عليــه مــن توبــة ونــدم ولكونــه متــزوج ولديــه أطفــال وهــذه‬\n     ‫مســوغات معتبــرة يف تخفيــف العقوبــة عنــه لــذا فقــد قــررت تعزيــره لقــاء‬\n     ‫ذلــك بســجنه ملــدة أســبوع محســوب ًا منهــا مــدة توقيفــه وجلــده ثالثــن‬\n\n\n‫‪31‬‬\n\f                                                             ‫جلــدة دفعــة واحــدة‪.‬‬\n‫ثانيــا‪ :‬ثبــت لــدي قيــام املدعــى عليــه بضــرب زوجتــه كفــن علــى وجههــا‬\n‫والبصــق عليهــا وحيــث إن هــذا الفعــل فيــه مخالفــة لألوامــر الشــرعية‬\n‫منهــا قولــه تعالــى‪، :‬وعاشــروهن باملعــروف‪[ ،‬النســاء‪ ]19:‬وحلديــث‬\n‫معاويــة بــن حيــدة ‪ -‬رضــي اهلل عنــه ‪ -‬قــال‪ :‬قلــت يــا رســول اهلل مــا حــق‬\n‫زوجــة أحدنــا عليــه قــال‪(( :‬أن تطعمهــا إذا طعمــت‪ ،‬وتكســوها إذا‬\n‫اكتســيت‪ ،‬وال تضــرب الوجــه وال تقبــح وال تهجــر إال يف البيــت)) رواه‬\n‫أحمــد وأبــو داود وصححــه ابــن حبــان وقــال األلبانــي‪ :‬حســن صحيــح‪.‬‬\n‫فــإذا نهــى النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬عــن تقبيــح الوجــه فمــن بــاب‬\n‫أولــى البصــق والبــزق والضــرب علــى الوجــه وكل ذلــك إكرام ًا للوجه‪،‬‬\n‫فقــد قــال النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪(( :-‬إذا قاتــل أحدكــم أخــاه‬\n‫فليجتنــب الوجــه)) رواه مســلم فقــد جــاء يف كتــاب شــرح صحيــح مســلم‬\n‫لإلمــام النــووي ‪ -‬رحمــه اهلل ‪ -‬مــا نصــه‪(( :‬هــذا تصريــح بالنهــي عــن‬\n‫ضــرب الوجــه؛ ألنــه لطيــف يجمــع احملاســن وأعضــاؤه نفيســة لطيفــة‬\n‫وأكثــر اإلدراك بهــا‪ ،‬فقــد يبطلهــا ضــرب الوجــه وقــد ينقصهــا وقــد‬\n‫يشــوه الوجــه‪ ،‬والشــن فيــه فاحــش؛ ألنــه بــارز ظاهــر ال ميكــن ســتره‪،‬‬\n‫ومتــى ضربــه ال يســلم مــن شــن غالب ـاً‪ ،‬ويدخــل يف النهــي إذا ضــرب‬\n‫زوجتــه أو ولــده أو عبــده ضــرب تأديــب فليجتنــب الوجــه)) [‪،]165/16‬‬\n‫ولكــون التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل كمــا نــص علــى ذلــك‬\n‫الفقهــاء ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق وملــا ظهــر‬\n‫عليــه مــن توبــة ونــدم ولكونــه متــزوج ولديــه أطفــال وهــذه مســوغات‬\n‫معتبــرة يف تخفيــف العقوبــة عنــه لــذا فقــد مت توبيــخ املدعــى عليــه ولومــه‬\n‫علــى فعلــه وإفهامــه مبغبــة عملــه ونتائجــه وآثــاره الســلبية علــى زوجتــه‬\n\n\n                                                                                      ‫‪32‬‬\n\f                                                                           ‫وعلــى أوالده ‪.‬‬\n     ‫ثالثــا‪ :‬أخــذ التعهــد الشــديد علــى املدعــى عليــه بعــدم تكــرار مــا بدر منه‬\n     ‫ومبــا ســبق كلــه حكمــت وبعرضــه علــى املدعــى عليــه قــرر القناعــة بــه‬\n     ‫كمــا قــرر املدعــي العــام املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة‬\n     ‫الدعــوى عــن تقــدمي الئحــة اعتراضيــة وبذلــك تكــون القضيــة منتهيــة‬\n     ‫وقــررت بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف بالشــرقية‬\n     ‫لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق واختتمــت اجللســة يف‬\n     ‫متــام الســاعة احلاديــة عشــرة صباحــا وللبيــان حــرر يف ‪1434/5/19‬ه ـ ـ‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم تســليما كثيــرا‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 3466584‬وتاريــخ ‪1434/6/10‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 341447048‬وتاريــخ ‪1434/6/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪..........‬املســجل برقــم‬\n     ‫وتاريــخ ‪1434/5/29‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف‬\n     ‫قضيــة إيــذاء زوجتــه وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم حــرر يف ‪1434/6/25‬ه ـ‬\n\n\n\n\n‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":25,"source_page_end":33,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a26efed8c3d8a454ecd2dce215e1177e30be4319d2d1b2196666233706da11f","normalized_text_hash":"aa9bf922bf795c596ba027dcb171d1416a06ed5699da2cc4dd111d1762976b70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p25-34226948"},{"id":"5fa66688-7849-58da-b1ab-44efbc80005c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -ضرب -شروع يف القتل -تقرير طبي -إقرار -تعزير بالسجن","document_number":"34198838","case_number":"3427354","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/27","year":"1434","subject":"إيذاء -ضرب -شروع يف القتل -تقرير طبي -إقرار -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"             ‫رقم الصك ‪ 34198838 :‬تاريخه‪:‬‬\n      ‫‪1434/04/27‬هـ رقم الدعوى‪3427354:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 34212869‬تاريخه‪1434/05/14 :‬هـ‬\n\n\n\n‫إيذاء‪ -‬ضرب ‪ -‬شــروع يف القتل ‪ -‬تقرير طبي ‪ -‬إقرار ‪ -‬تعزير بالســجن‬\n                                                          ‫واجللد‪.‬‬\n\n\n\n\n        ‫‪-‬قول اهلل تعالى‪« :‬وال تقتلوا النفس التي حرم اهلل إال باحلق» ‪.‬‬\n‫‪-‬قــال صلــى اهلل عليــه وســلم ‪« :‬مــن أخــاف مؤمنــا كان حــق علــى اهلل‬\n                                       ‫أال يؤمنــه مــن أفــزاع يــوم القيامــة»‬\n‫‪ -‬قــال صلــى اهلل عليــه وســلم ‪« :‬مــن أشــار إلــى أخيــه بحديــدة فــإن‬\n‫املالئكــة تلعنــه حتــى يدعــه وإن كان أخــاه ألبيــه وأمــه» رواه مســلم ‪.‬‬\n\n\n\n\n‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بالشــروع يف قتــل زوج‬\n‫أختــه وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب‬\n‫يف إصابتــه بعــدة إصابــات موصوفــة بالتقريــر الطبــي‪ ،‬وذلــك بعدمــا مت‬\n‫القبــض علــى املدعــى عليــه إثــر ورود بــاغ للجهــات املختصــة يتضمــن‬\n‫وجــود شــخص مصــاب لتعرضــه للضــرب ب ــآلة حــادة فــأس مــن قبــل‬\n‫املدعــى عليــه ‪ ،‬صــدر بحقــه التقريــر الطبــي ومــدة الشــفاء ســتة أشــهر‪،‬‬\n‫بالبحــث عــن ســوابقه عثــر لــه على ســابقة مضاربة ‪ ،‬طلــب املدعي العام‬\n‫إثبــات مــا أســند إلــى املدعــى عليــه واحلكــم بعقوبــة تعزيريــة مشــددة‬\n\n                                                                                   ‫‪34‬‬\n\f     ‫‪ ،‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة‬\n     ‫ا ‪ ،‬جــرى االطــاع علــى التقريــر الطبــي ‪ ،‬وعلــى كــرت ســوابق‬        ‫وتفصيـ ً‬\n     ‫املدعــى عليــه املشــار إليهمــا‪ ،‬نظــر ًا ألن املدعــى عليــه صــادق علــى دعــوى‬\n     ‫املدعــي العــام ومبــا أن الشــريعة اإلســامية حرصــت علــى حفــظ النفــس‬\n     ‫وصيانتهــا وحمايتهــا مــن االعتــداء عليهــا وجتنيبهــا األضــرار التــي تفتــك‬\n     ‫بهــا ووضعــت كافــة الوســائل املؤديــة إلــى احملافظــة عليهــا لــذا وألجــل‬\n     ‫احلــق العــام فقــد ثبتــت إدانــة املدعــى عليــه بقيامــه بالشــروع يف قتــل زوج‬\n     ‫أختــه وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n     ‫إصابتــه بعــدة إصابــات ومت احلكــم بتعزيــره بالســجن مــدة أربــع ســنوات‬\n     ‫وجلــده ثمامنائــة جلــدة مفرقــة علــى ســت عشــرة دفعــة علــى أن يكــون‬\n     ‫اجللــد علنــا ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة وقــرر‬\n     ‫املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة‪ ،‬وبعــد‬\n                        ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي باحملكمــة العامــة بأبــو‬\n‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫برقــم ‪ 3427354‬وتاريــخ ‪1434/01/17‬ه ـ واملقيــدة باحملكمــة برقــم‬\n‫‪ 34129844‬وتاريــخ ‪ 1434/01/17‬ه ـ وقــد عــادت إلينــا املعاملــة مــن‬\n‫هيئــة التحقيــق واالدعــاء العــام ه ـ ج‪ 875/2/3‬وتاريــخ ‪1434/4/17‬ه ـ‬\n‫واملقيــدة لدينــا برقــم ‪ 34991160‬وتاريــخ ‪1434/4/22‬هـ عليه ففي هذا‬\n‫اليــوم الســبت املوافق‪1434/04/27‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء‬\n‫العــام ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬واملفــوض‬\n‫باخلطــاب رقــم ‪........‬وتاريــخ ‪1429/11/3‬ه ـ وأدعــى قائــا بصفتــي‬\n‫مدعيــا عامــا يف دائــرة االدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى‬\n‫‪30........‬عامـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬مــودع‬\n‫بقســم ســجن أبــو عريــش مبوجــب أمر متديــد التوقيف واإلحالة رقــم‪........‬‬\n‫وتاريــخ ‪1433/11/8‬ه ـ اســتناد ًا للقــرار الــوزاري ‪ 1900‬ويعتبــر إيقافــه‬\n‫مــن تاريــخ القبــض عليــه أنــه يف متــام الســاعة الرابعــة والنصــف مــن صبــاح‬\n‫يــوم االثنــن املوافــق ‪1433/10/23‬ه ـ ورد بــاغ لشــرطة وادي جــازان‬\n‫عــن طريــق العمليــات يتضمــن وجــود شــخص مصــاب يدعــى ‪........‬إثــر‬\n‫تعرضــه للضــرب ب ــآلة حــادة فــأس مــن قبــل املدعــى عليــه وبإحالتــه‬\n‫ملستشــفى أبــو عريــش العــام صــدر بحقــه التقريــر الطبــي رقــم ‪........‬‬\n‫وتاريــخ ‪1433/10/ 24‬ه ـ املتضمــن هبــوط حــاد بالــدورة الدموية ونزيف‬\n‫شــديد كســور متعــدد بعظمــة الزنــد األيســر وقطــع بالعضــات وقطــع‬\n\n                                                                                      ‫‪36‬‬\n\f     ‫بالعصــب الزنــدي واألوســط وكســور متعــدد مبشــطيات اليــد اليســرى‬\n     ‫ومت التثبيــت باســتخدام أســياخ‪ ،‬وكســور متعــدد بعظمــة الزنــد األميــن‬\n     ‫وقطــع بالعصــب الوحشــي وقطــع متعــدد باألوتــار والعضــات ووضــع‬\n     ‫اليــد يف جبــس فــوق الكــوع أمــا بالنســبة لقطــع أعصــاب املريــض يحتــاج‬\n     ‫لدراســة توصيــل األعصــاب إلجــراء جراحــي يف مراحــل الحقــة بعــد‬\n     ‫التئــام اجلــروح وكســور متعــددة بالكاحــل األيســر وعظمــة الشــظية‬\n     ‫وعظمــة القصبــة اليســرى وقطــع بالعضــات ومت التثبيــت بواســطة‬\n     ‫أســياخ وتوصيــل العضــات وجــروح قطعيــة متعــددة بالســاق والفخــذ‬\n     ‫األميــن ومت إصــاح هــذه اجلــروح ومــدة الشــفاء ســتة أشــهر وبســماع‬\n     ‫أقــوال املجنــي عليــه أفــاد بــأن مــن قــام بضربــه هــو املدعــى عليــه أثــر‬\n     ‫خــاف بينــه وبــن زوجتــه أي أخــت املدعــى عليــه وباســتجواب املدعــى‬\n     ‫عليــه ومواجهتــه بالتهمــة املنســوبة إليــه أفــاد بأنــه ذهــب ملنــزل زوج أختــه‬\n     ‫‪........‬وقــام بإطفــاء الكهربــاء مــن عــداد الكهربــاء اخلارجــي ودخــل‬\n     ‫حــوش املنــزل وقــام بضــرب جــدار منــزل ‪........‬املذكــور بقطعــة بلــك‬\n     ‫حتــى اســتيقظ ‪........‬املذكــور وقــام بســؤال املجنــي عليــه عــن ســبب‬\n     ‫ضربــه ألختــه فقــال أنــه ال يريــد ضربهــا وإمنــا كان يريــد ضــرب ابنتــه‬\n     ‫‪........‬فقــال يريــد أخــذ حــق أختــه منــه وكان بيــده فــأس فقــام بضربــه‬\n     ‫بــه علــى اليــد اليمنــى ومــن ثــم اليســرى ومــن ثــم األقــدام وتركــه أمــام‬\n     ‫منزلــه ينــزف مــن الدمــاء وصــادق علــى إقــراره بذلــك شــرعا وقــد أســفر‬\n     ‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بالشــروع يف قتــل زوج أختــه‬\n     ‫‪........‬وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n     ‫إصابتــه بعــدة إصابــات موصوفــة بالتقريــر الطبــي املرفــق وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة‪ -1‬مــا جــاء يف إقــرار املصــادق عليــه شــرع ًا ص ‪ 5‬مــن‬\n\n\n‫‪37‬‬\n\f‫دفتــر التحقيــق املرفــق لفــة رقــم ‪2 .2‬ـ مــا جــاء يف محضــر القبــض املرفــق‬\n‫لفــة رقــم ‪3 .4‬ـ مــا جــاء بالتقريــر الطبــي املرفــق لفــة رقــم ‪ 49‬وبالبحــث‬\n‫عــن ســوابقه عثــر لــه علــى ســابقة مضاربــة وحيــث أن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم بعقوبــة تعزيريــة مشــددة تزجــره وتــردع غيــره علم ــا‬\n‫بــأن احلــق اخلــاص مــازال قائمــا وبعــرض دعــوى املدعي العــام على املدعى‬\n‫عليــه بعــد التأكــد مــن هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام مــن قيامــي بالشــروع يف قتــل زوج أختــي ‪........‬‬\n‫وذلــك مــن خــال ضربــي لــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n‫إصابتــه بعــدة إصابــات املوصوفــة يف دعــوى املدعــي العــام كلــه صحيــح‬\n‫وذلــك بعــد أن حضــر أحــد أفــراد القريــة وأخبرنــي أن ‪........‬قتــل أختــي‬\n‫مبطرقــة وأخذهــا اإلســعاف هكــذا أجــاب عقــب ذلــك جــرى االطــاع‬\n‫علــى التقريــر الطبــي رقــم ‪........‬وتاريــخ ‪1433/10/ 24‬ه ـ واملتضمــن‬\n‫هبــوط حــاد بالــدورة الدمويــة ونزيــف شــديد‪ ،‬كســور متعــدد بعظمــة‬\n‫الزنــد األيســر وقطــع بالعضــات وقطــع بالعصــب الزنــدي واألوســط‬\n‫وكســور متعــدد مبشــطيات اليــد اليســرى ومت التثبيــت باســتخدام‬\n‫أســياخ وكســور متعــدد بعظمــة الزنــد األميــن وقطــع بالعصــب الوحشــي‬\n‫وقطــع متعــدد باألوتــار والعضــات ووضــع اليــد يف جبــس فــوق الكــوع‬\n‫أمــا بالنســبة لقطــع أعصــاب املريــض يحتــاج لدراســة توصيــل األعصــاب‬\n‫إلجــراء جراحــي يف مراحــل الحقــة بعــد التئــام اجلــروح وكســور متعــددة‬\n‫بالكاحــل األيســر وعظمــة الشــظية وعظمــة القصبــة اليســرى وقطــع‬\n‫بالعضــات ومت التثبيــت بواســطة أســياخ وتوصيــل العضــات وجــروح‬\n‫قطعيــة متعــددة بالســاق والفخــذ األميــن ومت إصــاح هــذه اجلــروح ومــدة‬\n\n\n                                                                                    ‫‪38‬‬\n\f     ‫الشــفاء ســتة أشــهر عقــب ذلــك جــرى االطــاع علــى كــرت ســوابق‬\n     ‫املدعــى عليــه املرفــق لفــة رقــم ‪ 17‬فوجــدت بــه ســابقة اعتــداء كمــا‬\n     ‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املرفقــة لفــة رقــم‬\n     ‫‪ 14‬فوجــدت أنــه أوقــف بتاريــخ ‪1433/10/23‬ه ـ فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم املدعــى عليــه بقيامــه‬\n     ‫بالشــروع يف قتــل زوج أختــه ‪........‬وذلــك مــن خــال ضربــه بفــأس يف‬\n     ‫أطرافــه األربعــة ممــا تســبب يف إصابتــه بعــدة إصابــات موصوفــة يف‬\n     ‫دعــواه ومبــا أن املدعــي صــادق علــى دعــوى املدعــي العــام ومبــا أنــه‬\n     ‫جــرى االطــاع علــى التقريــر الطبــي املــدون مضمونــه بعاليــه ومبــا أن‬\n     ‫الشــريعة اإلســامية حرصــت علــى حفــظ النفــس وصيانتهــا وحمايتهــا‬\n     ‫مــن االعتــداء عليهــا وجتنيبهــا األضــرار التــي تفتــك بهــا ووضعــت كافــة‬\n     ‫الوســائل املؤديــة إلــى احملافظــة عليهــا قــال تعالــى وال تقتلــوا النفــس التــي‬\n     ‫حــرم اهلل إال باحلــق وحــرم النبــي صلــى اهلل عليــه وســلم تخويــف املســلم‬\n     ‫وترويعــه قــال عليــه الصــاة والســام مــن أخــاف مؤمنــا كان حــق علــى‬\n     ‫اهلل أال يؤمنــه مــن أفــزاع يــوم القيامــة ونهــى النبــي صلــى اهلل عليــه وســلم‬\n     ‫عــن اإلشــارة بالســاح وقــال مــن أشــار إلــى أخيــه بحديــدة فــإن املالئكــة‬\n     ‫تلعنــه حتــى يدعــه وإن كان أخــاه ألبيــه وأمــه رواه مســلم لذلــك كلــه‬\n     ‫وألجــل احلــق العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه‬\n     ‫بقيامــه بالشــروع يف قتــل زوج أختــه ‪........‬وذلــك مــن خــال ضربــه بفــأس‬\n     ‫يف أطرافــه األربعــة ممــا تســبب يف إصابتــه بعــدة إصابــات ثانيــا يعــزر‬\n     ‫املدعــى عليــه بالســجن ملــدة أربــع ســنوات مــن تاريــخ إيقافــه علــى ذمــة‬\n     ‫هــذه القضيــة وجلــده ثمامنائــة جلــدة مفرقــة علــى ســتة عشــر دفعــة كل‬\n     ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيام‬\n\n\n‫‪39‬‬\n\f‫علــى أن يكــون اجللــد علنــا وبــه حكمــت وبعــرض احلكــم علــى املدعــى‬\n‫عليــه قــرر القناعــة وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون‬\n‫الئحــة اعتراضيــة عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم وحتــى ال يخفــى جــرى تدوينــه وأقفلــت‬\n‫اجللســة يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/4/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بأبــي عريــش‬\n‫الشــيخ ‪........ /‬برقــم ‪ 34991160‬وتاريــخ ‪1434 /4/29‬ه ـ املرفــق بهــا‬\n‫القرار الصادر من فضيلـته برقم ‪ 34198838‬وتاريخ ‪1434/4/27‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪................ /‬يف قضيــة ( الشــروع‬\n‫يف قتــل زوج أختــه ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n                                   ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":34,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a184175fc5bd5d06847f4c3c1d54f628f46ed92fba10586f23137f4c0d2a431","normalized_text_hash":"b226ab59901eda50526b8223bfe0db8d69c3abfda9e54b43b423660174bd6727","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p34-34198838"},{"id":"8be86e7a-5f02-5ab0-89b2-397b533e7022","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -طعن -طعن بسكني «ساح أبيض» ،انتهاك حرمة املنزل -إحداث إصابات -ثبوت اإلدانة -تعزير بالسجن واجللد.","document_number":"3451474","case_number":"3437318","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"اعتداء -طعن -طعن بسكني «ساح أبيض» ،انتهاك حرمة املنزل -إحداث إصابات -ثبوت اإلدانة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3451474 :‬تاريخه‪1434/3/1 :‬هـ‬\n                          ‫رقم الدعوى‪3437318:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34174738‬تاريخه‪1434/03/29 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬طعــن ‪ -‬طعــن بســكني «ســاح أبيــض» ‪ ،‬انتهــاك حرمــة املنــزل‬\n                  ‫‪ -‬إحــداث إصابــات ‪ -‬ثبــوت اإلدانــة ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n     ‫‪-‬قولــه صلــى اهلل عليــه وســلم ( ال يشــير أحدكــم إلــى أخيــه بالســاح‬\n     ‫فإنــه ال يــدري أحدكــم لعــل الشــيطان ينــزع يف يــده فيقــع يف حفــرة‬\n                                                                   ‫مــن النــار)‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه لقيامــه بدخــول منــزل املجنــي عليــه‬\n     ‫عنــو ًة وطعنــه بســكني ممــا تســبب يف إصابتــه وطلــب إدانتــه وتعزيــره‬\n     ‫شــرعا لدخــول املدعــى عليــه ملنــزل املجنــي عليــه وحمله ســكني ( ســاح‬\n     ‫أبيــض ) ومفتــاح كفــر ممــا تســبب يف إصابتــه بجــرح يف يــده وقــدم‬\n     ‫املجنــي عليــه تقريــر ًا طبيـ ًا تأييــد ًا لدعــواه ‪ ،‬كمــا أقــر املدعــى عليه مبا‬\n     ‫جــاء يف الدعــوى ‪ ،‬أديــن املدعــى عليــه وحكــم عليــه بالســجن ملــدة أربعــة‬\n     ‫أشــهر اعتبــار ًا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة وبجلــده مائــة‬\n     ‫وخمســن جلــدة مفرقــه علــى دفعــات‪ ،‬قــرر املدعــي العــام االعتــراض‬\n     ‫وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة ‪ ،‬صــدق‬\n                                              ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪41‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n‫ـاء علــى املعاملــة احملالــة لنــا من فضيلــة رئيس احملكمة‬    ‫بأبــي عريــش وبنـ ً‬\n‫العامــة بأبــي عريــش برقــم ‪ 3437318‬وتاريخ‪1434/01/21‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34156823‬وتاريــخ ‪1434/01/19‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1434/02/20‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬مبوجــب تكليفــه باخلطــاب برقم هـ‪7‬جـ‬\n‫‪ 513/10/‬وتاريــخ ‪1429/11/3‬ه ـ الصــادر مــن دائــرة التحقيــق وحضــر‬\n‫حلضــوره ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬وبســؤال‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬    ‫املدعــي العــام عــن دعــواه أجــاب قائ ـ ً‬\n‫التحقيــق واالدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى ‪ ...‬البالــغ‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬البالــغ مــن العمــر اثنــان‬\n‫وعشــرون عام ـ ًا أوقــف مبوجــب أمــر التوقيــف رقــم ه ـ ج‪3383/2/2‬‬\n‫وتاريــخ ‪1433/11/24‬ه ـ ومــودوع بســحن أبــو عريــش مبوجــب أمــر‬\n‫التمديــد واإلحالــة رقــم ه ـ ‪ 2‬ج‪ 3429/2/‬وتاريــخ ‪1433/11/28‬ه ـ‬\n‫حيــث إنــه بتاريــخ ‪1433/11/23‬ه ـ تقــدم كل مــن املواطــن ‪ ....‬ســعودي‬\n‫اجلنســية و املواطــن ‪ ....‬ســعودي اجلنســية بدعــوى مفادهــا قيــام املدعــى‬\n‫عليــه أعــاه باالعتــداء عليهمــا بالضــرب وبســماع إفادة املدعــن أفادا أن‬\n‫املدعــى عليــه أعــاه قــد حضــر ملنــزل ‪ ....‬وقــام بدخــول احلــوش والتهجــم‬\n‫عليهمــا وكان يحمــل معــه ســكني ( ســاح أبيــض ) ومفتــاح كفــر ممــا‬\n‫تســبب يف إصابــة أحدهمــا بجــرح يف يــده وباســتجواب املدعــى عليــه أقــر‬\n\n                                                                                        ‫‪42‬‬\n\f     ‫بدخولــه ملنــزل املدعــو ‪ ....‬وهــو يريــد ‪ ....‬كونــه يطلبــه مبلــغ مــن املــال‬\n     ‫كمــا أقــر بقيامــه بطعــن ‪ ....‬بالســكني وصــادق علــى إقــراره حتقيق ـ ًا‬\n     ‫وقــد أفــرز التحقيــق عــن توجبيــه االتهــام ل‪ ...‬بقيامــه بالتهجــم علــى منــزل‬\n     ‫‪ ...‬والدخــول للحــوش وطعنــه بســكني ممــا تســبب يف إصابتــه وذلــك‬\n     ‫لألدلــة و القرائــن التاليــة ‪-1:‬ماجــاء بأقــوال املدعــى عليــه املدونــة ص‬\n     ‫‪ 2 1‬بدفتــر التحقيــق املرفــق لفــه رقــم ‪-2 14‬ماجــاء يف التقريــر الطبــي‬\n     ‫املرفــق لفــه رقــم ‪ 6‬ورقــم ‪ 4‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n     ‫ســوابق مســجله وحيــث أن مــا أقــدم عليــه املتهــم املذكــور فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا نســب إليــه واحلكــم بتعزيــره‬\n     ‫شــرع ًا علمــا بــأن احلــق مــازال قائمـ ًا هــذه دعــواي وبعــرض دعــوى املدعــي‬\n     ‫العــام علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف دعــوى املدعــي العــام‬\n     ‫صحيــح جملــة و تفصيــا هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر‬\n     ‫الطبــي بــدون رقــم و تاريــخ ‪1433/11/23‬ه ـ الصادر من مستشــفى ‪.......‬‬\n     ‫ب ـ ‪ ....‬والــذي جــاء فيــه توجــد كدمــات يف الذراعــن والركبتــن ومــدة‬\n     ‫الشــفاء خمســة أيــام وجــرى االطــاع علــى التقريــر الطبــي بــدون رقــم‬\n     ‫وتاريــخ ‪1433/11/23‬ه ـ اخلــاص ب ـ ‪ ....‬والــذي جــاء فيــه جــرح قطعــي‬\n     ‫علــى ظهــر اليــد اليســرى بطــول ثالثــة ونصــف يف خمســة ســم متــة خياطته‬\n     ‫بســبع غــرزات ومــدة الشــفاء ســبعة أيــام ثــم جــرى االطــاع علــى صحيفــة‬\n     ‫ســوابقه املوضــح بهــا عــدم وجــود ســوابق عليــه وجــرى االطــاع علــى‬\n     ‫مذكــرة إيقافــه حيــث كان إيقافــه بتاريــخ ‪1433/11/23‬ه ـ ثــم جــرى‬\n     ‫قفــل بــاب املرافعــة فبعــد مــا تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى‬\n     ‫أوراق املعاملــة وحيــث أن املدعــى عليــه أقــر وصــادق علــى دعــوى املدعــي‬\n     ‫العــام وحيــث أن مــا أقــدم عليــه املدعــي عليــه فعــل محــرم شــرع ًا لقولــه‬\n\n\n‫‪43‬‬\n\f‫صلــى اهلل عليــه وســلم ( ال يشــير أحدكــم إلــى أخيــه بالســاح فإنــه ال‬\n‫يــدري أحدكــم لعــل الشــيطان ينــزع يف يــده فيقــع يف حفــرة مــن النــار)‬\n‫وبنــاء علــى ذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بإقــراره مبــا‬\n‫أســند إليــه وحكمــت عليــه تعزيــر ًا للحــق العــام مبــا يلــي ‪ :‬أو ًال ســجنه‬\n‫ملــدة أربعــة أشــهر اعتبــار ًا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة ثانيـ ًا‬\n‫جلــده مائــة وخمســون جلــدة مفرقــه علــى دفعــات كل دفعــة خمســون‬\n‫جلــده بــن كل دفعــه وأخــرى عشــرة أيــام وبعــرض احلكــم علــى املدعــى‬\n‫عليــه قــرر القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفعه حملكمة‬\n‫االســتئناف بعســير بــدون الئحــة اعتراضيــة فأجبتــه إلــى طلبــه وقــررت‬\n‫رفعهــا حملكمــة االســتئناف بعســير وبــاهلل التوفيــق وأقفلــت اجللســة يف‬\n‫متــام الســاعة الثامنــة والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/20‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد مت دراســة الصــك وصــورة ضبطــه و اوراق‬\n‫املعاملــة مــن محكمــة االســتئناف مبنطقــة عســير ومتــت املصادقــة علــى‬\n                                                                               ‫احلكــم ‪.‬‬\n\n\n\n\n                                                                                              ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":41,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"367c09363d433e65c16fe0929d0a5478fa75d635fb57c41556adbc531d542c67","normalized_text_hash":"fa4010d52f2ccc78d8e7a8817118c5edaaea196f7567a6a7e1f53b662be5f27d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p41-3451474"},{"id":"cf93ca2d-435a-54b5-990a-8a12d328a6d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -طعن -طعن بسكني -إحداث إصابة بحجة الدفاع عن النفس -عدم ثبوت الدفاع عن النفس -ثبوت إدانة -التعزير بالسجن واجللد .","document_number":"3425051","case_number":"3440377","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/27","year":"1434","subject":"اعتداء -طعن -طعن بسكني -إحداث إصابة بحجة الدفاع عن النفس -عدم ثبوت الدفاع عن النفس -ثبوت إدانة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3425051 :‬تاريخه‪1434/01/27 :‬هـ‬\n                          ‫رقم الدعوى‪3440377 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34424707‬تاريخه‪1434/2/20 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬طعــن ‪ -‬طعــن بســكني ‪ -‬إحــداث إصابــة بحجــة الدفــاع عــن‬\n     ‫النفــس ‪ -‬عــدم ثبــوت الدفــاع عــن النفــس ‪ -‬ثبــوت إدانــة ‪ -‬التعزيــر‬\n                                                         ‫بالســجن واجللــد ‪.‬‬\n\n\n\n\n                    ‫‪ -‬قول اهلل تعالى ‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n     ‫‪ -‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬املســلم مــن ســلم املســلمون مــن‬\n     ‫لســانه ويــده )وقــال النبــي صلــى اهلل عليــه وســلم (مــن أشــار إلــى أخيــه‬\n     ‫بحديــده فــإن املالئكــة تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه )‪.‬‬\n                                    ‫‪ -‬املادة ‪ 152‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بطعــن املجنــي عليــه يف‬\n     ‫صــدره اجلهــة اليســرى بآلــة حــادة وطلــب إدانتــه وتعزيــره شــرعا إذ أنــه‬\n     ‫تبلــغ مركــز الشــرطة مــن املستشــفى عــن وجــود شــخص مصــاب لديهــم‬\n     ‫بطعــن ‪ ،‬وقــد جــرى االنتقــال ملوقــع احلادثــة وأفــاد املجنــي عليــه أنــه أثنــاء‬\n     ‫ســيره علــى األقــدام يرافقــه اثنــان مــن أصدقائــه ‪ ،‬تعــرض لــه املدعــى‬\n     ‫عليــه بطعنــه بســكني يف اجلهــة اليســرى مــن الصــدر ‪ ،‬وال يعلــم عــن‬\n         ‫ســبب قيــام املدعــى عليــه بطعنــه وال توجــد بينــه وبــن املدعــى عليــه‬\n\n‫‪45‬‬\n\f‫أيــة مشــاكل مــن الســابق ‪ ،‬وقــد صــدر بحقــه التقريــر الطبــي واملتضمن‬\n‫إصابتــه بطعنــة يف الصــدر األيســر علــى مســتوى الضلــع الســادس يف‬\n‫اجلهــة األماميــة ومــدة الشــفاء شــهر‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف‬\n‫الدعــوى ودفــع بأنــه أراد الدفــاع عــن نفســه وال بينــة لــه علــى أن املجنــي‬\n                            ‫عليــه قــام مبهاجمتــه قــررت احملكمــة مــا يلــي ‪:‬‬\n‫أوالً‪ :‬ثبــت إدانــة املدعــى عليــه وحكــم عليــه ‪ ،‬بالســجن مــدة أربعــة‬\n‫أشــهر مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة ‪ ،‬بجلــد املدعــى عليــه‬\n‫مائتــان وخمســون جلــدة مفرقــة علــى خمــس دفعــات كل دفعــة خمســون‬\n‫جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ ،‬قــرر املدعــي‬\n‫العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه‬\n                        ‫القناعة‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪46‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة العامــة بأبــو‬\n     ‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بأبــو عريــش برقــم ‪ 3440377‬وتاريــخ ‪ 1434/01/24‬ه ـ املقيــدة‬\n     ‫باحملكمة برقم ‪ 34185872‬وتاريخ ‪ 1434/01/21‬هـ ففي هذا اليوم‬\n     ‫الثالثــاء املوافــق ‪1433/1/27‬ه ـ افتتحــت اجللســة األولــى يف متام الســاعة‬\n     ‫احلاديــة عشــر و النصــف وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق‬\n     ‫واالدعــاء العــام ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫املفــوض باخلطــاب رقــم هــ‪7‬ج‪ 513/‬وتاريــخ ‪1428/7/9‬ه ـ وأدعــى قائــا‬\n     ‫بصفتــي مدعيــا عامــا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة أبــو‬\n     ‫عريــش أدعــي علــى ‪ 19 ....‬عامــا مينــي اجلنســية مبوجــب البطاقــة البديلــة‬\n     ‫رقــم ‪......‬ع ض وتاريــخ ‪1434/1/5‬ه ـ مــودع بقســم ســجن أبــو عريــش‬\n     ‫كــون جرميتــه مــن اجلرائــم املوجبــة للتوقيــف اســتنادا للقــرار الــوزاري‬\n     ‫رقــم ‪ 1900‬وتاريــخ ‪1428/8/9‬ه ـ إنــه يف متــام الســاعة الثامنــة والنصــف‬\n     ‫مــن مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ تبلــغ مركــز شــرطة‬\n     ‫‪ ......‬مــن قبــل مستشــفى ‪ .........‬عــن وجــود شــخص مصــاب لديهــم بطعــن‬\n     ‫وقــد جــرى االنتقــال ملوقــع احلادثــة الــذي يقــع شــرق محافظــة ‪ ......‬بحوالي‬\n     ‫خمســن كيلــو متــر علــى اخلــط الدائــري رفــق األدلــة اجلنائيــة ومت‬\n     ‫إكمــال الــازم حيــال املعاينــة وبضبــط إفــادة املجنــي عليــه ‪ ....‬والــذي‬\n     ‫أفــاد أنــه يف مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ وعنــد الســاعة‬\n     ‫الثامنــة وأثنــاء ســيره علــى األقــدام علــى اخلــط الدائــري ‪ ........‬وبالتحديــد‬\n     ‫غــرب ‪ .........‬وكان يرافقــه كال مــن ‪ ...‬واملدعــو ‪ ....‬مــن أجــل املشــي‬\n\n‫‪47‬‬\n\f‫الرياضــي عندهــا تعــرض لــه املدعــى عليــه بطعنــه بســكني يف اجلهــة‬\n‫اليســرى مــن الصــدر وال يعلــم عــن ســبب قيــام املدعــى عليــه بطعنــه وال‬\n‫توجــد بينــه وبــن املدعــى عليــه أي مشــاكل مــن الســابق وقــد صــدر‬\n‫بحقــه التقريــر الطبــي رقــم ‪ 23623‬وتاريــخ ‪1433/11/9‬ه ـ واملتضمــن‬\n‫إصابتــه بطعنــه يف الصــدر األيســر علــى مســتوى الضلــع الســادس يف‬\n‫اجلهــة األماميــة ومــدة الشــفاء شــهر وبضبــط شــهادة الشــهود أفــاد كال‬\n‫مــن ‪ ...‬و‪....‬أنهمــا يف مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ كانــا‬\n‫برفقــة املجنــي عليــه ‪ ....‬وكانــوا يســيرون مشــيا علــى األقــدام رياضــة‬\n‫علــى خــط ‪ .......‬ومــع أذان العشــاء توقفــوا للصــاة وبعدهــا شــاهدوا‬\n‫شــخص واقــف بجوارهــم فذهــب املجنــي عليــه ‪ ...‬للتفاهــم معــه وحــال‬\n‫وصولــه إليــه قــام املدعــى عليــه بطعــن املجنــي عليــه بســكني وبعدهــا‬\n‫قــام الشــاهدان بإمســاك املدعــى عليــه وتســليمه للشــرطة وباســتجواب‬\n‫املدعــى عليــه ومواجهتــه بالتهمــة املنســوبة إليــه والــذي أفــاد أنــه يف مســاء‬\n‫يــوم الســبت املوافــق ‪1433/10/21‬ه ـ حوالــي الســاعة الثامنــة جلــس‬\n‫علــى اخلــط الدائــري لوحــده ولــم يكــن يرافقــه أي أحــد وكان الشــارع‬\n‫مظلــم وأثنــاء جلوســه غــرب قرية‪.......‬عندهــا حضــر لــه ثالثــة أشــخاص‬\n‫ولــم يشــعر بهــم إال وقــت قيامهــم بالهجــوم عليــه وعندهــا قــام مفــزوع وال‬\n‫يعلــم مــن األشــخاص وعنــد حضــور أحــد األشــخاص إليــه قــام بطعنــه‬\n‫بســكني يف صــدره مــن اجلهــة اليســرى أســفل الثــدي بعدهــا قــام برمــي‬\n‫الســكني يف مــكان بعيــد وعندهــا حضــر مرافقــي الشــخص االثنــن‬\n‫اآلخريــن وقامــوا بإمســاكه وتربيطــه وقــام املدعــو ‪ ....‬بإمســاكه‬\n‫واآلخــر ال يعــرف اســمه قــام بضربــه بعصــا وذلــك بعــد أن قــام بطعــن‬\n‫صاحبهــم األول والــذي اتضــح أنــه بعــد فــك اللثــام أنــه املدعــو ‪ ...‬وقــد‬\n\n\n                                                                                        ‫‪48‬‬\n\f     ‫كانــوا يلبســون مالبــس ســوداء جميعهــم الثالثــة وبعــد املشــكلة أفــادوه‬\n     ‫بأنهــم ميزحــون معــه وقــد أحضــروا ســيارة وأخــذوا املطعــون إلســعافه‬\n     ‫وأنــه املتســبب يف إصابــة ‪ ....‬وذلــك بطعنــه بالســاح األبيــض الســكني‬\n     ‫وأن اإلصابــات التــي كانــت بــه مــن مرافقــي ‪ ...‬املذكــور وأنــه ليــس‬\n     ‫بينــه وبــن ‪ ...‬أي مشــاكل مــن الســابق وأن قيامــه بطعــن املدعــي هــو‬\n     ‫دفــاع عــن نفســه أثنــاء هجومهــم عليــه يف موقــع مظلــم وقــد صــدر بحقــه‬\n     ‫التقريــر الطبــي مــن املستشــفى واملتضمــن إصابتــه يف اجلانــب األيســر‬\n     ‫مــن البطــن واجلانــب الســفلي مــن الصــدر ومــدة الشــفاء ثالثــة أيــام وقــد‬\n     ‫أســفر التحقيــق عــن توجيــه االتهــام إليــه بطعن املدعــو ‪ ....‬يف صدره اجلهة‬\n     ‫اليســرى بآلــة حــادة أثنــاء ســيره علــى اخلــط الدائــري قــرب قريــة‪.......‬‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪1‬ـ إقــراره حتقيقــا املنــوه عنــه املــدون ص‬\n     ‫‪ 6‬مــن ملــف التحقيــق املرفــق لفــة رقــم ‪2 .1‬ـ مــا جــاء بشــهادة الشــهود‬\n     ‫املنــوه عنهــا ص ‪ 6‬مــن ملــف التحقيــق لفــة رقــم ‪3 .1‬ـ التقريــر الطبــي‬\n     ‫الصــادر مــن مستشــفى ‪ .................‬املرفــق لفــة رقــم ‪4 .12‬ـ محضــر‬\n     ‫االنتقــال واملعاينــة املنــوه عنــه املــدون ص ‪ 8‬مــن دفتــر التحقيــق املرفــق‬\n     ‫لفــة رقــم ‪ .1‬و بالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســابقة حتــى تاريخه‬\n     ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه‬\n     ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n     ‫وتــردع غيــره علمــا بــأن احلقــوق اخلاصــة مازالــت قائمــة واهلل املوفــق‬\n     ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بعــد التأكــد مــن‬\n     ‫هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا ذكــره املدعــي العــام مــن‬\n     ‫قيامــي بطعــن املدعــو ‪ ....‬يف صــدره اجلهــة اليســرى بآلــة حــادة فصحيــح‬\n     ‫فقــد حضــر أثنــاء جلوســي بالطــرق الدائــري ثالثــة شــباب ال أعرفهــم‬\n\n\n‫‪49‬‬\n\f‫كونهــم كانــوا ملثمــن وقــام أحدهــم بإمســاكي مــن جهــة اليمــن‬\n‫واآلخــر بإمســاكي مــن جهــة اليســار واألخيــر مــن اخللــف بعدهــا قمــت‬\n‫بإخــراج ســكني كانــت معــي وطعنــت الشــخص املمســك بــي مــن اجلهــة‬\n‫اليمنــى ولــم أعــرف الشــخص املطعــون إال يف املستشــفى هكــذا أجــاب‬\n‫عقــب ذلــك ســألت املدعــى عليــه هــل لديــك بينــه علــى أن الشــباب الثالثــة‬\n‫قامــوا بالتهجــم عليــك واإلمســاك بــك أجــاب قائــا ال بينــة لــي كونــه‬\n‫لــم يكــن أحــد ســوانا وكان املــكان مظلــم هكــذا أجــاب عقــب ذلــك‬\n‫جــرى االطــاع علــى التقريــر الطبــي الصــادر مــن مستشــفى ‪.................‬‬\n‫بجــازان رقــم ‪ 23623‬وتاريــخ ‪1433/11/9‬ه ـ واملتضمــن تدمــي صــدر‬\n‫األيســر مــع ريــح صدريــة يســرى مــع أنبــوب صــدر أيســر ومــدة العــاج يف‬\n‫املستشــفى أســبوعني ومــدة الشــفاء حوالــي شــهر كمــا جــرى االطــاع‬\n‫علــى كــرت ســوابق املدعــى عليــه املرفــق لفــة رقــم ‪ 6‬فوجدتــه خاليــا‬\n‫مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n         ‫املرفقــة لفــة رقــم ‪ 8‬فوجــدت أنــه أوقــف بتاريــخ ‪1433/10/21‬ه ـ‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم‬\n‫املدعــى عليــه بطعــن املدعــو ‪ ....‬يف صــدره اجلهــة اليســرى بآلــة حــادة ومبــا‬\n‫أن املدعــى عليــه صــادق علــى دعــوى املدعــي العــام وادعــى أن مجموعــة‬\n‫مــن الشــباب وكان مــن بينهــم املجنــي عليــه قامــوا باالعتــداء عليــه ومبــا‬\n‫أنــه طلــب مــن املدعــى عليــه البينــة وال بينــة لــه علــى ذلــك ولعمــوم قولــه‬\n‫تعالــى (وال تعتــدوا إن اهلل ال يحــب املعتديــن)‪ .‬وقــول النبــي صلــى اهلل‬\n‫عليــه وســلم املســلم مــن ســلم( املســلمون مــن لســانه ويــده )وقــال النبــي‬\n‫صلــى اهلل عليــه وســلم (مــن أشــار إلــى أخيــه بحديــده فــإن املالئكــة‬\n‫تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه) لذلــك كلــه وألجــل احلــق‬\n\n\n                                                                                        ‫‪50‬‬\n\f     ‫العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه ‪ ....‬بطعــن‬\n     ‫املدعــو ‪ ...‬يف صــدره اجلهــة اليســرى بآلــة حــادة ثانيــا يعــزر املدعــى عليــه‬\n     ‫بالســجن مــدة أربعــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‬\n     ‫ثالثــا يجلــد املدعــى عليــه مائتــان وخمســون جلــدة مفرقــة علــى خمــس‬\n     ‫دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل‬\n     ‫عــن عشــرة أيــام وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة بــه‬\n     ‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة‬\n     ‫عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n     ‫احلكــم وحتــى ال يخفــى جــرى تدوينــه وأقفلــت اجللســة يف متــام الســاعة‬\n     ‫الثانيــة عشــر وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                              ‫وصحبــه وســلم حــرر يف ‪1434/1/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بأبي عريــش املكلف برقم‬\n     ‫‪ 34558265‬وتاريــخ ‪1434 / 4/1‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيل ــة القاضــي باحملكمــة الشــيخ‪ ... /‬برقــم ‪ 3425051‬وتاريــخ ‪1/27‬‬\n     ‫‪1434/‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ - .... /‬مينــي اجلنســية ‪-‬‬\n     ‫يف قضيــة ( طعــن ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه تقــررت املوافقــة علــى احلكــم واهلل‬\n                     ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":45,"source_page_end":51,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"88b84c6a6e15a83a03d2e3222ecfe46aff67283f6edfb1a8cfb41607d5145ba6","normalized_text_hash":"c9d7a714b4ae5ed9a4c91e532a0825bcf558e769f7f76809022fc8c46f64acdb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p45-3425051"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS legal_documents,
       (SELECT count(*) FROM public.document_files WHERE document_id IN (
          SELECT (x->>'id')::uuid FROM jsonb_array_elements($archive_payload$[{"id":"72b35c0d-1e27-5125-9228-7b4e529b20f2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب باستخدام عصا خشبية -ضرب أفضى إلى املوت -قتل شبه عمد -دعوى عامة وخاصة -االستئناس برأي أهل اخلبرة يف ثبوت الدعوى من عدمها «تقرير طبي شرعي» -يشترط لثبوت اجلناية ثبوت قيام العالقة السببية بن الفعل واجلناية-رد دعوى املدعى العام .","document_number":"34250164","case_number":"3018918","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة ب","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/7/30","year":"1434","subject":"اعتداء -ضرب -ضرب باستخدام عصا خشبية -ضرب أفضى إلى املوت -قتل شبه عمد -دعوى عامة وخاصة -االستئناس برأي أهل اخلبرة يف ثبوت الدعوى من عدمها «تقرير طبي شرعي» -يشترط لثبوت اجلناية ثبوت قيام العالقة السببية بن الفعل واجلناية-رد دعوى املدعى العام .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"                 ‫رقم الصك ‪ 34250164 :‬تاريخه‪:‬‬\n       ‫رقم الدعوى‪3018918:‬‬      ‫‪1434/06/24‬هـ‬\n        ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34283702‬تاريخه‪1434/7/30 :‬هـ‬\n\n\n    ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب باســتخدام عصــا خشــبية ‪ -‬ضــرب أفضــى إلــى‬\n    ‫املــوت ‪ -‬قتــل شــبه عمــد‪ -‬دعــوى عامــة وخاصــة ‪ -‬االســتئناس بــرأي أهــل‬\n    ‫اخلبــرة يف ثبــوت الدعــوى مــن عدمهــا «تقريــر طبــي شــرعي» ‪-‬يشــترط‬\n    ‫لثبــوت اجلنايــة ثبــوت قيــام العالقــة الســببية بــن الفعــل واجلنايــة‪-‬رد‬\n                                                          ‫دعــوى املدعــى العــام ‪.‬‬\n\n\n\n\n                                        ‫ما أشار له القاضي يف تسبيب احلكم‪.‬‬\n\n\n\n\n    ‫أقــام املدعــي اخلــاص دعــوى ضــد املدعــى عليــه بحصــول مضاربــة بينــه‬\n    ‫وبــن مورثــه ‪ -‬ابنــه ‪-‬وأنــه قــام بضربــه بعصــا علــى رأســه أدت لوفاتــه‬\n    ‫ويطلــب احلكــم عليــه بدفــع نصيبــه مــن دية شــبه العمد املقــدرة بأربعمئة‬\n    ‫ألــف ريــال عليــه فيكــون نصيبــه منهــا مئتــن وســتني ألفــا وســتمئة وســتة‬\n    ‫وســتني ريــاال وســتة وســتني هللــة ‪،‬أقــر املدعــى عليــه بحصــول املضاربــة‬\n    ‫وأنــه تنــاول العصــا وأهــوى بهــا علــى مورثــه إال أن مورثــه متكــن مــن‬\n    ‫صدهــا بيــده ولــم تصبــه بــأذى ‪ ،‬ورد بتقريــر الطبيــب الشــرعي عــدم‬\n    ‫تعــرض املتوفــى ألي ضــرب يف أي موضــع مــن جســده وأنــه ظهــر مــن‬\n    ‫تشــريح اجلثــة وجــود حالــة مرضيــة مزمنــة متقدمــة بالقلــب وشــرايينه‬\n\n‫‪5‬‬\n\f‫أدت لتضخــم القلــب مصحــوب بتصلــب عصيــدي شــديد مــع انســداد يف‬\n‫محيــط الشــريان التاجــي لــذا فــإن وفاتــه تعــزى حلالتــه املرضيــة التــي أدت‬\n‫لتوقــف القلــب والتنفــس نتيجــة نقــص شــديد يف ترويــة عضلــة القلــب ‪،‬‬\n‫كمــا جــرى إفهــام املدعــي بــأن لــه ميــن املدعــى عليــه علــى نفــي دعــواه‬\n‫فطلــب ميينــه‪ ،‬فحلــف املدعــى عليــه اليمــن املطلوبــة‪ ،‬لــذا فقــد قــررت‬\n‫احملكمــة صــرف النظــر عــن دعــوى املدعــي وأخلــت ســبيل املدعــى عليــه‬\n‫‪،‬وبعــرض احلكــم علــى املدعــي قــرر القناعــة ‪،‬وأقــام املدعــي العــام علــى‬\n‫املدعــى عليــه دعــوى بأنــه جــرى توجيــه االتهــام لــه بقيامــه بقتــل الغيــر‬\n‫شــبه عمــد بضربــه بعصــا خشــبية وطلــب إثبــات مــا أســند إليــه وتطبيــق‬\n‫مقتضــى اإلرادة امللكيــة ‪،‬أنكــر املدعــى عليــه تســببه يف قتــل املتوفــى‬\n‫‪،‬وإلنــكار املدعــى عليــه ولعــدم قيــام البينــة املوصلــة علــى الدعــوى‬\n‫وملــا تضمنــه التقريــر الطبــي مــن اإلشــارة بــأن ســبب الوفــاة يعــود حلالتــه‬\n‫املرضيــة ‪ -‬لــذا فقــد انتهــت احملكمــة إلــى عــدم ثبــوت تســبب املدعــى‬\n‫عليــه بالوفــاة ال عمــد ًا وال شــبهة وال خطــأ وقــررت صــرف النظــر عــن‬\n‫دعــوى املدعــي العــام وأخلــت ســبيله مــن الدعــوى ‪،‬بعــرض احلكــم علــى‬\n‫املدعــي العــام قــرر عــدم القناعــة وطلــب تدقيقــه بــدون الئحــة ‪،‬صــدق‬\n                                            ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف احملكمــة اجلزائيــة‬\n‫بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1430/02/27‬ه ـ املقيــدة باحملكمــة‬\n‫برقم وتاريخ ‪ 1430/02/27‬هـ ففي يوم الثالثاء املوافق‪1434/06/06‬‬\n\n                                                                                       ‫‪6‬‬\n\f    ‫ه ـ افتتحــت اجللســة الســاعة ‪10 : 45‬وفيهــا حضــر ‪...........‬أردنــي اجلنســية‬\n    ‫مبوجــب رخصــة إقامــة رقــم ‪...........‬وادعــى علــى احلاضــر معــه ‪...........‬‬\n    ‫بنجالديشــي اجلنســية مبوجــب رخصــة إقامــة رقــم ‪...........‬قائــا يف‬\n    ‫دعــواه أن هــذا احلاضــر ‪...........‬حصلــت بينــه وبــن ابنــي ‪...........‬مضاربــة‬\n    ‫يف ‪1429/9/22‬ه ـ فقــام بضــرب ابنــي بعصــا وتــويف ابنــي نتيجــة لذلــك‬\n    ‫وقــد انحصــر ارث ابنــي يف أنــا والــده ويف والدتــه ‪ ...........‬مبوجــب صــك‬\n    ‫اإلرث الصــادر مــن احملكمــة العامــة برقــم‪...........‬يف ‪1433/1/30‬هـ ـ‬\n    ‫فقــط وجنايــة علــى ابنــي مــن قبيــل شــبه العمــد اطلــب منكــم احلكــم‬\n    ‫عليــه بتســليمي نصيبــي مــن ديــة قتــل شــبه العمــد حيــث أن ديــة شــبه‬\n    ‫العمــد أربعمائــة ألــف ريــال ونصيبــي منهــا مئتــن وســتني الفــا وســتمائة‬\n    ‫وســتة وســتني رياال وســته وســتني هلله(‪)266666,6‬هذه دعواي وبعرض‬\n    ‫دعــوى املدعــي ‪...........‬علــى املدعــى عليــه ‪...........‬اجــاب بلســان عربــي‬\n    ‫قائــا إنــه حصلــت بينــي وبــن ابــن املدعــي ‪...........‬مضاربــة فأخــذت‬\n    ‫عصــا ملــا ضربنــي أردت ضربــه بهــا ورفعتهــا وأهويــت بهــا عليــه فقــام‬\n    ‫مبســكها منــي أثنــاء رفعهــا ولــم أصبــه بــأي ضــرب وقــد جــاء آخــر‬\n    ‫ســعودي فضربنــي ولــم يحصــل منــي أي ضــرب ألحــد هكــذا أجــاب‬\n    ‫وبعــرض جوابــه علــى املدعــي قــال إن املدعــى عليــه ضــرب ابنــي وعنــدي‬\n    ‫بينــه وبينتــي احلاضــر املضاربــة ‪...........‬اطلــب رفــع اجللســة إلحضــاره‬\n    ‫ورفعــت اجللســة لذلــك وحــددت لهمــا موعــد ًا هــو يــوم األربعــاء املوافــق‬\n    ‫‪1434/6/14‬هـ ـ الســاعة الثامنــة والنصــف وعلــى مــا ذكــر حصــل‬\n    ‫التوقيــع‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                     ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/06‬ه ـ‬\n    ‫احلمــد هلل وحــده وبعــد ففــي يــوم األربعــاء املوافــق‪ 1434/06/14‬ه ـ‬\n\n\n‫‪7‬‬\n\f‫افتتحــت اجللسةالســاعة‪9‬وفيها حضــر املدعــي ‪...........‬واملدعــى عليــه‬\n‫‪...........‬وقــد احضــر املدعــي معــه ‪...........‬ســعودي اجلنســية مبوجــب‬\n‫الســجل املدنــي رقــم ‪...........‬وبســؤال احلاضــر ‪...........‬عمــا لديــه مــن‬\n‫شــهادة كنــت أنــا وصديقــي ‪...........‬رحمــة اهلل عليــه راجعــن إلــى منــزل‬\n‫‪...........‬وكنــا نــود الســحور ووقفنــا أمــام منــزل ‪...........‬ولــم جنــد موقفـ ًا‬\n‫للســيارة ووقفنــا خلــف الســيارات ونزلنــا ومعنــا الســحور وجدنــا البنقالي‬\n‫املدعــى عليــه هــذا احلاضــر أمــام مطعمــه فتوجهنــا إليه ووجه إليه ســؤال‬\n‫وقــال ملــاذا كثــرت الســيارات أمــام منزلــي وقــام البنقالــي يتلفــظ مــا لــك‬\n‫دخــل وكشــر بوجهــه ‪...........‬وقامــوا مبدافعــة بعضهــم بعضــا وجتمــع‬\n‫النــاس لتفريقهــم وأنــا بجانــب ‪...........‬ورجــع البنقالــي للمحــل ورأيــت معــه‬\n‫عصــا وكان ممســك ًا بيديــه الثنتــن ويريــد ضــرب ‪...........‬وخفــت ان‬\n‫يضربنــي ووجهــت وجهــي للخلــف فســمعت ضربــة العصــا ولــم أشــاهد‬\n‫أيــن ضــرب فقــام ‪...........‬بغضــب شــديد فضــرب البنقالــي وقمنــا بدخــول‬\n‫احملــل وهنــاك كنــت امســك البنقالــي هــذا احلاضــر وهو كان ماســك ًا‬\n‫بــي وكان دم البنقالــي هــذا احلاضــر ينثــر علــي ولكــي أفلــت البنقالــي‬\n‫هــذا احلاضــر قمــت وضربتــه لكــي يتركنــي وقمنــا بالتفرقــة بينهمــا‬\n‫هــذا مــا لــدي مــن شــهادة وبــه اشــهد وبســؤال املدعــي ‪...........‬هــل لديــه‬\n‫أي بينــة أو شــاهد آخــر قــال ال يوجــد لــدي أي بينــات أو شــهود ســوى‬\n‫مــن أحضــرت ‪...........‬هــذا وقــد جــرى اطالعــي علــى التقريــر الطبــي‬\n‫الشــرعي النهائــي يف هــذه القضيــة رقــم ‪...........‬الصــادر مــن املديريــة‬\n‫العامــة للشــئون الصحيــة مبنطقــة الريــاض إدارة الطــب الشــرعي‬\n‫بالريــاض حيــث ذكــر فيــه عــدم تعــرض املتوفــى ب‪ ...........‬ألي ضــرب‬\n‫يف أي موضــع مــن جســده وهــذا خالصــة مــا جــاء يف تقريرهــم حيــث‬\n\n\n                                                                                          ‫‪8‬‬\n\f    ‫ذكــر يف الصفحــة األخيــرة منــه ( ثبــت مــن فحــص وتشــريح اجلثــة ومــن‬\n    ‫فحــص التشــريح النســجي وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب‬\n    ‫وشــرايينه عبــارة عــن تضخــم بعضلــة القلــب (البطــن االيســر) مصحــوب‬\n    ‫بتصلــب عصيــدي شــديد مــع انســداد يف محيــط الشــريان التاجــي‬\n    ‫االيســر نســبة ‪ %90‬وحكمـ ًا علــى مــا ســبق وعلــى مــا اوردنــا مــن حقائــق‬\n    ‫علميــة فإننــا نــرى ان وفــاة املذكــور مرضيــة تعــزى الــى حالتــه املرضيــة‬\n    ‫املوصوفــه بالقلــب آنفـ ًا مبــا أدت اليــه مــن توقــف للقلــب والتنفــس نتيجــة‬\n    ‫نقــص شــديد يف ترويــة عضلــة القلــب وال يوجــد مــا مينــع مــن حــدوث وفــاة‬\n    ‫املذكــور يف تاريــخ ‪1429/9/22‬هـ ـ كمــا هــو مثبــت بخطــاب الشــرطة‬\n    ‫اخصائــي الطــب الشــرعي بالريــاض و‪...........‬توقيــع اخصائــي الطــب‬\n    ‫الشــرعي بالريــاض ‪............‬توقيــع جلميــع مــا تقــدم مــن الدعــوى واالجابــة‬\n    ‫وحيــث أنكــر املدعــى ‪ ......................‬ضربــه مــورث املدعــي ‪...........‬أو‬\n    ‫تســببه يف وفاتــه وحيــث لــم يقــم املدعــي البينــه علــى مــا أدعــاه وحيــث أن‬\n    ‫شــهادة الشــاهد الــذي أحضــره املدعــي هــو ‪ ...........‬لــم يشــهد علــى ضرب‬\n    ‫املدعــى عليــه وحيــث اثبــت التقريــر الطبــي الشــرعي املذكــور خالصتــه‬\n    ‫ان ســبب الوفــاة هــو وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب أدت‬\n    ‫الــى وفاتــه وانــه لــم يتعــرض ألي آثــار ضــرب يف جســده فقــد أفهمــت‬\n    ‫املدعــي ان لــه ميــن املدعــى عليــه أنــه لــم يضــرب ابنــه وانــه لــم يتســبب‬\n    ‫يف وفاتــه بضربــه قــال أريــد ميــن املدعــى عليــه ‪...........‬وبعرضــه علــى‬\n    ‫املدعــى عليــه ‪...........‬قــال ال مــا نــع لــدي مــن احللــف ثــم تلفــظ قائــا واهلل‬\n    ‫العظيــم الــذي ال الــه اال هــو عالــم الغيــب والشــهادة اننــي لــم اضــرب ابــن‬\n    ‫املدعــي ‪...........‬جلميــع مــا تقــدم فقــد حكمــت بصــرف النظــر عــن دعــوى‬\n    ‫املدعــي ‪...........‬ضــد املدعــى عليــه ‪...........‬واخليــت ســبيل املدعــى عليــه‬\n\n\n‫‪9‬‬\n\f‫‪...........‬وبعــرض احلكــم علــى الطرفــن قــررا القناعــة بــه‪ .‬وبــاهلل التوفيــق‬\n‫‪ ،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف‬\n‫‪ 1434/06/14‬ه ـ احلمــد هلل وحــده وبعــد فلــدي أنــا ‪...........‬القاضــي يف‬\n‫احملكمــة اجلزائيــة بالريــاض وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n‫رئيــس احملكمــة اجلزائيــة بالريــاض برقــم وتاريــخ ‪ 1430/02/27‬ه ـ‬\n‫املقيــدة باحملكمــة برقــم وتاريــخ ‪ 1430/02/27‬ه ـ ففــي يــوم األحــد‬\n‫املوافــق‪ 1434/06/18‬ه ـ افتتحــت اجللســة الســاعة وفيهــا حضــر املدعــي‬\n‫‪...........‬قائــا يف دعــواه بصفتــي مدعي ـ ًا عام ـ ًا يف دائــرة االدعــاء العــام‬\n                                                    ‫مبدينــة الريــاض أدعــي علــى‪/‬‬\n‫‪ 37........... -1‬عامــا ‪ ،‬بنجالديشــي اجلنســية مبوجــب رخصــة االقامــة‬\n‫رقــم () مقيــم مبدينــة الريــاض اوقــف بتاريخ ‪1429/9/22‬ه ـ ومت ايداعه‬\n‫الســجن العــام مبوجــب مذكــرة االحالــة ومتديــد التوقيــف رقــم‪...........‬‬\n                                                          ‫وتاريــخ ‪1429/11/12‬هـ‬\n‫‪ 22........... -2‬عامــا ‪ ،‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‬\n‫(‪ )...........‬متعلم ‪ ،‬مقيم مبدينة الرياض ‪ ،‬اوقف بتاريخ ‪1429/9/22‬هـ‬\n‫وافــرج عنــه مبوجــب امــر اإلفــراج ‪...........‬وتاريــخ ‪1429/9/24‬ه ـ حيــث‬\n‫انــه بتاريــخ ‪1429/6/5‬ه ـ ورد ملركــز شــرطة ‪...........‬تقريــر احــدى فــرق‬\n‫الدوريــات االمنيــة برقــم ‪...........‬املتضمــن وجــود مضاربــة علــى شــارع‬\n‫‪...........‬امــام مطعــم ‪...........‬وانتقلــت الفرقــه للموقــع وقابلــت املتهــم االول‬\n‫وتبــن ان بــه اصابــه ويفيــد بــان شــخصني قامــا بضربــه امــام املطعــم‬\n‫ودخــا املنــزل احدهمــا املتهــم الثانــي واالخــر يدعــى ‪...........‬واثنــاء ذلــك‬\n‫حضــرا وافــادا بــان الطــرف االول تلفــظ عليهمــا ويقــوم بايقــاف ســيارته‬\n‫امــام املنــزل ومت نقــل جميــع االطــراف الــى مســتوصف ‪...........‬الســعافهم‬\n\n\n                                                                                          ‫‪10‬‬\n\f     ‫ومت عــاج املتهــم االول فقــط لعــدم وجــود اصابــات باخصامــه كمــا‬\n     ‫افــادا بذلــك واثنــاء اخلــروج مــن املســتوصف تعــرض ‪...........‬حلالــة اغمــاء‬\n     ‫ومت عرضــه علــى الطبيــب فطلــب نقلــه الــى مستشــفى احلــرس الوطنــي‬\n     ‫ومت نقلــه عــن طريــق اســعاف املســتوصف وتــويف قبــل وصولــه املستشــفى‬\n     ‫وباالنتقــال الــى موقــع اجلرميــة يف حــي ‪ .....‬شــارع ‪...........‬عقــار رقــم ‪...........‬‬\n     ‫وعنــد معاينــة املوقــع عثــر علــى عصــا خشــبية ( عصــا مكنســة ) ولــم يتــم‬\n     ‫العثــور علــى اشــياء اخــرى او اثــار دمــاء ‪ .‬وباســتجواب املتهــم االول ‪ /‬افــاد‬\n     ‫بانــه يف حوالــي الســاعة الثالثــة والثلــث صباحــا مــن يــوم ‪1429/9/22‬ه ـ‬\n     ‫حضــر البوفيــة وتنــاول وجبــة الســحور وعنــد خروجــه مــن البوفيــة‬\n     ‫قابله‪...........‬وســاله عــن صاحــب الســيارة الليموزيــن الواقفــه امــام منزلــه‬\n     ‫فقــال انــه نائــم يف منزلــه فضربــه ‪...........‬بيــده علــى وجهــه وضربــه‬\n     ‫بحديــده وذراعــه وفخــذه االميــن وقــام زميلــه املتهــم الثانــي ‪...........‬بضربــه‬\n     ‫علــى وجهــه ومبواجهتــه باملتهــم الثانــي تراجــع عــن اقوالــه وافــاد بانــه قــام‬\n     ‫بضــرب املتــويف بعصــا خشــبية مــرة واحــدة وال يعلــم هــل كانــت الضربــة‬\n     ‫علــى صــدره ام كتفــه وباســتجواب املتهــم الثانــي افــاد بانــه كان مــع‬\n     ‫املتــويف وعنــد وصولهمــا الــى املنــزل لــم يعثــر علــى موقــف للســيارة فنــزل‬\n     ‫املتــويف يتحــدث مــع املتهــم االول فســأله عــن صاحــب الســيارة الواقفــة‬\n     ‫أمــام منزلهــم فقــال لــه املتهــم األول إنــه زبــون وأنــه نائــم فتماســكا‬\n     ‫باأليــدي فدخــل املتهــم األول البوفيــة وأحضــر عصــا ورفعهــا علــى املتــويف‬\n     ‫وال يعلــم إن كان ضربــه بهــا أم ال كمــا أفــاد بــأن املتهــم األول قــام‬\n     ‫مبســكه وحــاول التخلــص منــه دون جــدوى فقــام لضــرب املتهــم األول‬\n     ‫علــى وجهــه ثــم دخــل هــو واملتــويف املنــزل وبعــد ذلــك قبــض عليهمــا وال‬\n     ‫يوجــد بــه أي اصابــات وقــد صــدر التقريــر الشــرعي رقم‪...........‬املتضمــن‬\n\n\n‫‪11‬‬\n\f‫ان املجنــي عليــه يعانــي مــن حالــة مرضيــة متقدمــة بالقلــب وشــرايينه‬\n‫عبــارة عــن تضخــم بعضلــة القلــب البطــن األيســر مصحــوب بتصلــب‬\n‫عصيــدي شــديد مــع انســداد يف محيــط الشــريان التاجــي األيســر بنســبة‬\n‫‪ %90‬وحكمــا علــى مــا ســبق فــان املذكــور تعــزى وفاتــه إلــى حالتــه‬\n‫املرضيــة املوصوفــة بالقلــب ومبــا أدت إليــه مــن توقــف القلــب والتنفــس‬\n‫نتيجــة نقــص شــديد يف ترويــة عضلــة القلــب كمــا ورد التقريــر الطبــي‬\n‫مــن مدينــة امللــك عبدالعزيــز الطبيــة رقــم ‪...........‬وتاريــخ ‪1429/9/22‬ه ـ‬\n             ‫بحــق املتــويف ‪...........‬املتضمــن وجــود ســحجات علــى الصــدر‪.‬‬\n‫وقــد أســفر التحقيــق عــن اتهــام األول ‪...........‬بقتــل ‪...........‬شــبه عمــد‬\n‫وذلــك بعــد ضربــه بعصــا خشــبية علــى صــدره ضربــة واحــده واتهــام‬\n‫الثانــي ‪...........‬بضــرب االول علــى وجهــه بيــده وفقــا لقــرار االتهــام رقــم (‬\n                       ‫‪ ...........‬لعــام ‪1429‬ه ــوذلك لألدلــة والقرائــن التاليــة‬\n‫‪-1‬إقــرار األول بالتضــارب مــع املتوفــى واملتهــم الثانــي املــدون علــى‬\n      ‫الصفحــة رقــم (‪ )12‬مــن ملــف التحقيــق املرفــق لفــة رقــم (‪)24‬‬\n‫‪ -2‬مــا جــاء يف اقــوال املتهــم الثانــي املدونــة علــى الصفحــة رقــم (‪ )5‬مــن‬\n                                                ‫ملــف التحقيــق املرفــق لفــة (‪.)24‬‬\n‫‪-3‬محضــر املواجهــة املــدون علــى الصفحــة رقــم (‪ )8‬مــن ملــف التحقيــق‬\n                                                                  ‫املرفقــة لفــة (‪)24‬‬\n‫‪-4‬التقريــر الطبــي الصــادر مــن مدينــة امللــك عبدالعزيــز الطبية املتضمن‬\n                    ‫وجــود ســحجات علــى صــدر املتوفــى املرفــق لفــة رقم (‪)6‬‬\n‫‪-5‬محضــر االنتقــال واملعاينــة املــدون علــى الصفحــة رقــم (‪ )13-12‬مــن‬\n                                               ‫ملــف االســتدالل املرفــق لفــة (‪.)1‬‬\n                                            ‫‪ -6‬التقرير اجلنائي املصور لفة (‪.)22‬‬\n\n\n                                                                                         ‫‪12‬‬\n\f     ‫‪-7‬محضــر عــرض األداة املســتخدمة باجلرميــة املــدون علــى الصفحــة رقــم‬\n                                         ‫(‪ )2‬مــن ملــف التحقيــق املرفــق لفــة (‪.)24‬‬\n                                            ‫‪ -8‬تقرير الدوريات املنية لفة رقم (‪.)4‬‬\n     ‫وبالبحــث عــن ســوابقهما لــم تــرد حتــى تاريخــه‪ .‬وحيــث أن مــا أقــدم‬\n     ‫عليــه األول وهــو بكامــل أهليتــه يعــد فعــا محرمــا لــذا أطلــب إثبــات‬\n     ‫صفــة القتــل شــبه العمــد وفقــا لنــص املــادة ‪ 126‬مــن نظــام اإلجــراءات‬\n     ‫اجلزائيــة وطلــب احلكــم عليــه مبقتضــى اإلرادة امللكيــة للقتــل شــبه‬\n     ‫العمــد رقــم ‪ 2104/4/8‬وتاريــخ ‪1363/10/16‬ه ــوتعزير الثانــي لقــاء‬\n     ‫مــا أســند إليــه علمــا بــأن احلــق اخلــاص مــازال قائم ـ ًا بالنســبة للديــة‬\n     ‫‪.‬وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه األول ‪...........‬أجــاب‬\n     ‫بلســان عربــي قائــا ان املتوفــى ‪...........‬أردنــي اجلنســية حصــل بينــي‬\n     ‫وبينــه مشــادة كالميــة بســبب إيقــاف ســيارة أمــام املطعــم فقــام بضربــي‬\n     ‫كف ـ ًا علــى وجهــي وقمــت وأخــذت عصــا ملــا ضربنــي ورفعتهــا واهويــت‬\n     ‫بهــا عليــه فقــام مبســكها منــي أثنــاء رفعهــا ولــم أصبــه بــأي ضــرب‬\n     ‫وال غيــره وقــد جــاء ‪...........‬ســعودي اجلنســية فضربنــي ولــم أضــرب أي‬\n     ‫منهمــا بــل أنــا املضــروب هكــذا أجــاب وال صحــة ملاذكــر يف الدعــوى‬\n     ‫مــن اننــي أفــدت بضــرب املتوفــى بعصــا خشــبية مــرة واحــدة هــذا غيــر‬\n     ‫صحيــح هكــذا أجــاب وقــال املدعــي العــام ليــس لــدي بينــة علــى ضــرب‬\n     ‫املدعــى عليــه للمتوفــى ســوى إفــادة املدعــى عليــه وقــد جــرى رجوعــي‬\n     ‫ألقــوال املدعــى عليــه ‪...........‬و‪...........‬فيدفتــر التحقيــق املرفــق ص(‪-1‬‬\n     ‫‪)8‬فوجــدت املدعــى عليــه أنكــر ضربــه للمتوفــى ‪...........‬ووجــدت‬\n     ‫أقــوال ‪...........‬أنــه شــاهد املدعــى عليه‪...........‬رفــع العصــا وال يــدري هــل‬\n     ‫ضــرب ‪...........‬أم ال كمــا جــرى اطالعــي علــى محضــر املواجهــة بــن‬\n\n\n‫‪13‬‬\n\f‫‪...........‬و‪ ...........‬وجــدت افــادة ‪ ....‬أنــه قــام باحضــار العصــا مــن داخــل‬\n‫احملــل وقــام بضــرب ‪...........‬مــرة واحــدة وال يــدري هــل كانــت يف صــدره‬\n‫أم كتفــة وبعرضــه عليــه قــال ال صحــة لذلــك كمــا جــرى اطالعــي‬\n‫علــى التقريــر الطبــي الشــرعي النهائــي يف هــذه القضيــة رقــم ‪...........‬‬\n‫الصــادر مــن املديريــة العامــة للشــئون الصحيــة مبنطقــة الريــاض إدارة‬\n‫الطــب الشــرعي بالريــاض حيــث ذكــر فيــه عــدم تعــرض املتوفــى‬\n‫ب‪...........‬ألي ضــرب يف أي موضــع مــن جســده وعــدم وجــود ســحجات‬\n‫وهــذا خالصــة مــا جــاء يف تقريرهــم حيــث ذكــر يف الصفحــة األخيــرة‬\n‫منــه ( ثبــت مــن فحــص وتشــريح اجلثــة ومــن فحــص التشــريح النســجي‬\n‫وجــود حالــة مرضيــة مزمنــه متقدمــة بالقلــب وشــرايينه عبــارة عــن‬\n‫تضخــم بعضلــة القلــب (البطــن االيســر) مصحــوب بتصلــد عصيــدي‬\n‫شــديد مــع انســداد يف محيــط الشــريان التاجــي االيســر نســبة ‪%90‬‬\n‫وحكمـ ًا علــى مــا ســبق وعلــى مــا أوردنــا مــن حقائــق علميــة فإننــا نــرى‬\n‫أن وفــاة املذكــور مرضيــة تعــزى الــى حالتــه املرضيــة املوصوفــه بالقلــب‬\n‫آنف ـ ًا مبــا أدت اليــه مــن توقــف للقلــب والتنفــس نتيجــة نقــص شــديد يف‬\n‫ترويــة عضلــة القلــب وال يوجــد مــا مينــع مــن حــدوث وفــاة املذكــور يف‬\n‫تاريــخ ‪1429/9/22‬هـ ــكما هــو مثبــت بخطــاب الشــرطة أخصائــي‬\n‫الطــب الشــرعي بالريــاض ‪...........‬توقيــع أخصائــي الطــب الشــرعي‬\n‫بالريــاض د‪............‬توقيــع جلميــع مــا تقــدم مــن الدعــوى واالجابــة وحيــث‬\n‫أنكــر املدعــى عليــه ‪...........‬ضربــه مــورث املدعــي‪...........‬أو تســببه يف‬\n‫وفاتــه وحيــث لــم يقــم املدعــي البينــة علــى مــا أدعــاه وحيــث جــاء يف‬\n‫التقريــر الطبــي الشــرعي النهائــي أن ســبب وفــاة ‪...........‬حالتــه املرضيــة‬\n‫بالقلــب جلميــع مــا تقــدم لــم يظهــر لــم يثبــت لــدي تســبب املدعــى عليــه يف‬\n\n\n                                                                                       ‫‪14‬‬\n\f     ‫وفــاة ‪...........‬ال عمــد وال شــبه وال خطــأ وحكمــت بصــرف النظــر عــن‬\n     ‫دعــوى املدعــي العــام ضــد املدعــى عليــه ‪...........‬وأخليــت ســبيله وبعــرض‬\n     ‫احلكــم علــى الطرفــن قنــع املدعــى عليــه ‪...........‬ولــم يقنــع املدعــي العــام‬\n     ‫وطلــب تدقيقــه مــن قبــل محكمــة االســتئناف بــدون الئحــة فأجيــب‬\n     ‫لطلبــه ويف حــال إحضــار املدعــى عليــه الثاني‪...........‬ســوف يتــم نظــر‬\n     ‫الدعــوى ضــده لــدي مبشــيئة اهلل‪ .‬وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى‬\n     ‫نبينــا محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/06/18‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة اجلزائيــة‬\n     ‫الثالثــة لتمييــز القضايــا اجلزائيــة مبحكمــة االســتئناف بالريــاض علــى‬\n     ‫خطــاب فضيلــة رئيــس احملكمــة اجلزائيــة بالريــاض برقــم ‪331950074‬‬\n     ‫وتاريــخ ‪1434/7/9‬ه ــاملرفق بهــا القــرار الصــادر مــن فضيلــة القاضــي‬\n     ‫باحملكمــة الشــيخ ‪........... /‬برقموتاريخ‪1434/6/24‬ه ـ اخلــاص بدعوى‬\n     ‫املدعــي العــام واخلــاص ‪...........‬أردني اجلنســية ضد‪ ........... /‬بنجالديشــي‬\n     ‫اجلنســية يف قضيــة قتــل علــى النحــو املوضــح يف بالقــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل بــه وبدراســة القــرار وصــورة ضبطــه‬\n     ‫وأوراق املعاملــة لــم يظهــر مــا يوجــب املالحظــة علــى احلكــم فيمــا يتعلــق‬\n     ‫باحلــق العــام وأمــا مــا يتعلــق باحلــق اخلــاص فقــد انتهــى احلكــم بقناعــة‬\n     ‫الطرفــن فــا يكــون خاضع ـ ًا للتدقيــق واهلل املوفــق وصلــى اهلل علــى‬\n                                                     ‫نبينــا محمــد وآلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n‫‪15‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":5,"source_page_end":15,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"57b732a9852944cc5be15d283a1e0a24a397aebdc4de7c1cdb52998863d498e2","normalized_text_hash":"7cb22a01be803710c1c9c014b8b9ae8752e32a464dfb0aee7ee4205ca4837991","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p5-34250164"},{"id":"a2bda85b-a2e1-5082-9b3e-026a4677ff39","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -إحداث إصابة -املطالبة بالتعزير جراء التعدي -املطالبة بأرش اإلصابة -تقدير أرش إصابة الرأس -التعزير","document_number":"3449421","case_number":"346565","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/02/27","year":"1434","subject":"اعتداء -ضرب -إحداث إصابة -املطالبة بالتعزير جراء التعدي -املطالبة بأرش اإلصابة -تقدير أرش إصابة الرأس -التعزير","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":" ‫رقم الصك ‪ 3449421:‬تاريخه‪1434/02/27 :‬هـ‬\n                       ‫رقم الدعوى‪346565:‬‬\n     ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n            ‫‪ 34233598‬تاريخه‪1434/06/7:‬هـ‬\n\n\n\n‫اعتــداء ‪ -‬ضــرب ‪-‬إحــداث إصابــة ‪ -‬املطالبــة بالتعزيــر جــراء التعــدي‬\n‫‪ -‬املطالبــة بــأرش اإلصابــة ‪ -‬تقديــر أرش إصابــة الــرأس ‪ -‬التعزيــر‬\n                                                               ‫باجللــد‪.‬‬\n\n\n\n\n                                            ‫‪-1‬قول اهلل تعالى‪(:‬وال تعتدوا )‪.‬‬\n‫‪-2‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬مــن حلــف علــى ميــن هــو فيهــا فاجــر‬\n‫ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل وهــو عليه غضبان)‪.‬رواه مســلم‬\n‫‪-3‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬كل املســلم علــى املســلم حــرام دمــه‬\n                                                             ‫ومالــه وعرضــه )‪.‬‬\n‫‪-4‬قولــه صلــى اهلل عليــه وســلم ‪ (:‬املســلم مــن ســلم املســلمون مــن لســانه‬\n                                                                         ‫ويده)‪.‬‬\n          ‫‪-5‬ماذكره الفقهاء من حتليف أقوى املتداعيني املتجاحدين‪.‬‬\n ‫‪-6‬ماذكره ابن القيم من أن البينة هي كل مايبني احلق ويوضحه‪.‬‬\n\n\n\n\n‫توجيــه االتهــام للمدعــى عليــه برمــي فنجــان والتســبب يف إصابــة املجنــي‬\n‫عليــه بجــرح بالــرأس ويحتــاج عشــرة أيــام للعــاج ‪ ،‬طلــب املدعــى العــام‬\n‫إثبــات مــا أســند للمدعــى عليــه واحلكــم عليــه بعقوبــة تعزيريــة ‪ ،‬حضــر‬\n\n                                                                                   ‫‪16‬‬\n\f     ‫املدعــي اخلــاص وطلــب أرش االصابــة‪ ،‬أقــر املدعــى عليــه بضــرب املدعي‬\n     ‫اخلــاص بفنجــان الشــاي ‪ ،‬وذكــر بــأن اإلصابــة بالصدر وليســت بالرأس‬\n     ‫‪ ،‬أحضــر املدعــي العــام واملدعــي اخلــاص شــاهدين فشــهدا بالضــرب‬\n     ‫ولــم يذكــرا موضعــه ‪ ،‬وذكــر الشــاهدان أنهــم بعــد املضاربــة شــاهدا‬\n     ‫إصابــة يف رأس املدعــي باحلــق اخلــاص ‪ ،‬رجــع القاضــي إلــى التقريــر‬\n     ‫الطبــي املبــن لصفــة اإلصابــة ومــدة الشــفاء وقــد مت تقديــر أرش‬\n     ‫اإلصابــة مــن مقــدري الشــجاج بأربعــة آالف ريــال ‪،‬وملــا ذكــره الفقهــاء‬\n     ‫مــن حتليــف أقــوى املتداعبــن املتجاحديــن جــرى حتليــف املدعــي باحلــق‬\n     ‫اخلــاص علــى صحــة دعــواه مــن أن اإلصابــة التــي برأســه مــن املدعــى‬\n     ‫عليــه ‪ ،‬صــدر احلكــم بجلــد املدعــى عليــه عشــرين جلــدة للحــق العــام ‪،‬‬\n     ‫إلــزام املدعــى عليــه بــأن يدفــع للمدعــي باحلــق اخلــاص أربعــة آالف ريــال‬\n     ‫أرش إصابتــه ‪،‬قــرر املدعــي العــام عــدم املعارضــة واملــدع باحلــق اخلــاص‬\n     ‫القناعــة أمــا املدعــى عليــه فاعتــرض علــى احلكــم ‪ ،‬صــدق احلكــم مــن‬\n                                                            ‫محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ .........‬القاضــي يف احملكمــة‬\n     ‫اجلزئيــة مبحافظــة جــدة وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة‬\n     ‫رئيــس احملكمــة اجلزئيــة يف محافظــة جدة‪/‬املســاعد برقــم وتاريــخ‬\n     ‫‪ 1433/01/18‬ه ـ املقيــدة باحملكمــة برقــم ‪ 33120326‬وتاريــخ‬\n     ‫‪ 1433/01/18‬ه ـ ففــي يــوم االثنــن املوافــق‪ 1433/01/24‬ه ـ افتتحــت‬\n     ‫اجللســة الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي باحلــق اخلــاص ‪......... ،‬‬\n     ‫ســعودي اجلنســية مبوجــب الهويــة الوطنيــة رقــم ‪ .........‬واملدعــي العــام‬\n\n‫‪17‬‬\n\f‫بصفتــه عضــو هيئــة التحقيــق واالدعــاء العــام بدائــرة محافظــة جــدة‪،‬‬\n‫واملكلــف مــن قبــل هيئــة التحقيــق واالدعاء العام برقــم هـ م ‪1540/2/2‬‬\n‫وتاريــخ ‪1433/01/05‬ه ـ وادعيــا علــى ‪ )37( ............../‬عامـ ًا ‪ ،‬ســعودي‬\n‫اجلنســية ‪ ،‬مبوجــب ســجل مدنــي رقــم () ‪ ،‬مطلــق الســراح بالكفالــة‬\n‫احلضوريــة ‪.‬حيــث أنــه بتاريــخ ‪1432/11/8‬ه ـ تســلم مركــز شــرطة‬\n‫النزهــة الشــكوى املقدمــة مــن املدعــي‪، /‬ســعودي اجلنســية ‪ ،‬ومفادهــا‬\n‫ان املدعــى عليــه رمــى عليــه فنجــان شــاي وصــدر بشــأنه التقريــر‬\n‫الطبــي مــن الشــؤون الصحيــة مبحافظــة الطائــف رقــم بــدون بتاريــخ‬\n‫‪1432/11/8‬هـ‪،‬املتضمــن إصابتــه بجــرح بالــراس بطــول ‪4‬ســم نصــف‬\n‫ســم‪ ،‬مــدة الشــفاء عشــرة أيام‪.‬وبســماع أقــوال املدعــى عليــه‪، ........../‬‬\n‫أقــر برمــي املدعــي بفنجــان شــاي بســبب وجــود خالفــات عائليــة ســابقة‬\n‫بينهمــا‪ .‬وانتهــى التحقيــق إلــى توجيــه االتهــام إلــى املدعــى عليــه برمــي‬\n‫املدعــي بفنجــان شــاي والتســبب يف إصابتــه باإلصابــة املدونــة بالتقريــر‬\n                                        ‫الطبــي وذلــك لألدلــة والقرائــن التاليــة‪:‬‬\n                                   ‫‪ )1‬اعترافه املنوه عنه مبلف التحقيق ص(‪.)1‬‬\n                                                                  ‫‪ )2‬التقرير الطبي‪.‬‬\n                  ‫وبالبحث عن سوابق املدعى عليه لم يعثر له على سوابق ‪.‬‬\n‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه املذكــور أعــاه فعــل محــرم و‬\n‫معاقــب عليــه شــرع ًا ‪ ،‬لــذا اطلــب مــن احملكمــة اجلزئيــة مبحافظــة جــدة‬\n‫إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة لقــاء مــا بــدر منــه‪.‬‬\n‫ا مــا ذكــره املدعــي‬      ‫ونســأله اجلــواب وبســؤال املدعــى عليــه أجــاب قائـ ً‬\n‫العــام مــن أننــي قمــت بضــرب املدعــي بفنجــان فصحيــح أمــا كــون‬\n‫الفنجــان أصــاب رأس املدعــي فغيــر صحيــح والصحيــح أن الفنجــان‬\n\n\n                                                                                         ‫‪18‬‬\n\f     ‫أصــاب صــدره هكــذا أجــاب وبســؤال املدعــى عليــه علــى بينتــه علــى‬\n     ‫أن الفنجــان أصــاب صــدره قــال هــذا مــا شــاهدته وبســؤال املدعــي العــام‬\n     ‫واملدعــي اخلــاص عــن بينتهمــا أجــاب املدعــي اخلــاص قائــا نعــم لــدي‬\n     ‫بينــه علــى ذلــك أطلــب إمهالــي إلحضارهــا لــذا رفعــت اجللســة وأعطــي‬\n     ‫موعــدا يف يــوم األحــد املوافــق ‪1433/02/14‬ه ـ الســاعة احلاديــة عشــر‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا القاضــي باحملكمــة اجلزئيــة والقائــم‬\n     ‫بعمــل القاضــي مبوجــب التكليــف رقــم ‪ /260‬ش يف ‪1433/2/13‬ه ـ‬\n     ‫ويف اجللســة املقررةيــوم االحــد املوافــق ‪1443/2/14‬ه ـ افتتحــت اجللســة‬\n     ‫الســاعة ‪ 12 : 00‬وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى‬\n     ‫ال مــن مينــي اجلنســية مبوجــب االقامــة‬\n                                              ‫عليــه واملدعــي اخلــاص وحضــر ك ً‬\n     ‫رقــم والــذي يعمــل ميكانيكــي ســيارات كمــا حضــر مينــي اجلنســية‬\n     ‫مبوجــب االقامــة رقــم والــذي يعمــل ميكانيكــي ســيارات وبســؤالهما‬\n     ‫كل واحــد مبفــرده شــهد كل واحــد منهمــا بــأن املدعــى عليــه قــام‬\n     ‫بضــرب املدعــى اخلــاص ولــم أرى املوضــع الــذي ضــرب بــه الفنجــان‬\n     ‫يف جســم املدعــى اخلــاص لكــن وبعــد املضاربــة رأينــا إصابــة يف رأس‬\n     ‫املدعــي اخلــاص بعــد ذلــك هكــذا شــهد كل واحــد منهمــا وبعــرض‬\n     ‫ا ماجــاء يف الشــهادة صحيــح‬    ‫الشــهادة علــى املدعــى عليــه أجــاب قائ ـ ً‬\n     ‫لكــن االصابــة التــي حلقــت بــرأس املدعــي اخلــاص ليســت منــي وليســت‬\n     ‫مســؤول عنهــا والفنجــان الــذي رميــت بــه ضــرب يف صــدره وبســؤال‬\n     ‫املدعــي اخلــاص هــل لديــك بينــة علــى أن االصابــة التــي يف رأســك مــن‬\n     ‫املدعــى عليــه قــال ليــس لــدي ســوى ماقدمــت وعليــه رفعــت اجللســة‬\n     ‫وتأجلــت يف يــوم الســبت املوافــق ‪1433/2/27‬ه ـ ويف اجللســة املقررة يوم‬\n     ‫الســبت املوافــق ‪1433/02/27‬ه ـ الســاعة ‪ 10 : 30‬افتتحــت اجللســة‬\n\n\n‫‪19‬‬\n\f‫وفيهــا حضــر املدعــي العــام وحضــر حلضــوره املدعــى عليــه واملدعــي‬\n‫اخلــاص وقــال أطلــب حقــي الشــرعي منــه وإلزامــه بدفــع أرش إصابتــي‬\n‫وتعزيــره لقــاء إهانتــي وبعــد ذلــك جــرى ســؤال املدعــى عليــه عــن الشــهود‬\n‫فقــال ال أطعــن فيهــم ولــي معرفــه بهــم ولكــن الفنجــان ضــرب يف صــدره‬\n‫ولــم يضــرب يف رأســه وال بينــه لــدي إال نفــس الشــهود الذيــن شــهدوا‬\n‫وال اعلــم مــن ضربــه يف رأســه وقــد جــرى منــي إحالــة املعاملــة إلــى جلنــة‬\n‫الصلــح برقــم ‪ 33120326‬يف ‪1433/02/27‬ه ـ لــذا رفعــت اجللســة إلــى‬\n‫حــن ورود اإلجابــة مــن جلنــة الصلــح ‪.‬احلمــد هلل وحــده وبعــد فلــدي أنــا‬\n‫القاضــي يف احملكمــة اجلزائيــة مبحافظــة جــدة والقائــم بعمــل القاضــي‬\n‫مبوجــب قــرار التكليــف رقــم ‪331348829‬وتاريــخ ‪1433/07/19‬ه ـ‬\n‫ويف اجللســة املقــررة يــوم األحــد املوافــق‪ 1433/07/20‬ه ـ افتتحــت‬\n‫اجللســة الســاعة ‪ 11 :30‬لســماع دعــوى املدعــي العــام ضــد وفيهــا حضــر‬\n‫املدعــي العــام و املدعــى باحلــق اخلــاص ولــم يحضــر املدعــى عليــه مــع‬\n‫علمــه باملوعــد احملــدد مســبق ًا لــذا رفعــت اجللســة حلــن حضــوره يف‬\n‫املوعــد احملــدد وذلــك يــوم األحــد املوافــق ‪1433/08/11‬ه ـ الســاعة‬\n‫‪ . 11 : 15‬ويف اجللســة املقــررة يــوم الســبت املوافــق ‪1433/02/27‬ه ـ‬\n‫الســاعة ‪ 10 : 30‬افتتحــت اجللســة وفيهــا حضــر املدعــي العــام وحضــر‬\n‫حلضــوره املدعــى عليــه واملدعــي اخلــاص وقــال أطلــب حقــي الشــرعي‬\n‫منــه وإلزامــه بدفــع أرش إصابتــي وتعزيــره لقــاء إهانتــي وبعــد ذلــك‬\n‫جــرى ســؤال املدعــى عليــه عــن الشــهود فقــال ال أطعــن فيهــم ولــي معرفــه‬\n‫بهــم ولكــن الفنجــان ضــرب يف صــدره ولــم يضــرب يف رأســه وال بينــه‬\n‫لــدي إال نفــس الشــهود الذيــن شــهدوا وال اعلــم مــن ضربــه يف رأســه‬\n‫وقــد جــرى منــي إحالــة املعاملــة إلــى جلنــة الصلــح برقــم ‪ 33120326‬يف‬\n\n\n                                                                                     ‫‪20‬‬\n\f     ‫‪1433/02/27‬ه ـ لــذا رفعــت اجللســة إلــى حــن ورود اإلجابــة مــن جلنــة‬\n     ‫الصلــح ويف جلســة أخــرى وردنــا خطــاب جلنــة الصلــح رقــم ‪33120326‬‬\n     ‫يف ‪1433/5/16‬ه ـ وبســؤال املدعــي العــام واملدعــي باحلــق اخلــاص هــل‬\n     ‫لديكمــا زيــادة بينــه قــاال ليــس لدينــا بينــه ســوى مــا قدمنــا ومــا جــاء يف‬\n     ‫املعاملــة مــن أدلــة وقرائــن عليــه جــرى منــي الرجــوع إلــى اعترافــه املــدون‬\n     ‫لفــة رقــم (‪ )1‬املتضمــن أنــه وبســؤاله عمــا جــاء يف أقــوال املدعــي أنكــر‬\n     ‫نهائي ـ ًا بــل هــو مــن قــام برميــي بطفايــة علبــة الســجائر وعــن اإلصابــة‬\n     ‫التــي حدثــت باملدعــي أفــاد أنــه ال يعلــم عنهــا نهائيـ ًا وال يعلــم مــن تســبب‬\n     ‫بهــا وأنهــا دعــوة كيديــة وبعــد االطــاع عليهــا لــم أجــد فيهــا اعتــراف‬\n     ‫للمدعــى عليــه كمــا ذكــر املدعــي العــام كمــا جــرى منــي الرجــوع‬\n     ‫إلــى التقريــر الطبــي املرفــق باملعاملــة لفــة رقــم (‪ )8‬واملتضمنــة أنــه يوجــد‬\n     ‫جــرح بالــرأس بطــول ‪ 4‬ســم ‪ ،‬نصــف ســم ومــدة الشــفاء عشــرة أيــام‬\n     ‫وهــو بتاريــخ ‪1432/11/08‬ه ـ وعليــه وبنــاء علــى مــا تقــدم مــن الدعــوى‬\n     ‫واإلجابــة وحيــث إن املدعــي باحلــق اخلــاص تقــوي جانبــه مبــا يف دعــواه‬\n           ‫مبــا يلــي أوالً‪ :‬اعتــراف املدعــى عليــه بأنــه ضــرب املدعــي بفنجــان‬\n                            ‫ثانياً‪ :‬تزامن تاريخ الضرب مع تاريخ التقرير الطبي‬\n     ‫ثالثـاً‪ :‬مــا جــاء يف شــهادة الشــهود بــأن املدعــى عليــه قــام بضــرب املدعــى‬\n     ‫بفنجــان وبعــد املضاربــة شــاهدوا إصابــة يف وجــه املدعــي باحلــق اخلــاص‬\n     ‫عليه فق ــد ق ــررت الكتـاب ــة ملقدري الشجاج يف هذه احملكمة مبوجب‬\n     ‫خطابنا رقم ‪ 33120326‬وتاريخ ‪1434/01/14‬هـ لت ـقـديـر أرش اصـابة‬\n     ‫امل ــدعي ‪ ،‬وقــد وردنــا إفــادة مقــدري الشــجاج يف هــذه احملكمــة برقــم‬\n     ‫‪ 3457354‬و تاريــخ ‪1434/02/05‬ه ـ و املتضمنــة مــا نصــه يوجــد جــرح‬\n     ‫بالــرأس بطــول ‪ 4‬ســم و مــدة الشــفاء عشــرة أيــام و ال يوجــد مــكان‬\n\n\n‫‪21‬‬\n\f‫لإلصابــة عليــه نفيــد فضيلتكــم بــان تقديــر أرش اإلصابــة يقــدر بأربعــة‬\n‫آالف ريــال ( ‪ 4000‬ريــال ) و بــاهلل التوفيــق و مبــا أن جانــب املدعــي‬\n‫قــد تقــوى مبــا ذكــر ســابقا و ملــا ذكــره الفقهــاء مــن حتليــف أقــوى‬\n‫املتداعييناملتجاحديــن و لتقــوي جانــب املدعــي مبــا ذكــر ســابقا لــذا‬\n‫فقــد جــرى منــي عــرض اليمــن علــى املدعــي بــان يحلــف علــى أن املدعــي‬\n‫عليــه قــام برمــي فنجــان شــاهي عليــه و تســبب يف إصابتــه يف الــرأس و‬\n‫بعــد تذكيــره مبعظــم اليمــن و بقولــه صلــى اهلل عليــه وســلم ( مــن حلــف‬\n‫علــى ميــن هــو فيهــا فاجــر ليقتطــع بهــا مــال امــرئ مســلم لقــي اهلل و هــو‬\n‫عليــه غضبــان ) رواه مســلم فاســتعد لقــول اليمــن ثــم حلــف بعــد إذنــي‬\n‫لــه قائــا ( و اهلل العظيــم الــذي ال الــه غيــره عالــم الغيــب و الشــهادة أن‬\n‫املدعــي عليــه قــام برمــي فنجــان شــاهي علــي و تســبب يف إصابتــي يف‬\n‫الــرأس ) و اهلل العظيــم و عليــه و بنــاء علــى مــا تقــدم مــن الدعــوى و‬\n‫جوابهــا و إلقــرار املدعــي عليــه برمــي فنجــان الشــاهي و لتزامــن تاريــخ‬\n‫الضــرب مــع تاريــخ التقريــر الطبــي و ملــا جــاء يف شــهادة الشــهود و ملــا جاء‬\n‫يف تقريــر مقــدري الشــجاج املطابقــة ملــا جــاء يف الدعــوى و قناعتهمــا بــه‬\n‫و ملــا قــرره أهــل العلــم بــان البينــة ليســت محصــورة باعتــراف أو شــهود‬\n‫و ملــا ذكــره ابــن القيــم بــأن البينــة هــي كل مايبــن احلــق و يوضحــه و‬\n‫حللــف املدعــي باحلــق اخلــاص اليمــن املكملــة لبينتــه لــذا فقــد ثبــت لــدي‬\n‫قيــام املدعــي عليــه برمــي املدعــي بفنجــان شــاي و التســبب يف إصابتــه و‬\n‫مبــا أن مــا قــام بــه املدعــي عليــه فعــل محــرم و معاقــب عليــه شــرعا لقولــه‬\n‫تعالــى ( وال تعتــدوا ) و لقولــه صلــى اهلل عليــه و ســلم ( كل املســلم علــى‬\n‫املســلم حــرام دمــه و مالــه و عرضــه) ولقولــه صلــى اهلل عليــه و ســلم‬\n‫( املســلم مــن ســلم املســلمون مــن لســانه و يــده ) و نظــرا لعــدم و جــود‬\n\n\n                                                                                        ‫‪22‬‬\n\f     ‫ســوابق علــى املدعــي عليــه كمــا هــو مبــن يف صحيفــة الســوابق املرفقــة‬\n     ‫لفــة رقــم (‪ )18‬و نظــر لصلــة القرابــة بينهمــا كــون املدعــي عليــه زوج‬\n     ‫أخــت املدعــي و ذلــك كلــه أمــر يلحــظ فلمــا ســبق فقــد قــررت اآلتــي ‪:‬‬\n     ‫أوال ‪ :‬يجلــد املدعــي عليــه عشــرون جلــده و ذلــك لقــاء قيامــه مبــا نســب‬\n     ‫إليــه و ذلــك لقــاء احلــق العــام ‪ .‬ثانيــا ‪ :‬الزمــت املدعــي عليــه بدفــع مبلــغ و‬\n     ‫قــدره أربعــة أالف ريــال (‪ 4000‬ريــال) للمدعــي وذلــك لقــاء ارش إصابتــه‬\n     ‫و بذلــك كلــه حكمــت و بعــرض احلكــم علــى املدعــي العــام و املدعــي‬\n     ‫عليــه و املدعــي باحلــق اخلــاص قــرر املدعــي باحلــق اخلــاص القناعــة بــه‬\n     ‫كمــا قــرر املدعــي العــام عــدم معارضتــه و قــرر املدعــي عليــه عــدم‬\n     ‫القناعــة فافهمتــه باحلضــور يف يــوم الســبت املوافــق ‪1434/03/07‬ه ـ‬\n     ‫الســتالم نســخة مــن قــرار احلكــم لتقــدمي اعتراضــه عليــه خــال ثالثــن‬\n     ‫يومــا اعتبــارا مــن التاريــخ املشــار إليــه فــان مضــت املــدة و لــم يســتلم‬\n     ‫نســخة مــن احلكــم أو لــم يقــدم اعتراضــه عليــه خاللهــا فــان حقــه يف‬\n     ‫تقــدمي الئحــة االعتــراض يكــون ســاقطا و جــرى النطــق باحلكــم يف يــوم‬\n     ‫الثالثــاء املوافــق ‪1434/02/26‬ه ـ الســاعة ‪ 10 : 30‬وبــه أقفلــت اجللســة‬\n     ‫و علــى ذلــك جــرى التوقيــع وبــاهلل التوفيــق ‪ ،‬وصلــى اهلل علــى نبينــا‬\n               ‫محمــد وعلــى آلــه وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/26‬ه ـ‬\n               ‫احلمد هلل وحده والصالة والسالم على من ال نبي بعده وبعد ‪-:‬‬\n     ‫نحــن قضــاة الدائــرة اجلزائيــة السادســة مبحكمــة االســتئناف مبكــة‬\n     ‫املكرمــة جــرى منــا االطــاع علــى املعاملــة الــواردة إلــى هــذه احملكمــة‬\n     ‫بكتــاب فضيلــة رئيــس احملكمــة اجلزائيــة بجــده رقــم(‪)3457354‬‬\n     ‫وتاريخ(‪1434/5/28‬هــ) املرفــق بهــا القــرار رقــم(‪)3449421‬‬\n     ‫وتاريخ(‪1434/2/27‬هـ)الصــادر مــن فضيلــة الشــيخ‪ /‬القاضــي‬\n\n\n‫‪23‬‬\n\f‫باحملكمــة اجلزائيــة بجــدة ‪،‬املتضمــن دعــوى املدعــي العــام ضــد‪/‬‬\n‫ســعودي اجلنســية ‪ ،‬املتهــم برمــي شــخص بفنجــان شــاي والتســبب يف‬\n‫إصابتــه ‪ ،‬احملكــوم فيــه مبــادون باطنه‪،‬وبدراســة القــرار وصــورة‬\n‫ضبطــه والئحتــه االعتراضيــة تقــررت املوافقــة علــى احلكــم ‪ ،‬واهلل‬\n   ‫املوفق‪،‬وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم‪.‬‬\n\n\n\n\n                                                                          ‫‪24‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":16,"source_page_end":24,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"a7704868eaefc1c958244955645a67b20e6906f538b857f966e516d31564fed3","normalized_text_hash":"8e655485f7d6db94bd904b9a74f27d824a54ba1ec37510de1e257801e4e5714a","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p16-3449421"},{"id":"41bb860d-9514-55b7-b066-ee771e565d5f","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -ضرب -ضرب الزوج لزوجته -تنازل الزوجة عن حقها اخلاص -تعزير الزوج بالتوبيخ والسجن واجللد وأخذ التعهد.","document_number":"34226948","case_number":"3414182","judgment_number":null,"decision_number":null,"circular_number":null,"court":"محكمة الاستئناف","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/05/29","year":"1434","subject":"اعتداء -ضرب -ضرب الزوج لزوجته -تنازل الزوجة عن حقها اخلاص -تعزير الزوج بالتوبيخ والسجن واجللد وأخذ التعهد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك‪ 34226948 :‬تاريخه‪1434/05/29:‬هـ‬\n                          ‫رقم الدعوى‪3414182:‬‬\n         ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n              ‫‪ 34251682‬تاريخه‪1434/06/26 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬ضــرب ‪ -‬ضــرب الــزوج لزوجتــه ‪ -‬تنــازل الزوجــة عــن حقهــا‬\n      ‫اخلــاص ‪ -‬تعزيــر الــزوج بالتوبيــخ والســجن واجللــد وأخــذ التعهــد‪.‬‬\n\n\n\n                         ‫‪-1‬قول اهلل تعالى‪( :‬وعاشروهن باملعروف) [النساء‪.]19:‬‬\n     ‫‪-2‬حديــث معاويــة بــن حيــدة ‪ -‬رضــي اهلل عنــه ‪ -‬قــال‪ :‬قلــت يــا رســول اهلل‬\n     ‫مــا حــق زوجــة أحدنــا عليــه قــال‪« :‬أن تطعمهــا إذا طعمــت‪ ،‬وتكســوها إذا‬\n     ‫اكتســيت‪ ،‬وال تضــرب الوجــه وال تقبــح وال تهجــر إال يف البيــت» رواه‬\n      ‫أحمــد وأبــو داود وصححــه ابــن حبــان وقــال األلبانــي‪ :‬حســن صحيــح‪.‬‬\n     ‫‪ -3‬حديــث أبــي هريــرة قــال‪ :‬قــال النبــي ‪ -‬صلــى اهلل عليــه وســلم‪( :-‬إذا‬\n                            ‫قاتــل أحدكــم أخــاه فليجتنــب الوجــه) رواه مســلم‪.‬‬\n     ‫‪ -4‬قــول النــووي ‪ -‬رحمــه اهلل ‪ ،‬يف شــرحه للحديــث الســابق‪(:-‬هذا‬\n     ‫تصريــح بالنهــي عــن ضــرب الوجــه؛ ألنــه لطيــف يجمــع احملاســن‬\n     ‫وأعضــاؤه نفيســة لطيفــة وأكثــر اإلدراك بهــا‪ ،‬فقــد يبطلهــا ضــرب‬\n     ‫الوجــه وقــد ينقصهــا وقــد يشــوه الوجــه‪ ،‬والشــن فيــه فاحــش؛ ألنــه بــارز‬\n     ‫ظاهــر ال ميكــن ســتره‪ ،‬ومتــى ضربــه ال يســلم مــن شــن غالبـ ًا‪ ،‬ويدخــل‬\n     ‫يف النهــي إذا ضــرب زوجتــه أو ولــده أو عبــده ضــرب تأديــب فليجتنــب‬\n                                                                  ‫الوجــه) [‪.]165/16‬‬\n     ‫‪ -5‬التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل ‪ ،‬كمــا نــص علــى ذلــك‬\n                                                                             ‫الفقهــاء‪.‬‬\n‫‪25‬‬\n\f‫تقــدم مواطــن ببــاغ عــن تعــرض شــقيقته لإلعتــداء بالضــرب مــن‬\n‫قبــل زوجهــا املدعــى عليــه ‪ ،‬والتســبب يف إصابتهــا بكســر يف أصبــع‬\n‫قدمهــا اليمنــى ومــدة الشــفاء أربعــة أســابيع حســب تقريــر املستشــفى‪،‬‬\n‫بالتحقيــق معــه جــرى توجيــه اإلتهــام لــه بضــرب زوجتــه والتســبب يف‬\n‫إصابتهــا اإلصابــة املوصوفــة بالتقريــر الطبــي ‪ ،‬وطلــب إثبــات مــا أســند‬\n‫إليــه وإيقــاع العقوبــة التعزيريــة ‪ ،‬وقــد انتهــى احلــق اخلــاص بالتنــازل ‪،‬‬\n‫أنكــر املدعــى عليــه قيامــه بضــرب زوجتــه والتســبب يف كســر أصبعها‬\n‫وأقــر بأنــه دخــل املنــزل فلــم يجدهــا فلمــا حضــرت وســألها أيــن كانــت‬\n‫فأجابتــه بــأن هــذا ليــس مــن شــأنه ‪ ،‬فحصــل بينهمــا شــجار فصفعهــا‬\n‫صفعتــن وبصــق عليهــا ‪ ،‬وقــرر بــأن اإلصابــة املشــار لهــا يف التقريــر‬\n‫قدميــة إثــر ســقوطها مــن الــدرج وأن زوجتــه كثيــرة اخلــروج مــن املنــزل‬\n‫بغيــر إذنــه وأفــادت الزوجــة وشــقيقها قيــام زوجهــا بضربهــا ‪ ،‬فأنكــر‬\n‫وأفــاد أنهــا دائمـ ًا تخــرج دون إذنــه وصــدر بحقهــا صــك شــرعي يتضمــن‬\n‫عــدم خروجهــا مــن البيــت إال بإذنــه وإلقــرار املدعــى عليــه قيامــه بصفــع‬\n‫زوجتــه صفعتــن والبصــق عليهــا وإلنــكاره قيامــه بضربهــا ضربــا‬\n‫مبرحــا والتســبب يف كســر أصبعهــا ‪ ،‬ولعــدم قيــام البينــة علــى ذلــك‬\n‫وبنــاء علــى التقريــر الطبــي قــررت احملكمــة مــا يلــي ‪ :‬أوال‪ /‬عــدم ثبــوت‬\n‫قيــام املدعــى عليــه بضــرب زوجتــه ضربــا مبرحــا والتســبب يف إصابتهــا‬\n‫بكســر أصبــع قدمهــا اليمنــى إال أن التهمــة القوية تتوجــه نحوه ‪ ،‬ولعدم‬\n‫وجــود ســوابق عليــه ‪ ،‬وملــا ظهــر عليــه مــن توبــة ونــدم‪ ،‬ولكونــه متــزوج‬\n‫ولديــه أطفــال‪ ،‬وهــذه مســوغات معتبــرة يف تخفيــف العقوبــة عنــه لــذا‬\n\n                                                                                    ‫‪26‬‬\n\f     ‫فقــد قـ َـر َرت تعزيــره لقــاء ذلــك بســجنه ملــدة أســبوع محســوبا منهــا مــدة‬\n     ‫توقيفــه وجلــده ثالثــن جلــدة دفعــة واحــدة‪ .‬ثانيــا‪ :‬ثبــت قيــام املدعــى عليــه‬\n     ‫بصفــع زوجتــه صفعتــن علــى وجههــا والبصــق عليهــا وألن هــذا الفعــل‬\n     ‫فيــه مخالفــة شــرعية حيــث نهــى النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬عــن‬\n     ‫تقبيــح الوجــه فمــن بــاب أولــى البصــق والضــرب علــى الوجــه وكل ذلــك‬\n     ‫إكرامـ ًا للوجــه‪ ،‬وملــا كان التعزيــر يبــدأ بالتوبيــخ وينتهــي بالقتــل كمــا‬\n     ‫نــص علــى ذلــك الفقهــاء‪ ،‬فقــد جــرى توبيــخ املدعــى عليــه ولومــه علــى‬\n     ‫فعلــه‪ .‬ثالثــا‪ :‬أخــذ التعهــد علــى املدعــى عليــه بعــدم تكــرار مــا بــدر منــه‬\n     ‫وقــرر املدعــى عليــه القناعــة بينمــا اعتــرض املدعــي العــام وطلــب رفعــه‬\n         ‫لالســتئناف بــدون الئحــة‪ .‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ..........‬املــازم القضائــي باحملكمــة‬\n     ‫اجلزائيــة باألحســاء يف املكتــب القضائــي وبنــاء علــى املعاملــة احملالــة‬\n     ‫مــن رئيــس احملكمــة اجلزائيــة باألحســاء برقــم ( ) يف ‪1434/1/10‬هـ ـ‬\n     ‫واملقيــدة برقــم ( ) يف ‪1434/1/10‬ه ـ وبنــاء علــى تعميــدي مــن فضيلــة‬\n     ‫الشــيخ ‪ ..........‬رئيــس احملكمــة اجلزائيــة باألحســاء املكلــف مبوجــب‬\n     ‫خطابــه رقــم ( ) يف ‪1434/4/21‬ه ـ لنظــر القضايــا مــا عــدا الســجناء‬\n     ‫ويف يــوم األربعــاء املوافــق ‪1434/4/24‬ه ـ افتتحــت اجللســة األولــى‬\n     ‫يف متــام الســاعة التاســعة يف هــذه القضيــة رقــم ( ) وفيهــا حضــر‬\n     ‫املدعــي العــام ‪..........‬الســعودي بالســجل املدنــي رقــم (‪ )..........‬وحضــر‬\n     ‫حلضــوره املدعــى عليــه ‪ ..........‬الســعودي بالســجل املدنــي رقــم (‪)..........‬‬\n     ‫وبســؤال املدعــي العــام عــن دعــواه قــال بصفتــي مدعيــا عامــا بدائــرة‬\n\n‫‪27‬‬\n\f‫االدعــاء العــام مبحافظــة األحســاء أدعــي علــى كل ‪ ،........../‬البالــغ‬\n‫مــن العمــر (‪ )41‬عام ـ ًا ‪ ،‬ســعودي اجلنســية ‪ ،‬مبوجــب الســجل املدنــي‬\n‫رقم‪..........‬أوقــف بتاريــخ ‪ 1433/11/8‬ه ـ وأفــرج عنــه بالكفالــة بتاريــخ‬\n‫‪1433/11/9‬ه ـ يســكن مبحافظــة األحســاء ‪ /‬قريــة ‪...........‬إنــه بتاريــخ‬\n‫‪1433/10/23‬ه ـ تقــدم املدعو‪........../‬ببــاغ مفــاده تعــرض شــقيقته‬\n‫املدعوة‪........../‬لالعتــداء بالضــرب مــن قبــل املدعــى عليــه (زوجهــا)‬\n‫والتســبب يف إصابتهــا‪ .‬وبضبــط أقــوال املجنــي عليها‪........../‬أفــادت‬\n‫انــه بتاريــخ ‪1433/10/20‬ه ـ وأثنــاء تواجدهــا مبنــزل زوجهــا وقيامهــا‬\n‫بإعــداد طعــام اإلفطــار لــه حصــل بينهمــا ســوء تفاهــم ممــا أدى باملدعــى‬\n‫عليــه بضربهــا وركلهــا وســقوطها علــى األرض والتســبب يف إصابتهــا‬\n‫وقــد صــدر بحقهــا التقريــر الطبــي رقــم(‪ )..........‬وتاريخ‪1433/11/1‬ه ـ‬\n‫مــن مستشــفى امللــك فهــد بالهفــوف املتضمــن إصابتهــا بكســر بإصبــع‬\n‫قدمهــا اليمنــى ومــدة الشــفاء أربعــة أســابيع مــا لــم حتــدث مضاعفــات‬\n‫وباســتجواب املدعــى عليــه أقــر بقيامــه بضــرب زوجتــه (‪ )..........‬بســبب‬\n‫خــاف حــدث بينهمــا‪ .‬وقــد أســفر التحقيــق معــه عــن توجيــه االتهــام لــه‬\n‫بضــرب زوجتــه ضربــا مبرحــا والتســبب يف اصابتهــا اإلصابــة املوصوفــة‬\n‫يف التقريــر الطبــي ‪ ،‬وذلــك لألدلــة والقرائــن التاليــة ‪ -1 :‬إقراره حتقيقا‬\n‫املــدون علــى الصفحــة رقــم ( ‪ ) 13 - 12‬مــن ملــف تقريــر األحــوال األمنية‬\n                                                       ‫املوحــد املرفــق لفــة رقــم(‪. )1‬‬\n‫‪ -2‬بــاغ شــقيق املجنــي عليهــا املــدون علــى الصفحــة رقــم(‪ )1‬مــن ملــف‬\n                          ‫تقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم(‪. )1‬‬\n‫‪ -3‬مــا جــاء يف أقــوال املجنــي عليهــا املــدون علــى الصفحــة رقــم(‪-10-9‬‬\n       ‫‪ )11‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد املرفــق لفــة رقــم(‪.)1‬‬\n\n\n                                                                                            ‫‪28‬‬\n\f                                                     ‫‪ -4‬التقرير الطبي املرفق لفة ( ‪.)9‬‬\n     ‫وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســوابق جنائيــة مســجلة ‪ .‬وحيــث‬\n     ‫إن مــا أقــدم عليــه املذكــور ـ وهــو بكامــل أهليتــه املعتبــرة شــرع ًا ـ فعــل‬\n     ‫محــرم ومعاقــب عليــه شــرع ًا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه‬\n     ‫بعقوبــة تعزيريــة رادعــه لــه وزاجــرة لغيــره لقــاء مــا أســند إليــه مــن اتهــام ‪.‬‬\n     ‫(علمـ ًا أن احلــق اخلــاص انتهــى بالتنــازل) ‪ .‬هــذه دعــواي وبســؤال املدعــى‬\n     ‫عليــه عــن دعــوى املدعــي العــام أجــاب قائــا إن مــا ذكــره املدعــي العــام‬\n     ‫مــن قيامــي بضــرب املجنــي عليهــا ضربــا مبرحــا وركلهــا وســقوطها‬\n     ‫علــى األرض والتســبب يف إصابتهــا بكســر أصبــع قدمهــا اليمنــى فغيــر‬\n     ‫صحيــح والصحيــح أنــه يف نفــس اليــوم الــذي حصلــت فيــه املشــكلة‬\n     ‫كنــت عائــدا مــن العمــل الســاعة العاشــرة صباحــا فدخلــت بيتــي فلــم‬\n     ‫أجــد املجنــي عليهــا يف البيــت وبعــد مضــي ربــع ســاعة تقريبــا دخلــت‬\n     ‫املجنــي عليهــا إلــى البيــت ومعهــا طفلــي فقمــت بســؤالها أيــن كنتــي‬\n     ‫فــردت علــي ليــس لــك دخــل أطلــع أو مــا أطلــع فقلــت لهــا أنا ولــي أمرك ال‬\n     ‫بــد مــن أخــذ أذنــي يف اخلــروج فقامــت برفــع صوتهــا علــي فقمــت بضربهــا‬\n     ‫كفــن علــى وجههــا وقمــت بالبصــق عليهــا ولــم أقــم بكســر أصبعهــا‬\n     ‫مطلقــا وإمنــا هــذه اإلصابــة قدميــة حيــث إن املجنــي عليهــا ســقطت مــن‬\n     ‫الــدرج فحصلــت لهــا هــذه اإلصابــة واملجنــي عليهــا دائمــا تخــرج مــن‬\n     ‫بيتــي بــدون أذنــي وقــد صــدر بحقهــا صــك شــرعي صــادر مــن قاضــي‬\n     ‫األوقــاف واملواريــث برقــم (‪ )..........‬يف ‪1424/10/20‬ه ـ يتضمــن عــدم‬\n     ‫خروجهــا مــن بيتــي إال بــأذن منــي هكــذا أجــاب هــذا فتــم اطالعــي علــى‬\n     ‫الصــك املذكــور فوجدتــه مطابــق ملــا ذكــره هــذا فتــم ســؤاله عــن عمــره‬\n     ‫فقــال أبلــغ مــن العمــر ‪ 41‬عامــا هكــذا قــال كمــا مت ســؤاله عــن عملــه‬\n\n\n‫‪29‬‬\n\f‫فقــال أعمــل يف إدارة التربيــة والتعليــم هكــذا قــال كمــا مت ســؤاله‬\n‫هــل لديــه أطفــال فقــال نعــم لــدي ســتة أطفــال هكــذا قــال وبطلــب‬\n‫البينــة مــن املدعــي العــام اســتعد بإحضارهــا يف اجللســة القادمــة وذلــك‬\n‫يف يــوم األحــد ‪1434/5/19‬ه ـ الســاعة العاشــرة والنصــف واهلل املوفــق‬\n‫واختتمــت اجللســة يف متــام الســاعة التاســعة والنصــف صباحــا وللبيــان‬\n‫حرر يف ‪1434/4/24‬هـ وصلى اهلل على نبينا محمد وعلى آله وصحبه‬\n‫وســلم‪ .‬احلمــد هلل وحــده وبعــد ويف يــوم األحــد ‪1434/5/19‬ه ـ افتتحــت‬\n‫اجللســة الثانيــة يف متــام الســاعة العاشــرة والنصــف وفيهــا حضــر املدعــي‬\n‫العــام ‪..........‬وحضــر حلضــوره املدعــى عليــه‪ ..........‬املذكــورة هويتهمــا‬\n‫ســابقا وبطلــب البينــة مــن املدعــي العــام التــي اســتعد بإحضارهــا يف هــذه‬\n‫اجللســة قــال ليــس لــدي بينــة ســوى مــا ورد يف أوراق املعاملــة هكــذا قــال‬\n‫هــذا فتــم اطالعــي علــى بــاغ شــقيق املجنــي عليهــا املــدون علــى الصفحة‬\n‫رقــم (‪ )1‬مــن ملــف تقريــر األحــوال األمنيــة املوحــد املرفــق يف املعاملــة‬\n‫علــى اللفــة رقــم (‪ )1‬ويتضمــن (تعــرض املجنــي عليهــا باالعتــداء عليهــا‬\n‫بالضــرب مــن قبــل زوجهــا وذلــك بســبب ســوء تفاهــم حصــل بينهمــا ممــا‬\n‫نتــج عنــه إصابــة املجنــي عليهــا بالقــدم اليمنــى وكســر بأصبــع اإلبهــام‬\n‫للقــدم اليمنــى) أ‪.‬هـ ـ وبعرضــه علــى املدعــى عليــه قــال غيــر صحيــح فأنــا‬\n‫لــم أقــم بالتســبب لهــا باإلصابــة املذكــورة وإمنــا هــي إصابــة قدميــة حدثــت‬\n‫لهــا ملــا ســقطت املجنــي عليهــا مــن الــدرج هكــذا قــال كمــا مت اطالعــي‬\n‫علــى إفــادة املجنــي عليهــا املدونــة علــى الصفحــة رقــم (‪ )10‬مــن ملــف‬\n‫تقريــر األحــوال األمنيــة املوحــد املرفــق يف املعاملــة علــى اللفــة رقــم (‪)1‬‬\n‫وتتضمــن (حضــر زوجــي املدعــى عليــه وقمــت بإحضــار وجبــة اإلفطــار‬\n‫لــه وبعــد ذلــك طلــب منــي الذهــاب إلــى منــزل أهلــي فقلــت لــه ســوف‬\n\n\n                                                                                       ‫‪30‬‬\n\f     ‫أذهــب وبعــد ذلــك قــام بضربــي بيديــه وركلــي عــدة ركالت بقدميــه‬\n     ‫وكذلــك قــام برمــي ترمــس الشــاي علــي وكذلــك دفعنــي بيــده ممــا‬\n     ‫أدى لســقوطي علــى األرض وحصلــت بــي إصابــة بقدمــي اليمنــي وكــذا‬\n     ‫أصبــع إبهــام قدمــي اليمنــى) أ‪.‬ه ـ ـ وبعرضــه علــى املدعــى عليــه قــال غيــر‬\n     ‫صحيــح جملــة وتفصيــا والصحيــح مــا ذكرتــه يف إجابتــي هكــذا قــال‬\n     ‫كمــا مت اطالعــي علــى التقريــر الطبــي ويتضمــن (إصابــة املجنــي عليهــا‬\n     ‫بكســر يف األصبــع الكبيــر للقــدم اليمنــى‪ .‬ومــدة الشــفاء أربعة أســابيع‬\n     ‫مــا لــم حتــدث مضاعفــات ســبب اإلصابــة ادعــاء باعتــداء بالضرب)أ‪.‬هـ ـ‬\n     ‫وبعرضــه علــى املدعــى عليــه قــال‪ :‬غيــر صحيــح هكــذا قــال هــذا فتــم‬\n     ‫ســؤال املدعــى عليــه هــل لديــك بينــة على أن كســر أصبــع زوجتك كان‬\n     ‫بســبب ســقوطها مــن الــدرج قــال‪ :‬ال هكــذا قــال فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة وحيــث أقــر املدعــى عليــه بضــرب زوجتــه كفــن‬\n     ‫علــى وجههــا والبصــق عليهــا وحيــث أنكــر املدعــى عليــه قيامــه بضــرب‬\n     ‫زوجتــه ضربــا مبرحــا والتســبب يف إصابتهــا بكســر أصبــع قدمهــا‬\n     ‫اليمنــى وحيــث ال يوجــد بينــة لــدى املدعــي العــام ســوى مــا ورد يف أوراق‬\n     ‫املعاملــة وبعــد االطــاع علــى إفــادة املجنــي عليهــا وعلــى التقريــر الطبــي‬\n                                                   ‫لذلــك كلــه فقــد قــررت مــا يلــي ‪:‬‬\n     ‫أوال‪ :‬لــم يثبــت لــدي قيــام املدعــى عليــه بضــرب زوجتــه ضربــا مبرحــا‬\n     ‫والتســبب يف إصابتهــا بكســر أصبــع قدمهــا اليمنــى إال أن التهمــة‬\n     ‫القويــة تتوجــه نحــوه ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق‬\n     ‫وملــا ظهــر عليــه مــن توبــة ونــدم ولكونــه متــزوج ولديــه أطفــال وهــذه‬\n     ‫مســوغات معتبــرة يف تخفيــف العقوبــة عنــه لــذا فقــد قــررت تعزيــره لقــاء‬\n     ‫ذلــك بســجنه ملــدة أســبوع محســوب ًا منهــا مــدة توقيفــه وجلــده ثالثــن‬\n\n\n‫‪31‬‬\n\f                                                             ‫جلــدة دفعــة واحــدة‪.‬‬\n‫ثانيــا‪ :‬ثبــت لــدي قيــام املدعــى عليــه بضــرب زوجتــه كفــن علــى وجههــا‬\n‫والبصــق عليهــا وحيــث إن هــذا الفعــل فيــه مخالفــة لألوامــر الشــرعية‬\n‫منهــا قولــه تعالــى‪، :‬وعاشــروهن باملعــروف‪[ ،‬النســاء‪ ]19:‬وحلديــث‬\n‫معاويــة بــن حيــدة ‪ -‬رضــي اهلل عنــه ‪ -‬قــال‪ :‬قلــت يــا رســول اهلل مــا حــق‬\n‫زوجــة أحدنــا عليــه قــال‪(( :‬أن تطعمهــا إذا طعمــت‪ ،‬وتكســوها إذا‬\n‫اكتســيت‪ ،‬وال تضــرب الوجــه وال تقبــح وال تهجــر إال يف البيــت)) رواه‬\n‫أحمــد وأبــو داود وصححــه ابــن حبــان وقــال األلبانــي‪ :‬حســن صحيــح‪.‬‬\n‫فــإذا نهــى النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪ -‬عــن تقبيــح الوجــه فمــن بــاب‬\n‫أولــى البصــق والبــزق والضــرب علــى الوجــه وكل ذلــك إكرام ًا للوجه‪،‬‬\n‫فقــد قــال النبــي ‪ -‬صلــى اهلل عليــه وســلم ‪(( :-‬إذا قاتــل أحدكــم أخــاه‬\n‫فليجتنــب الوجــه)) رواه مســلم فقــد جــاء يف كتــاب شــرح صحيــح مســلم‬\n‫لإلمــام النــووي ‪ -‬رحمــه اهلل ‪ -‬مــا نصــه‪(( :‬هــذا تصريــح بالنهــي عــن‬\n‫ضــرب الوجــه؛ ألنــه لطيــف يجمــع احملاســن وأعضــاؤه نفيســة لطيفــة‬\n‫وأكثــر اإلدراك بهــا‪ ،‬فقــد يبطلهــا ضــرب الوجــه وقــد ينقصهــا وقــد‬\n‫يشــوه الوجــه‪ ،‬والشــن فيــه فاحــش؛ ألنــه بــارز ظاهــر ال ميكــن ســتره‪،‬‬\n‫ومتــى ضربــه ال يســلم مــن شــن غالب ـاً‪ ،‬ويدخــل يف النهــي إذا ضــرب‬\n‫زوجتــه أو ولــده أو عبــده ضــرب تأديــب فليجتنــب الوجــه)) [‪،]165/16‬‬\n‫ولكــون التعازيــر تبــدأ بالتوبيــخ وتنتهــي بالقتــل كمــا نــص علــى ذلــك‬\n‫الفقهــاء ونظــرا لكــون املدعــى عليــه ال يوجــد عليــه ســوابق وملــا ظهــر‬\n‫عليــه مــن توبــة ونــدم ولكونــه متــزوج ولديــه أطفــال وهــذه مســوغات‬\n‫معتبــرة يف تخفيــف العقوبــة عنــه لــذا فقــد مت توبيــخ املدعــى عليــه ولومــه‬\n‫علــى فعلــه وإفهامــه مبغبــة عملــه ونتائجــه وآثــاره الســلبية علــى زوجتــه‬\n\n\n                                                                                      ‫‪32‬‬\n\f                                                                           ‫وعلــى أوالده ‪.‬‬\n     ‫ثالثــا‪ :‬أخــذ التعهــد الشــديد علــى املدعــى عليــه بعــدم تكــرار مــا بدر منه‬\n     ‫ومبــا ســبق كلــه حكمــت وبعرضــه علــى املدعــى عليــه قــرر القناعــة بــه‬\n     ‫كمــا قــرر املدعــي العــام املعارضــة عليــه واكتفــى مبــا جــاء يف الئحــة‬\n     ‫الدعــوى عــن تقــدمي الئحــة اعتراضيــة وبذلــك تكــون القضيــة منتهيــة‬\n     ‫وقــررت بعــث كامــل أوراق املعاملــة حملكمــة االســتئناف بالشــرقية‬\n     ‫لتدقيــق احلكــم حســب املتبــع وبــاهلل التوفيــق واختتمــت اجللســة يف‬\n     ‫متــام الســاعة احلاديــة عشــرة صباحــا وللبيــان حــرر يف ‪1434/5/19‬ه ـ ـ‬\n     ‫وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم تســليما كثيــرا‪.‬‬\n     ‫احلمــد هلل وحــده وبعــد ‪ . . .‬فقــد اطلعن ــا نحــن قـض ــاة الدائ ــرة اجلـزائي ــة‬\n     ‫األولــى مبحكمــة االســتئناف باملنطقــة الشــرقية علــى املعاملــة الــواردة‬\n     ‫مــن فضيلــة رئيــس احملكمــة اجلزائيــة مبحافظــة االحســاء املكلــف‬\n     ‫برقــم ‪ 3466584‬وتاريــخ ‪1434/6/10‬ه ـ املقيــدة لــدى احملكمــة برقــم‬\n     ‫‪ 341447048‬وتاريــخ ‪1434/6/14‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيلــة املــازم القضائــي باحملكمــة الشــيخ ‪..........‬املســجل برقــم‬\n     ‫وتاريــخ ‪1434/5/29‬ه ـ اخلــاص بدعوى‪/‬املدعــي العــام ضــد‪........../‬يف‬\n     ‫قضيــة إيــذاء زوجتــه وقــد تضمــن القــرار حكــم فضيلتــه مبــا هــو مــدون‬\n     ‫ومفصــل فيــه ‪ .‬وبدراســة القــرار وصــورة ضبطــه وأوراق املعاملــة قررنــا‬\n     ‫املصادقــة علــى احلكــم واهلل املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه‬\n                                           ‫وصحبــه وســلم حــرر يف ‪1434/6/25‬ه ـ‬\n\n\n\n\n‫‪33‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":25,"source_page_end":33,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"0a26efed8c3d8a454ecd2dce215e1177e30be4319d2d1b2196666233706da11f","normalized_text_hash":"aa9bf922bf795c596ba027dcb171d1416a06ed5699da2cc4dd111d1762976b70","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p25-34226948"},{"id":"5fa66688-7849-58da-b1ab-44efbc80005c","document_type":"judgment","category":"judicial","subcategory":"general","title":"إيذاء -ضرب -شروع يف القتل -تقرير طبي -إقرار -تعزير بالسجن","document_number":"34198838","case_number":"3427354","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/04/27","year":"1434","subject":"إيذاء -ضرب -شروع يف القتل -تقرير طبي -إقرار -تعزير بالسجن","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"             ‫رقم الصك ‪ 34198838 :‬تاريخه‪:‬‬\n      ‫‪1434/04/27‬هـ رقم الدعوى‪3427354:‬‬\n    ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n        ‫‪ 34212869‬تاريخه‪1434/05/14 :‬هـ‬\n\n\n\n‫إيذاء‪ -‬ضرب ‪ -‬شــروع يف القتل ‪ -‬تقرير طبي ‪ -‬إقرار ‪ -‬تعزير بالســجن‬\n                                                          ‫واجللد‪.‬‬\n\n\n\n\n        ‫‪-‬قول اهلل تعالى‪« :‬وال تقتلوا النفس التي حرم اهلل إال باحلق» ‪.‬‬\n‫‪-‬قــال صلــى اهلل عليــه وســلم ‪« :‬مــن أخــاف مؤمنــا كان حــق علــى اهلل‬\n                                       ‫أال يؤمنــه مــن أفــزاع يــوم القيامــة»‬\n‫‪ -‬قــال صلــى اهلل عليــه وســلم ‪« :‬مــن أشــار إلــى أخيــه بحديــدة فــإن‬\n‫املالئكــة تلعنــه حتــى يدعــه وإن كان أخــاه ألبيــه وأمــه» رواه مســلم ‪.‬‬\n\n\n\n\n‫أســفر التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بالشــروع يف قتــل زوج‬\n‫أختــه وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب‬\n‫يف إصابتــه بعــدة إصابــات موصوفــة بالتقريــر الطبــي‪ ،‬وذلــك بعدمــا مت‬\n‫القبــض علــى املدعــى عليــه إثــر ورود بــاغ للجهــات املختصــة يتضمــن‬\n‫وجــود شــخص مصــاب لتعرضــه للضــرب ب ــآلة حــادة فــأس مــن قبــل‬\n‫املدعــى عليــه ‪ ،‬صــدر بحقــه التقريــر الطبــي ومــدة الشــفاء ســتة أشــهر‪،‬‬\n‫بالبحــث عــن ســوابقه عثــر لــه على ســابقة مضاربة ‪ ،‬طلــب املدعي العام‬\n‫إثبــات مــا أســند إلــى املدعــى عليــه واحلكــم بعقوبــة تعزيريــة مشــددة‬\n\n                                                                                   ‫‪34‬‬\n\f     ‫‪ ،‬بعــرض دعــوى املدعــي العــام علــى املدعــى عليــه صــادق عليهــا جملــة‬\n     ‫ا ‪ ،‬جــرى االطــاع علــى التقريــر الطبــي ‪ ،‬وعلــى كــرت ســوابق‬        ‫وتفصيـ ً‬\n     ‫املدعــى عليــه املشــار إليهمــا‪ ،‬نظــر ًا ألن املدعــى عليــه صــادق علــى دعــوى‬\n     ‫املدعــي العــام ومبــا أن الشــريعة اإلســامية حرصــت علــى حفــظ النفــس‬\n     ‫وصيانتهــا وحمايتهــا مــن االعتــداء عليهــا وجتنيبهــا األضــرار التــي تفتــك‬\n     ‫بهــا ووضعــت كافــة الوســائل املؤديــة إلــى احملافظــة عليهــا لــذا وألجــل‬\n     ‫احلــق العــام فقــد ثبتــت إدانــة املدعــى عليــه بقيامــه بالشــروع يف قتــل زوج‬\n     ‫أختــه وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n     ‫إصابتــه بعــدة إصابــات ومت احلكــم بتعزيــره بالســجن مــدة أربــع ســنوات‬\n     ‫وجلــده ثمامنائــة جلــدة مفرقــة علــى ســت عشــرة دفعــة علــى أن يكــون‬\n     ‫اجللــد علنــا ‪ ،‬بعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة وقــرر‬\n     ‫املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة‪ ،‬وبعــد‬\n                        ‫رفــع احلكــم حملكمــة االســتئناف متــت املصادقــة عليــه‪.‬‬\n\n\n\n\n‫‪35‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي باحملكمــة العامــة بأبــو‬\n‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n‫برقــم ‪ 3427354‬وتاريــخ ‪1434/01/17‬ه ـ واملقيــدة باحملكمــة برقــم‬\n‫‪ 34129844‬وتاريــخ ‪ 1434/01/17‬ه ـ وقــد عــادت إلينــا املعاملــة مــن‬\n‫هيئــة التحقيــق واالدعــاء العــام ه ـ ج‪ 875/2/3‬وتاريــخ ‪1434/4/17‬ه ـ‬\n‫واملقيــدة لدينــا برقــم ‪ 34991160‬وتاريــخ ‪1434/4/22‬هـ عليه ففي هذا‬\n‫اليــوم الســبت املوافق‪1434/04/27‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة العاشــرة وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق واالدعــاء‬\n‫العــام ‪........‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪........‬واملفــوض‬\n‫باخلطــاب رقــم ‪........‬وتاريــخ ‪1429/11/3‬ه ـ وأدعــى قائــا بصفتــي‬\n‫مدعيــا عامــا يف دائــرة االدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى‬\n‫‪30........‬عامـ ًا ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم‪ ........‬مــودع‬\n‫بقســم ســجن أبــو عريــش مبوجــب أمر متديــد التوقيف واإلحالة رقــم‪........‬‬\n‫وتاريــخ ‪1433/11/8‬ه ـ اســتناد ًا للقــرار الــوزاري ‪ 1900‬ويعتبــر إيقافــه‬\n‫مــن تاريــخ القبــض عليــه أنــه يف متــام الســاعة الرابعــة والنصــف مــن صبــاح‬\n‫يــوم االثنــن املوافــق ‪1433/10/23‬ه ـ ورد بــاغ لشــرطة وادي جــازان‬\n‫عــن طريــق العمليــات يتضمــن وجــود شــخص مصــاب يدعــى ‪........‬إثــر‬\n‫تعرضــه للضــرب ب ــآلة حــادة فــأس مــن قبــل املدعــى عليــه وبإحالتــه‬\n‫ملستشــفى أبــو عريــش العــام صــدر بحقــه التقريــر الطبــي رقــم ‪........‬‬\n‫وتاريــخ ‪1433/10/ 24‬ه ـ املتضمــن هبــوط حــاد بالــدورة الدموية ونزيف‬\n‫شــديد كســور متعــدد بعظمــة الزنــد األيســر وقطــع بالعضــات وقطــع‬\n\n                                                                                      ‫‪36‬‬\n\f     ‫بالعصــب الزنــدي واألوســط وكســور متعــدد مبشــطيات اليــد اليســرى‬\n     ‫ومت التثبيــت باســتخدام أســياخ‪ ،‬وكســور متعــدد بعظمــة الزنــد األميــن‬\n     ‫وقطــع بالعصــب الوحشــي وقطــع متعــدد باألوتــار والعضــات ووضــع‬\n     ‫اليــد يف جبــس فــوق الكــوع أمــا بالنســبة لقطــع أعصــاب املريــض يحتــاج‬\n     ‫لدراســة توصيــل األعصــاب إلجــراء جراحــي يف مراحــل الحقــة بعــد‬\n     ‫التئــام اجلــروح وكســور متعــددة بالكاحــل األيســر وعظمــة الشــظية‬\n     ‫وعظمــة القصبــة اليســرى وقطــع بالعضــات ومت التثبيــت بواســطة‬\n     ‫أســياخ وتوصيــل العضــات وجــروح قطعيــة متعــددة بالســاق والفخــذ‬\n     ‫األميــن ومت إصــاح هــذه اجلــروح ومــدة الشــفاء ســتة أشــهر وبســماع‬\n     ‫أقــوال املجنــي عليــه أفــاد بــأن مــن قــام بضربــه هــو املدعــى عليــه أثــر‬\n     ‫خــاف بينــه وبــن زوجتــه أي أخــت املدعــى عليــه وباســتجواب املدعــى‬\n     ‫عليــه ومواجهتــه بالتهمــة املنســوبة إليــه أفــاد بأنــه ذهــب ملنــزل زوج أختــه‬\n     ‫‪........‬وقــام بإطفــاء الكهربــاء مــن عــداد الكهربــاء اخلارجــي ودخــل‬\n     ‫حــوش املنــزل وقــام بضــرب جــدار منــزل ‪........‬املذكــور بقطعــة بلــك‬\n     ‫حتــى اســتيقظ ‪........‬املذكــور وقــام بســؤال املجنــي عليــه عــن ســبب‬\n     ‫ضربــه ألختــه فقــال أنــه ال يريــد ضربهــا وإمنــا كان يريــد ضــرب ابنتــه‬\n     ‫‪........‬فقــال يريــد أخــذ حــق أختــه منــه وكان بيــده فــأس فقــام بضربــه‬\n     ‫بــه علــى اليــد اليمنــى ومــن ثــم اليســرى ومــن ثــم األقــدام وتركــه أمــام‬\n     ‫منزلــه ينــزف مــن الدمــاء وصــادق علــى إقــراره بذلــك شــرعا وقــد أســفر‬\n     ‫التحقيــق عــن توجيــه االتهــام للمدعــى عليــه بالشــروع يف قتــل زوج أختــه‬\n     ‫‪........‬وذلــك مــن خــال ضربــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n     ‫إصابتــه بعــدة إصابــات موصوفــة بالتقريــر الطبــي املرفــق وذلــك لألدلــة‬\n     ‫والقرائــن التاليــة‪ -1‬مــا جــاء يف إقــرار املصــادق عليــه شــرع ًا ص ‪ 5‬مــن‬\n\n\n‫‪37‬‬\n\f‫دفتــر التحقيــق املرفــق لفــة رقــم ‪2 .2‬ـ مــا جــاء يف محضــر القبــض املرفــق‬\n‫لفــة رقــم ‪3 .4‬ـ مــا جــاء بالتقريــر الطبــي املرفــق لفــة رقــم ‪ 49‬وبالبحــث‬\n‫عــن ســوابقه عثــر لــه علــى ســابقة مضاربــة وحيــث أن مــا أقــدم عليــه‬\n‫املدعــى عليــه فعــل محــرم ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا‬\n‫أســند إليــه واحلكــم بعقوبــة تعزيريــة مشــددة تزجــره وتــردع غيــره علم ــا‬\n‫بــأن احلــق اخلــاص مــازال قائمــا وبعــرض دعــوى املدعي العــام على املدعى‬\n‫عليــه بعــد التأكــد مــن هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا‬\n‫ذكــره املدعــي العــام مــن قيامــي بالشــروع يف قتــل زوج أختــي ‪........‬‬\n‫وذلــك مــن خــال ضربــي لــه بفــأس يف أطرافــه األربعــة ممــا تســبب يف‬\n‫إصابتــه بعــدة إصابــات املوصوفــة يف دعــوى املدعــي العــام كلــه صحيــح‬\n‫وذلــك بعــد أن حضــر أحــد أفــراد القريــة وأخبرنــي أن ‪........‬قتــل أختــي‬\n‫مبطرقــة وأخذهــا اإلســعاف هكــذا أجــاب عقــب ذلــك جــرى االطــاع‬\n‫علــى التقريــر الطبــي رقــم ‪........‬وتاريــخ ‪1433/10/ 24‬ه ـ واملتضمــن‬\n‫هبــوط حــاد بالــدورة الدمويــة ونزيــف شــديد‪ ،‬كســور متعــدد بعظمــة‬\n‫الزنــد األيســر وقطــع بالعضــات وقطــع بالعصــب الزنــدي واألوســط‬\n‫وكســور متعــدد مبشــطيات اليــد اليســرى ومت التثبيــت باســتخدام‬\n‫أســياخ وكســور متعــدد بعظمــة الزنــد األميــن وقطــع بالعصــب الوحشــي‬\n‫وقطــع متعــدد باألوتــار والعضــات ووضــع اليــد يف جبــس فــوق الكــوع‬\n‫أمــا بالنســبة لقطــع أعصــاب املريــض يحتــاج لدراســة توصيــل األعصــاب‬\n‫إلجــراء جراحــي يف مراحــل الحقــة بعــد التئــام اجلــروح وكســور متعــددة‬\n‫بالكاحــل األيســر وعظمــة الشــظية وعظمــة القصبــة اليســرى وقطــع‬\n‫بالعضــات ومت التثبيــت بواســطة أســياخ وتوصيــل العضــات وجــروح‬\n‫قطعيــة متعــددة بالســاق والفخــذ األميــن ومت إصــاح هــذه اجلــروح ومــدة‬\n\n\n                                                                                    ‫‪38‬‬\n\f     ‫الشــفاء ســتة أشــهر عقــب ذلــك جــرى االطــاع علــى كــرت ســوابق‬\n     ‫املدعــى عليــه املرفــق لفــة رقــم ‪ 17‬فوجــدت بــه ســابقة اعتــداء كمــا‬\n     ‫جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه املرفقــة لفــة رقــم‬\n     ‫‪ 14‬فوجــدت أنــه أوقــف بتاريــخ ‪1433/10/23‬ه ـ فبنــاء علــى مــا تقــدم‬\n     ‫مــن الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم املدعــى عليــه بقيامــه‬\n     ‫بالشــروع يف قتــل زوج أختــه ‪........‬وذلــك مــن خــال ضربــه بفــأس يف‬\n     ‫أطرافــه األربعــة ممــا تســبب يف إصابتــه بعــدة إصابــات موصوفــة يف‬\n     ‫دعــواه ومبــا أن املدعــي صــادق علــى دعــوى املدعــي العــام ومبــا أنــه‬\n     ‫جــرى االطــاع علــى التقريــر الطبــي املــدون مضمونــه بعاليــه ومبــا أن‬\n     ‫الشــريعة اإلســامية حرصــت علــى حفــظ النفــس وصيانتهــا وحمايتهــا‬\n     ‫مــن االعتــداء عليهــا وجتنيبهــا األضــرار التــي تفتــك بهــا ووضعــت كافــة‬\n     ‫الوســائل املؤديــة إلــى احملافظــة عليهــا قــال تعالــى وال تقتلــوا النفــس التــي‬\n     ‫حــرم اهلل إال باحلــق وحــرم النبــي صلــى اهلل عليــه وســلم تخويــف املســلم‬\n     ‫وترويعــه قــال عليــه الصــاة والســام مــن أخــاف مؤمنــا كان حــق علــى‬\n     ‫اهلل أال يؤمنــه مــن أفــزاع يــوم القيامــة ونهــى النبــي صلــى اهلل عليــه وســلم‬\n     ‫عــن اإلشــارة بالســاح وقــال مــن أشــار إلــى أخيــه بحديــدة فــإن املالئكــة‬\n     ‫تلعنــه حتــى يدعــه وإن كان أخــاه ألبيــه وأمــه رواه مســلم لذلــك كلــه‬\n     ‫وألجــل احلــق العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه‬\n     ‫بقيامــه بالشــروع يف قتــل زوج أختــه ‪........‬وذلــك مــن خــال ضربــه بفــأس‬\n     ‫يف أطرافــه األربعــة ممــا تســبب يف إصابتــه بعــدة إصابــات ثانيــا يعــزر‬\n     ‫املدعــى عليــه بالســجن ملــدة أربــع ســنوات مــن تاريــخ إيقافــه علــى ذمــة‬\n     ‫هــذه القضيــة وجلــده ثمامنائــة جلــدة مفرقــة علــى ســتة عشــر دفعــة كل‬\n     ‫دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيام‬\n\n\n‫‪39‬‬\n\f‫علــى أن يكــون اجللــد علنــا وبــه حكمــت وبعــرض احلكــم علــى املدعــى‬\n‫عليــه قــرر القناعــة وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون‬\n‫الئحــة اعتراضيــة عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة‬\n‫االســتئناف لتدقيــق احلكــم وحتــى ال يخفــى جــرى تدوينــه وأقفلــت‬\n‫اجللســة يف متــام الســاعة العاشــرة والنصــف وبــاهلل التوفيــق وصلــى اهلل‬\n‫علــى نبينــا محمــد وعلــى آلــه وصحبــه وســلم حــرر يف ‪1434/4/27‬ه ـ‬\n‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الرابعــة لتدقيــق‬\n‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n‫الــواردة مــن فضيلــة القائــم بعمــل رئيــس احملكمــة العامــة بأبــي عريــش‬\n‫الشــيخ ‪........ /‬برقــم ‪ 34991160‬وتاريــخ ‪1434 /4/29‬ه ـ املرفــق بهــا‬\n‫القرار الصادر من فضيلـته برقم ‪ 34198838‬وتاريخ ‪1434/4/27‬هـ‬\n‫اخلــاص بدعــوى املدعــي العــام ضـ ــد ‪................ /‬يف قضيــة ( الشــروع‬\n‫يف قتــل زوج أختــه ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه وبدراســة القــرار وصــورة ضبطــه‬\n‫وأوراق املعاملــة تقــررت املوافقــة علــى احلكــم واهلل املوفــق وصلــى اهلل‬\n                                   ‫علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n                                                                                     ‫‪40‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":34,"source_page_end":40,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"3a184175fc5bd5d06847f4c3c1d54f628f46ed92fba10586f23137f4c0d2a431","normalized_text_hash":"b226ab59901eda50526b8223bfe0db8d69c3abfda9e54b43b423660174bd6727","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p34-34198838"},{"id":"8be86e7a-5f02-5ab0-89b2-397b533e7022","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -طعن -طعن بسكني «ساح أبيض» ،انتهاك حرمة املنزل -إحداث إصابات -ثبوت اإلدانة -تعزير بالسجن واجللد.","document_number":"3451474","case_number":"3437318","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/3/1","year":"1434","subject":"اعتداء -طعن -طعن بسكني «ساح أبيض» ،انتهاك حرمة املنزل -إحداث إصابات -ثبوت اإلدانة -تعزير بالسجن واجللد.","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"       ‫رقم الصك ‪ 3451474 :‬تاريخه‪1434/3/1 :‬هـ‬\n                          ‫رقم الدعوى‪3437318:‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34174738‬تاريخه‪1434/03/29 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬طعــن ‪ -‬طعــن بســكني «ســاح أبيــض» ‪ ،‬انتهــاك حرمــة املنــزل‬\n                  ‫‪ -‬إحــداث إصابــات ‪ -‬ثبــوت اإلدانــة ‪ -‬تعزيــر بالســجن واجللــد‪.‬‬\n\n\n\n\n     ‫‪-‬قولــه صلــى اهلل عليــه وســلم ( ال يشــير أحدكــم إلــى أخيــه بالســاح‬\n     ‫فإنــه ال يــدري أحدكــم لعــل الشــيطان ينــزع يف يــده فيقــع يف حفــرة‬\n                                                                   ‫مــن النــار)‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه لقيامــه بدخــول منــزل املجنــي عليــه‬\n     ‫عنــو ًة وطعنــه بســكني ممــا تســبب يف إصابتــه وطلــب إدانتــه وتعزيــره‬\n     ‫شــرعا لدخــول املدعــى عليــه ملنــزل املجنــي عليــه وحمله ســكني ( ســاح‬\n     ‫أبيــض ) ومفتــاح كفــر ممــا تســبب يف إصابتــه بجــرح يف يــده وقــدم‬\n     ‫املجنــي عليــه تقريــر ًا طبيـ ًا تأييــد ًا لدعــواه ‪ ،‬كمــا أقــر املدعــى عليه مبا‬\n     ‫جــاء يف الدعــوى ‪ ،‬أديــن املدعــى عليــه وحكــم عليــه بالســجن ملــدة أربعــة‬\n     ‫أشــهر اعتبــار ًا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة وبجلــده مائــة‬\n     ‫وخمســن جلــدة مفرقــه علــى دفعــات‪ ،‬قــرر املدعــي العــام االعتــراض‬\n     ‫وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه القناعــة ‪ ،‬صــدق‬\n                                              ‫احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n‫‪41‬‬\n\f‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪........‬القاضــي يف احملكمــة العامــة‬\n‫ـاء علــى املعاملــة احملالــة لنــا من فضيلــة رئيس احملكمة‬    ‫بأبــي عريــش وبنـ ً‬\n‫العامــة بأبــي عريــش برقــم ‪ 3437318‬وتاريخ‪1434/01/21‬ه ـ املقيــدة‬\n‫باحملكمــة برقــم ‪ 34156823‬وتاريــخ ‪1434/01/19‬ه ـ ففــي يــوم‬\n‫األربعــاء املوافق‪1434/02/20‬ه ـ افتتحــت اجللســة األولــى يف متــام‬\n‫الســاعة ‪ 08 : 30‬وفيهــا حضــر املدعــي العــام ‪ ....‬ســعودي اجلنســية‬\n‫مبوجــب الســجل املدنــي رقــم ‪ .....‬مبوجــب تكليفــه باخلطــاب برقم هـ‪7‬جـ‬\n‫‪ 513/10/‬وتاريــخ ‪1429/11/3‬ه ـ الصــادر مــن دائــرة التحقيــق وحضــر‬\n‫حلضــوره ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬وبســؤال‬\n‫ا بصفتــي مدعي ـ ًا عام ـ ًا بدائــرة‬    ‫املدعــي العــام عــن دعــواه أجــاب قائ ـ ً‬\n‫التحقيــق واالدعــاء العــام مبحافظــة أبــو عريــش أدعــي علــى ‪ ...‬البالــغ‬\n‫ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪ ....‬البالــغ مــن العمــر اثنــان‬\n‫وعشــرون عام ـ ًا أوقــف مبوجــب أمــر التوقيــف رقــم ه ـ ج‪3383/2/2‬‬\n‫وتاريــخ ‪1433/11/24‬ه ـ ومــودوع بســحن أبــو عريــش مبوجــب أمــر‬\n‫التمديــد واإلحالــة رقــم ه ـ ‪ 2‬ج‪ 3429/2/‬وتاريــخ ‪1433/11/28‬ه ـ‬\n‫حيــث إنــه بتاريــخ ‪1433/11/23‬ه ـ تقــدم كل مــن املواطــن ‪ ....‬ســعودي‬\n‫اجلنســية و املواطــن ‪ ....‬ســعودي اجلنســية بدعــوى مفادهــا قيــام املدعــى‬\n‫عليــه أعــاه باالعتــداء عليهمــا بالضــرب وبســماع إفادة املدعــن أفادا أن‬\n‫املدعــى عليــه أعــاه قــد حضــر ملنــزل ‪ ....‬وقــام بدخــول احلــوش والتهجــم‬\n‫عليهمــا وكان يحمــل معــه ســكني ( ســاح أبيــض ) ومفتــاح كفــر ممــا‬\n‫تســبب يف إصابــة أحدهمــا بجــرح يف يــده وباســتجواب املدعــى عليــه أقــر‬\n\n                                                                                        ‫‪42‬‬\n\f     ‫بدخولــه ملنــزل املدعــو ‪ ....‬وهــو يريــد ‪ ....‬كونــه يطلبــه مبلــغ مــن املــال‬\n     ‫كمــا أقــر بقيامــه بطعــن ‪ ....‬بالســكني وصــادق علــى إقــراره حتقيق ـ ًا‬\n     ‫وقــد أفــرز التحقيــق عــن توجبيــه االتهــام ل‪ ...‬بقيامــه بالتهجــم علــى منــزل‬\n     ‫‪ ...‬والدخــول للحــوش وطعنــه بســكني ممــا تســبب يف إصابتــه وذلــك‬\n     ‫لألدلــة و القرائــن التاليــة ‪-1:‬ماجــاء بأقــوال املدعــى عليــه املدونــة ص‬\n     ‫‪ 2 1‬بدفتــر التحقيــق املرفــق لفــه رقــم ‪-2 14‬ماجــاء يف التقريــر الطبــي‬\n     ‫املرفــق لفــه رقــم ‪ 6‬ورقــم ‪ 4‬وبالبحــث عــن ســوابقه لــم يعثــر لــه علــى‬\n     ‫ســوابق مســجله وحيــث أن مــا أقــدم عليــه املتهــم املذكــور فعــل محــرم‬\n     ‫ومعاقــب عليــه شــرع ًا لــذا أطلــب إثبــات مــا نســب إليــه واحلكــم بتعزيــره‬\n     ‫شــرع ًا علمــا بــأن احلــق مــازال قائمـ ًا هــذه دعــواي وبعــرض دعــوى املدعــي‬\n     ‫العــام علــى املدعــى عليــه أجــاب بقولــه مــا جــاء يف دعــوى املدعــي العــام‬\n     ‫صحيــح جملــة و تفصيــا هكــذا أجــاب ثــم جــرى االطــاع علــى التقريــر‬\n     ‫الطبــي بــدون رقــم و تاريــخ ‪1433/11/23‬ه ـ الصادر من مستشــفى ‪.......‬‬\n     ‫ب ـ ‪ ....‬والــذي جــاء فيــه توجــد كدمــات يف الذراعــن والركبتــن ومــدة‬\n     ‫الشــفاء خمســة أيــام وجــرى االطــاع علــى التقريــر الطبــي بــدون رقــم‬\n     ‫وتاريــخ ‪1433/11/23‬ه ـ اخلــاص ب ـ ‪ ....‬والــذي جــاء فيــه جــرح قطعــي‬\n     ‫علــى ظهــر اليــد اليســرى بطــول ثالثــة ونصــف يف خمســة ســم متــة خياطته‬\n     ‫بســبع غــرزات ومــدة الشــفاء ســبعة أيــام ثــم جــرى االطــاع علــى صحيفــة‬\n     ‫ســوابقه املوضــح بهــا عــدم وجــود ســوابق عليــه وجــرى االطــاع علــى‬\n     ‫مذكــرة إيقافــه حيــث كان إيقافــه بتاريــخ ‪1433/11/23‬ه ـ ثــم جــرى‬\n     ‫قفــل بــاب املرافعــة فبعــد مــا تقــدم مــن الدعــوى واإلجابــة واالطــاع علــى‬\n     ‫أوراق املعاملــة وحيــث أن املدعــى عليــه أقــر وصــادق علــى دعــوى املدعــي‬\n     ‫العــام وحيــث أن مــا أقــدم عليــه املدعــي عليــه فعــل محــرم شــرع ًا لقولــه‬\n\n\n‫‪43‬‬\n\f‫صلــى اهلل عليــه وســلم ( ال يشــير أحدكــم إلــى أخيــه بالســاح فإنــه ال‬\n‫يــدري أحدكــم لعــل الشــيطان ينــزع يف يــده فيقــع يف حفــرة مــن النــار)‬\n‫وبنــاء علــى ذلــك كلــه فقــد ثبــت لــدي إدانــة املدعــى عليــه بإقــراره مبــا‬\n‫أســند إليــه وحكمــت عليــه تعزيــر ًا للحــق العــام مبــا يلــي ‪ :‬أو ًال ســجنه‬\n‫ملــدة أربعــة أشــهر اعتبــار ًا مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة ثانيـ ًا‬\n‫جلــده مائــة وخمســون جلــدة مفرقــه علــى دفعــات كل دفعــة خمســون‬\n‫جلــده بــن كل دفعــه وأخــرى عشــرة أيــام وبعــرض احلكــم علــى املدعــى‬\n‫عليــه قــرر القناعــة وقــرر املدعــي العــام االعتــراض وطلــب رفعه حملكمة‬\n‫االســتئناف بعســير بــدون الئحــة اعتراضيــة فأجبتــه إلــى طلبــه وقــررت‬\n‫رفعهــا حملكمــة االســتئناف بعســير وبــاهلل التوفيــق وأقفلــت اجللســة يف‬\n‫متــام الســاعة الثامنــة والنصــف وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                ‫وصحبــه وســلم ‪ .‬حــرر يف ‪ 1434/02/20‬هــ‪.‬‬\n‫احلمــد هلل وحــده وبعــد فقــد مت دراســة الصــك وصــورة ضبطــه و اوراق‬\n‫املعاملــة مــن محكمــة االســتئناف مبنطقــة عســير ومتــت املصادقــة علــى‬\n                                                                               ‫احلكــم ‪.‬‬\n\n\n\n\n                                                                                              ‫‪44‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":41,"source_page_end":44,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"367c09363d433e65c16fe0929d0a5478fa75d635fb57c41556adbc531d542c67","normalized_text_hash":"fa4010d52f2ccc78d8e7a8817118c5edaaea196f7567a6a7e1f53b662be5f27d","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p41-3451474"},{"id":"cf93ca2d-435a-54b5-990a-8a12d328a6d2","document_type":"judgment","category":"judicial","subcategory":"general","title":"اعتداء -طعن -طعن بسكني -إحداث إصابة بحجة الدفاع عن النفس -عدم ثبوت الدفاع عن النفس -ثبوت إدانة -التعزير بالسجن واجللد .","document_number":"3425051","case_number":"3440377","judgment_number":null,"decision_number":null,"circular_number":null,"court":"المحكمة العامة بأبو عريش","circuit":null,"issuing_authority":"وزارة العدل السعودية","document_date":null,"hijri_date":"1434/01/27","year":"1434","subject":"اعتداء -طعن -طعن بسكني -إحداث إصابة بحجة الدفاع عن النفس -عدم ثبوت الدفاع عن النفس -ثبوت إدانة -التعزير بالسجن واجللد .","summary":null,"facts":null,"claims":null,"reasoning":null,"ruling":null,"principle_text":null,"full_text":"     ‫رقم الصك ‪ 3425051 :‬تاريخه‪1434/01/27 :‬هـ‬\n                          ‫رقم الدعوى‪3440377 :‬‬\n          ‫رقم قرار التصديق من محكمة االستئناف‪:‬‬\n               ‫‪ 34424707‬تاريخه‪1434/2/20 :‬هـ‬\n\n\n\n     ‫اعتــداء ‪ -‬طعــن ‪ -‬طعــن بســكني ‪ -‬إحــداث إصابــة بحجــة الدفــاع عــن‬\n     ‫النفــس ‪ -‬عــدم ثبــوت الدفــاع عــن النفــس ‪ -‬ثبــوت إدانــة ‪ -‬التعزيــر‬\n                                                         ‫بالســجن واجللــد ‪.‬‬\n\n\n\n\n                    ‫‪ -‬قول اهلل تعالى ‪( :‬وال تعتدوا إن اهلل ال يحب املعتدين ) ‪.‬‬\n     ‫‪ -‬قــول النبــي صلــى اهلل عليــه وســلم‪( :‬املســلم مــن ســلم املســلمون مــن‬\n     ‫لســانه ويــده )وقــال النبــي صلــى اهلل عليــه وســلم (مــن أشــار إلــى أخيــه‬\n     ‫بحديــده فــإن املالئكــة تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه )‪.‬‬\n                                    ‫‪ -‬املادة ‪ 152‬من نظام اإلجراءات اجلزائية ‪.‬‬\n\n\n\n\n     ‫اتهــام املدعــي العــام للمدعــى عليــه بقيامــه بطعــن املجنــي عليــه يف‬\n     ‫صــدره اجلهــة اليســرى بآلــة حــادة وطلــب إدانتــه وتعزيــره شــرعا إذ أنــه‬\n     ‫تبلــغ مركــز الشــرطة مــن املستشــفى عــن وجــود شــخص مصــاب لديهــم‬\n     ‫بطعــن ‪ ،‬وقــد جــرى االنتقــال ملوقــع احلادثــة وأفــاد املجنــي عليــه أنــه أثنــاء‬\n     ‫ســيره علــى األقــدام يرافقــه اثنــان مــن أصدقائــه ‪ ،‬تعــرض لــه املدعــى‬\n     ‫عليــه بطعنــه بســكني يف اجلهــة اليســرى مــن الصــدر ‪ ،‬وال يعلــم عــن‬\n         ‫ســبب قيــام املدعــى عليــه بطعنــه وال توجــد بينــه وبــن املدعــى عليــه‬\n\n‫‪45‬‬\n\f‫أيــة مشــاكل مــن الســابق ‪ ،‬وقــد صــدر بحقــه التقريــر الطبــي واملتضمن‬\n‫إصابتــه بطعنــة يف الصــدر األيســر علــى مســتوى الضلــع الســادس يف‬\n‫اجلهــة األماميــة ومــدة الشــفاء شــهر‪ ،‬أقــر املدعــى عليــه مبــا جــاء يف‬\n‫الدعــوى ودفــع بأنــه أراد الدفــاع عــن نفســه وال بينــة لــه علــى أن املجنــي‬\n                            ‫عليــه قــام مبهاجمتــه قــررت احملكمــة مــا يلــي ‪:‬‬\n‫أوالً‪ :‬ثبــت إدانــة املدعــى عليــه وحكــم عليــه ‪ ،‬بالســجن مــدة أربعــة‬\n‫أشــهر مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة ‪ ،‬بجلــد املدعــى عليــه‬\n‫مائتــان وخمســون جلــدة مفرقــة علــى خمــس دفعــات كل دفعــة خمســون‬\n‫جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل عــن عشــرة أيــام ‪ ،‬قــرر املدعــي‬\n‫العــام االعتــراض وطلــب االســتئناف بــدون الئحــة وقــرر املدعــى عليــه‬\n                        ‫القناعة‪،‬صــدق احلكــم مــن محكمــة االســتئناف‪.‬‬\n\n\n\n\n                                                                                     ‫‪46‬‬\n\f     ‫احلمــد هلل وحــده وبعــد فلــدي أنــا ‪ ....‬القاضــي باحملكمــة العامــة بأبــو‬\n     ‫عريــش وبنــاء علــى املعاملــة احملالــة لنــا مــن فضيلــة رئيــس احملكمــة‬\n     ‫العامــة بأبــو عريــش برقــم ‪ 3440377‬وتاريــخ ‪ 1434/01/24‬ه ـ املقيــدة‬\n     ‫باحملكمة برقم ‪ 34185872‬وتاريخ ‪ 1434/01/21‬هـ ففي هذا اليوم‬\n     ‫الثالثــاء املوافــق ‪1433/1/27‬ه ـ افتتحــت اجللســة األولــى يف متام الســاعة‬\n     ‫احلاديــة عشــر و النصــف وفيهــا حضــر املدعــي العــام بدائــرة التحقيــق‬\n     ‫واالدعــاء العــام ‪ ....‬ســعودي اجلنســية مبوجــب الســجل املدنــي رقــم ‪.....‬‬\n     ‫املفــوض باخلطــاب رقــم هــ‪7‬ج‪ 513/‬وتاريــخ ‪1428/7/9‬ه ـ وأدعــى قائــا‬\n     ‫بصفتــي مدعيــا عامــا يف دائــرة التحقيــق واالدعــاء العــام مبحافظــة أبــو‬\n     ‫عريــش أدعــي علــى ‪ 19 ....‬عامــا مينــي اجلنســية مبوجــب البطاقــة البديلــة‬\n     ‫رقــم ‪......‬ع ض وتاريــخ ‪1434/1/5‬ه ـ مــودع بقســم ســجن أبــو عريــش‬\n     ‫كــون جرميتــه مــن اجلرائــم املوجبــة للتوقيــف اســتنادا للقــرار الــوزاري‬\n     ‫رقــم ‪ 1900‬وتاريــخ ‪1428/8/9‬ه ـ إنــه يف متــام الســاعة الثامنــة والنصــف‬\n     ‫مــن مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ تبلــغ مركــز شــرطة‬\n     ‫‪ ......‬مــن قبــل مستشــفى ‪ .........‬عــن وجــود شــخص مصــاب لديهــم بطعــن‬\n     ‫وقــد جــرى االنتقــال ملوقــع احلادثــة الــذي يقــع شــرق محافظــة ‪ ......‬بحوالي‬\n     ‫خمســن كيلــو متــر علــى اخلــط الدائــري رفــق األدلــة اجلنائيــة ومت‬\n     ‫إكمــال الــازم حيــال املعاينــة وبضبــط إفــادة املجنــي عليــه ‪ ....‬والــذي‬\n     ‫أفــاد أنــه يف مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ وعنــد الســاعة‬\n     ‫الثامنــة وأثنــاء ســيره علــى األقــدام علــى اخلــط الدائــري ‪ ........‬وبالتحديــد‬\n     ‫غــرب ‪ .........‬وكان يرافقــه كال مــن ‪ ...‬واملدعــو ‪ ....‬مــن أجــل املشــي‬\n\n‫‪47‬‬\n\f‫الرياضــي عندهــا تعــرض لــه املدعــى عليــه بطعنــه بســكني يف اجلهــة‬\n‫اليســرى مــن الصــدر وال يعلــم عــن ســبب قيــام املدعــى عليــه بطعنــه وال‬\n‫توجــد بينــه وبــن املدعــى عليــه أي مشــاكل مــن الســابق وقــد صــدر‬\n‫بحقــه التقريــر الطبــي رقــم ‪ 23623‬وتاريــخ ‪1433/11/9‬ه ـ واملتضمــن‬\n‫إصابتــه بطعنــه يف الصــدر األيســر علــى مســتوى الضلــع الســادس يف‬\n‫اجلهــة األماميــة ومــدة الشــفاء شــهر وبضبــط شــهادة الشــهود أفــاد كال‬\n‫مــن ‪ ...‬و‪....‬أنهمــا يف مســاء يــوم الســبت املوافــق ‪1433/10/21‬ه ـ كانــا‬\n‫برفقــة املجنــي عليــه ‪ ....‬وكانــوا يســيرون مشــيا علــى األقــدام رياضــة‬\n‫علــى خــط ‪ .......‬ومــع أذان العشــاء توقفــوا للصــاة وبعدهــا شــاهدوا‬\n‫شــخص واقــف بجوارهــم فذهــب املجنــي عليــه ‪ ...‬للتفاهــم معــه وحــال‬\n‫وصولــه إليــه قــام املدعــى عليــه بطعــن املجنــي عليــه بســكني وبعدهــا‬\n‫قــام الشــاهدان بإمســاك املدعــى عليــه وتســليمه للشــرطة وباســتجواب‬\n‫املدعــى عليــه ومواجهتــه بالتهمــة املنســوبة إليــه والــذي أفــاد أنــه يف مســاء‬\n‫يــوم الســبت املوافــق ‪1433/10/21‬ه ـ حوالــي الســاعة الثامنــة جلــس‬\n‫علــى اخلــط الدائــري لوحــده ولــم يكــن يرافقــه أي أحــد وكان الشــارع‬\n‫مظلــم وأثنــاء جلوســه غــرب قرية‪.......‬عندهــا حضــر لــه ثالثــة أشــخاص‬\n‫ولــم يشــعر بهــم إال وقــت قيامهــم بالهجــوم عليــه وعندهــا قــام مفــزوع وال‬\n‫يعلــم مــن األشــخاص وعنــد حضــور أحــد األشــخاص إليــه قــام بطعنــه‬\n‫بســكني يف صــدره مــن اجلهــة اليســرى أســفل الثــدي بعدهــا قــام برمــي‬\n‫الســكني يف مــكان بعيــد وعندهــا حضــر مرافقــي الشــخص االثنــن‬\n‫اآلخريــن وقامــوا بإمســاكه وتربيطــه وقــام املدعــو ‪ ....‬بإمســاكه‬\n‫واآلخــر ال يعــرف اســمه قــام بضربــه بعصــا وذلــك بعــد أن قــام بطعــن‬\n‫صاحبهــم األول والــذي اتضــح أنــه بعــد فــك اللثــام أنــه املدعــو ‪ ...‬وقــد‬\n\n\n                                                                                        ‫‪48‬‬\n\f     ‫كانــوا يلبســون مالبــس ســوداء جميعهــم الثالثــة وبعــد املشــكلة أفــادوه‬\n     ‫بأنهــم ميزحــون معــه وقــد أحضــروا ســيارة وأخــذوا املطعــون إلســعافه‬\n     ‫وأنــه املتســبب يف إصابــة ‪ ....‬وذلــك بطعنــه بالســاح األبيــض الســكني‬\n     ‫وأن اإلصابــات التــي كانــت بــه مــن مرافقــي ‪ ...‬املذكــور وأنــه ليــس‬\n     ‫بينــه وبــن ‪ ...‬أي مشــاكل مــن الســابق وأن قيامــه بطعــن املدعــي هــو‬\n     ‫دفــاع عــن نفســه أثنــاء هجومهــم عليــه يف موقــع مظلــم وقــد صــدر بحقــه‬\n     ‫التقريــر الطبــي مــن املستشــفى واملتضمــن إصابتــه يف اجلانــب األيســر‬\n     ‫مــن البطــن واجلانــب الســفلي مــن الصــدر ومــدة الشــفاء ثالثــة أيــام وقــد‬\n     ‫أســفر التحقيــق عــن توجيــه االتهــام إليــه بطعن املدعــو ‪ ....‬يف صدره اجلهة‬\n     ‫اليســرى بآلــة حــادة أثنــاء ســيره علــى اخلــط الدائــري قــرب قريــة‪.......‬‬\n     ‫وذلــك لألدلــة والقرائــن التاليــة ‪1‬ـ إقــراره حتقيقــا املنــوه عنــه املــدون ص‬\n     ‫‪ 6‬مــن ملــف التحقيــق املرفــق لفــة رقــم ‪2 .1‬ـ مــا جــاء بشــهادة الشــهود‬\n     ‫املنــوه عنهــا ص ‪ 6‬مــن ملــف التحقيــق لفــة رقــم ‪3 .1‬ـ التقريــر الطبــي‬\n     ‫الصــادر مــن مستشــفى ‪ .................‬املرفــق لفــة رقــم ‪4 .12‬ـ محضــر‬\n     ‫االنتقــال واملعاينــة املنــوه عنــه املــدون ص ‪ 8‬مــن دفتــر التحقيــق املرفــق‬\n     ‫لفــة رقــم ‪ .1‬و بالبحــث عــن ســوابقه لــم يعثــر لــه علــى ســابقة حتــى تاريخه‬\n     ‫وحيــث إن مــا أقــدم عليــه املدعــى عليــه فعــل محــرم شــرعا ومعاقــب عليــه‬\n     ‫لــذا أطلــب إثبــات مــا أســند إليــه واحلكــم عليــه بعقوبــة تعزيريــة تزجــره‬\n     ‫وتــردع غيــره علمــا بــأن احلقــوق اخلاصــة مازالــت قائمــة واهلل املوفــق‬\n     ‫وبعــرض دعــوى املدعــي العــام علــى املدعــى عليــه بعــد التأكــد مــن‬\n     ‫هويتــه وأهليتــه املعتبــرة شــرعا أجــاب قائــا مــا ذكــره املدعــي العــام مــن‬\n     ‫قيامــي بطعــن املدعــو ‪ ....‬يف صــدره اجلهــة اليســرى بآلــة حــادة فصحيــح‬\n     ‫فقــد حضــر أثنــاء جلوســي بالطــرق الدائــري ثالثــة شــباب ال أعرفهــم‬\n\n\n‫‪49‬‬\n\f‫كونهــم كانــوا ملثمــن وقــام أحدهــم بإمســاكي مــن جهــة اليمــن‬\n‫واآلخــر بإمســاكي مــن جهــة اليســار واألخيــر مــن اخللــف بعدهــا قمــت‬\n‫بإخــراج ســكني كانــت معــي وطعنــت الشــخص املمســك بــي مــن اجلهــة‬\n‫اليمنــى ولــم أعــرف الشــخص املطعــون إال يف املستشــفى هكــذا أجــاب‬\n‫عقــب ذلــك ســألت املدعــى عليــه هــل لديــك بينــه علــى أن الشــباب الثالثــة‬\n‫قامــوا بالتهجــم عليــك واإلمســاك بــك أجــاب قائــا ال بينــة لــي كونــه‬\n‫لــم يكــن أحــد ســوانا وكان املــكان مظلــم هكــذا أجــاب عقــب ذلــك‬\n‫جــرى االطــاع علــى التقريــر الطبــي الصــادر مــن مستشــفى ‪.................‬‬\n‫بجــازان رقــم ‪ 23623‬وتاريــخ ‪1433/11/9‬ه ـ واملتضمــن تدمــي صــدر‬\n‫األيســر مــع ريــح صدريــة يســرى مــع أنبــوب صــدر أيســر ومــدة العــاج يف‬\n‫املستشــفى أســبوعني ومــدة الشــفاء حوالــي شــهر كمــا جــرى االطــاع‬\n‫علــى كــرت ســوابق املدعــى عليــه املرفــق لفــة رقــم ‪ 6‬فوجدتــه خاليــا‬\n‫مــن الســوابق كمــا جــرى االطــاع علــى مذكــرة إيقــاف املدعــى عليــه‬\n         ‫املرفقــة لفــة رقــم ‪ 8‬فوجــدت أنــه أوقــف بتاريــخ ‪1433/10/21‬ه ـ‬\n‫فبنــاء علــى مــا تقــدم مــن الدعــوى واإلجابــة ومبــا أن املدعــي العــام يتهــم‬\n‫املدعــى عليــه بطعــن املدعــو ‪ ....‬يف صــدره اجلهــة اليســرى بآلــة حــادة ومبــا‬\n‫أن املدعــى عليــه صــادق علــى دعــوى املدعــي العــام وادعــى أن مجموعــة‬\n‫مــن الشــباب وكان مــن بينهــم املجنــي عليــه قامــوا باالعتــداء عليــه ومبــا‬\n‫أنــه طلــب مــن املدعــى عليــه البينــة وال بينــة لــه علــى ذلــك ولعمــوم قولــه‬\n‫تعالــى (وال تعتــدوا إن اهلل ال يحــب املعتديــن)‪ .‬وقــول النبــي صلــى اهلل‬\n‫عليــه وســلم املســلم مــن ســلم( املســلمون مــن لســانه ويــده )وقــال النبــي‬\n‫صلــى اهلل عليــه وســلم (مــن أشــار إلــى أخيــه بحديــده فــإن املالئكــة‬\n‫تلعنــه حتــى يدعهــا وإن كان أخــاه ألبيــه وأمــه) لذلــك كلــه وألجــل احلــق‬\n\n\n                                                                                        ‫‪50‬‬\n\f     ‫العــام فقــد قــررت مــا يلــي أوال ثبــت لــدي إدانــة املدعــى عليــه ‪ ....‬بطعــن‬\n     ‫املدعــو ‪ ...‬يف صــدره اجلهــة اليســرى بآلــة حــادة ثانيــا يعــزر املدعــى عليــه‬\n     ‫بالســجن مــدة أربعــة أشــهر مــن تاريــخ إيقافــه علــى ذمــة هــذه القضيــة‬\n     ‫ثالثــا يجلــد املدعــى عليــه مائتــان وخمســون جلــدة مفرقــة علــى خمــس‬\n     ‫دفعــات كل دفعــة خمســون جلــدة بــن كل دفعــة وأخــرى مــدة ال تقــل‬\n     ‫عــن عشــرة أيــام وبعــرض احلكــم علــى املدعــى عليــه قــرر القناعــة بــه‬\n     ‫وقــرر املدعــي العــام االعتــراض علــى احلكــم بــدون الئحــة اعتراضيــة‬\n     ‫عليــه أمــرت برفــع كامــل أوراق املعاملــة حملكمــة االســتئناف لتدقيــق‬\n     ‫احلكــم وحتــى ال يخفــى جــرى تدوينــه وأقفلــت اجللســة يف متــام الســاعة‬\n     ‫الثانيــة عشــر وبــاهلل التوفيــق وصلــى اهلل علــى نبينــا محمــد وعلــى آلــه‬\n                                              ‫وصحبــه وســلم حــرر يف ‪1434/1/27‬ه ـ‬\n     ‫احلمــد هلل وحــده وبعــد فقــد اطلعنــا نحــن قضــاة الدائــرة الثالثــة لتدقيــق‬\n     ‫القضايــا اجلزائيــة مبحكمــة االســتئناف مبنطقــة عســير علــى املعاملــة‬\n     ‫الــواردة مــن فضيلــة رئيــس احملكمــة العامــة بأبي عريــش املكلف برقم‬\n     ‫‪ 34558265‬وتاريــخ ‪1434 / 4/1‬ه ـ املرفــق بهــا القــرار الصــادر مــن‬\n     ‫فضيل ــة القاضــي باحملكمــة الشــيخ‪ ... /‬برقــم ‪ 3425051‬وتاريــخ ‪1/27‬‬\n     ‫‪1434/‬ه ـ اخلــاص بدعــوى املدعــي العــام ض ـ ـ ـ ـ ــد ‪ - .... /‬مينــي اجلنســية ‪-‬‬\n     ‫يف قضيــة ( طعــن ) علــى الصفــة املوضحــة يف القــرار املتضمــن حكــم‬\n     ‫فضيلتــه مبــا هــو مــدون ومفصــل فيــه تقــررت املوافقــة علــى احلكــم واهلل‬\n                     ‫املوفــق وصلــى اهلل علــى نبينــا محمــد وآلــه وصحبــه وســلم ‪.‬‬\n\n\n\n\n‫‪51‬‬\n\f","legal_articles":[],"source_id":"831db040-0b05-5921-907d-640530e541d8","source_file_id":"a5087788-de05-5c48-8cd0-bd622f15e952","source_page_start":45,"source_page_end":51,"original_source":"وزارة العدل السعودية","acquisition_source":"official_ministry_download_preserved_in_central_archive","source_url":null,"content_hash":"88b84c6a6e15a83a03d2e3222ecfe46aff67283f6edfb1a8cfb41607d5145ba6","normalized_text_hash":"c9d7a714b4ae5ed9a4c91e532a0825bcf558e769f7f76809022fc8c46f64acdb","status":"review","review_status":"manual_field_review_pending","legal_search_eligibility":false,"legacy_id":"collector-1434-v23-p45-3425051"}]$archive_payload$::jsonb) AS x LIMIT 25
       )) AS document_files
